static std::string FeedbackUtcNow() {
    const auto now = std::chrono::system_clock::now();
    const std::time_t time = std::chrono::system_clock::to_time_t(now);
    struct tm utc = {};
    gmtime_s(&utc, &time);
    char buffer[32] = {};
    std::strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", &utc);
    return buffer;
}

static std::string FeedbackErrorText(const CueviFeedback::Result& result) {
    switch (result.error) {
    case CueviFeedback::Error::NotConfigured: return L(Feedback_ServiceNotConfigured);
    case CueviFeedback::Error::InvalidEndpoint: return L(Feedback_EndpointInvalid);
    case CueviFeedback::Error::Unauthorized: return L(Feedback_Unauthorized);
    case CueviFeedback::Error::RateLimited: return L(Feedback_RateLimited);
    case CueviFeedback::Error::Validation: return L(Feedback_Validation);
    case CueviFeedback::Error::Timeout: return L(Feedback_Timeout);
    case CueviFeedback::Error::MalformedResponse: return L(Feedback_MalformedResponse);
    case CueviFeedback::Error::Server: return L(Feedback_Server);
    case CueviFeedback::Error::Network: return L(Feedback_Network);
    case CueviFeedback::Error::None: break;
    }
    return result.detail.empty() ? std::string(L(Fb_SubmitFailed)) : result.detail;
}

