// PAL-owned append sink for lightweight performance diagnostics.  The runtime
// temp directory is portable across Windows/macOS/Linux and preserves the
// historical best-effort semantics when the file cannot be opened.
static bool AppendHarkenSearchPerfLogLine(const std::string& line) {
    const std::string tempDirectory = Platform::FileSystem::TemporaryDirectory();
    if (tempDirectory.empty()) return false;
    const std::string logPath =
        (std::filesystem::u8path(tempDirectory) / "auro_perf.log").u8string();
    return Platform::FileSystem::AppendFileText(logPath, line);
}

// DAW Bridge Installer state (AUR-P1-047)
// Thread-safe: install() runs on a detached worker thread; main thread reads.
// Using shared_ptr so the worker cannot write into freed memory if Aris closes
// while the install is in progress.
struct DawBridgeInstallSession {
    enum class Phase { Idle, Installing, Done };
    std::atomic<Phase>               phase{Phase::Idle};
    std::mutex                       resultMutex;
    HarkenSearch::DawBridge::InstallResult   result;
    std::string                      installerName; // display name shown in toast
    double                           doneSince = 0.0; // ImGui::GetTime() when done
};
