static std::mutex g_reaperBridgeUiStatusMutex;
static std::unordered_map<std::string, HarkenSearch::DawBridge::InstallStatus>
    g_reaperBridgeUiStatusCache;
static std::unordered_set<std::string> g_reaperAutoDetectRequests;

static std::string ReaperBridgeUiCacheKey(const DawTarget& target) {
    return target.name + "\n" + target.exePath + "\n" + target.processName;
}

static std::string ReaperAutoDetectRequestKey(const DawTarget& target) {
    return ReaperBridgeUiCacheKey(target) + "\n" +
        std::to_string(static_cast<int>(target.mode)) + "\n" +
        (target.autoDetect ? "1" : "0");
}

static std::optional<HarkenSearch::DawBridge::InstallStatus>
ReaperBridgeUiStatusForTarget(const DawTarget& target) {
    std::lock_guard<std::mutex> lock(g_reaperBridgeUiStatusMutex);
    const auto found = g_reaperBridgeUiStatusCache.find(ReaperBridgeUiCacheKey(target));
    if (found == g_reaperBridgeUiStatusCache.end()) return std::nullopt;
    return found->second;
}

// H1b: DAW-send failure line rendered by the DAW toast. The send worker
// stores the keyed InstallStatus; DrawSendToDAWToast resolves it on the UI
