static std::string TrimLine(const std::string& s) {
    size_t a = 0;
    while (a < s.size() && (s[a] == ' ' || s[a] == '\t' || s[a] == '\r' || s[a] == '\n')) a++;
    size_t b = s.size();
    while (b > a && (s[b - 1] == ' ' || s[b - 1] == '\t' || s[b - 1] == '\r' || s[b - 1] == '\n')) b--;
    return s.substr(a, b - a);
}

static bool ParseBool(const std::string& v, bool defVal) {
    std::string s = v;
    std::transform(s.begin(), s.end(), s.begin(), ::tolower);
    if (s == "1" || s == "true" || s == "yes" || s == "on") return true;
    if (s == "0" || s == "false" || s == "no" || s == "off") return false;
    return defVal;
}

static int ParseInt(const std::string& v, int defVal) {
    try { return std::stoi(v); } catch (...) { return defVal; }
}

static float ParseFloat(const std::string& v, float defVal) {
    try { return std::stof(v); } catch (...) { return defVal; }
}

static bool LooksLikeUtf8AsAnsiMojibake(const std::string& value) {
    if (value.empty()) return false;
    // Detect settings text that was decoded through a legacy Chinese code page.

    static constexpr const char* kMarkers[] = {
        u8"\u934f", // 鍏
        u8"\u93c2", // 鏂
        u8"\u6b22", // 欢 after mojibake sequences
        u8"\u7f01", // 缁
        u8"\u714e", // 煎
        u8"\u608e", // 悎
        u8"\u6d93", // 涓
        u8"\u693d", // 椽
        u8"\u95ca", // 闊
    };
    for (const char* marker : kMarkers) {
        if (value.find(marker) != std::string::npos) return true;
    }
    return false;
}

static std::string RepairUtf8AsAnsiMojibakeForSettings(const std::string& value) {
    std::string repaired = value;
    // The platform helper verifies the round-trip before accepting a change,
    // so trying it for every settings value is safe for valid UTF-8. A small
    // bounded loop also repairs names that were encoded through the legacy
    // path more than once.
    for (int pass = 0; pass < 3; ++pass) {
        const std::string next = Platform::TextEncoding::RepairUtf8MojibakeFromCp936(repaired);
        if (next.empty() || next == repaired) break;
        repaired = next;
    }
    return repaired;
}

// A truncated settings write can concatenate the next tab field onto a tab
// name (for example: "name?tab0_viewMode=1"). Keep the parser tolerant of
// that historical corruption without changing valid user-entered tab names.
static size_t FindEmbeddedTabSettingsKey(const std::string& value) {
    constexpr const char* kViewModeSuffix = "_viewMode=";
    size_t searchFrom = 0;
    while (true) {
        const size_t suffixPos = value.find(kViewModeSuffix, searchFrom);
        if (suffixPos == std::string::npos) return std::string::npos;

        size_t digitsBegin = suffixPos;
        while (digitsBegin > 0 &&
               std::isdigit(static_cast<unsigned char>(value[digitsBegin - 1]))) {
            --digitsBegin;
        }
        if (digitsBegin >= 3 && value.compare(digitsBegin - 3, 3, "tab") == 0) {
            return digitsBegin - 3;
        }
        searchFrom = suffixPos + 1;
    }
}

static std::string SanitizeTabNameFromSettings(const std::string& rawValue) {
    std::string value = rawValue;
    const size_t embeddedKey = FindEmbeddedTabSettingsKey(value);
    if (embeddedKey != std::string::npos) {
        value.resize(embeddedKey);
        // A damaged line may leave a replacement/question marker directly
        // before the embedded key. It is a separator artifact, not a name.
        while (!value.empty() &&
               (value.back() == '?' || value.back() == '\r' || value.back() == '\n' ||
                value.back() == ' ' || value.back() == '\t')) {
            value.pop_back();
        }
    }
    value = RepairUtf8AsAnsiMojibakeForSettings(value);
    while (!value.empty() &&
           (value.front() == ' ' || value.front() == '\t' || value.front() == '\r' || value.front() == '\n')) {
        value.erase(value.begin());
    }
    while (!value.empty() &&
           (value.back() == ' ' || value.back() == '\t' || value.back() == '\r' || value.back() == '\n')) {
        value.pop_back();
    }
    const std::wstring wideValue = Platform::TextEncoding::Utf8ToWidePermissive(value);
    if (std::any_of(wideValue.begin(), wideValue.end(), [](wchar_t codePoint) {
            return codePoint >= 0xE000 && codePoint <= 0xF8FF;
        })) {
        // Private-use code points are the telltale result of the legacy tab
        // payload being decoded through the wrong code page. Let the caller
        // replace it with the localized default instead of exposing garbage.
        return {};
    }
    return value;
}

namespace fs = std::filesystem;
static fs::path Utf8ToPathMain(const std::string& str);

static std::unordered_map<std::string, std::string> LoadKeyValueFile(const std::string& pathUtf8) {
    std::unordered_map<std::string, std::string> kv;
    std::string contents;
    if (!Platform::FileSystem::ReadFileText(pathUtf8, contents)) return kv;
    std::istringstream in(contents);
    std::string line;
    while (std::getline(in, line)) {
        line = TrimLine(line);
        if (line.empty()) continue;
        if (line[0] == '#' || line[0] == ';') continue;
        size_t eq = line.find('=');
        if (eq == std::string::npos) continue;
        std::string k = TrimLine(line.substr(0, eq));
        std::string v = TrimLine(line.substr(eq + 1));
        if (!k.empty()) kv[k] = v;
    }
    return kv;
}

static bool SaveAppSettingsKeyValueFile(const std::string& pathUtf8, const std::vector<std::pair<std::string, std::string>>& items) {
    Platform::FileSystem::StreamWriter writer;
    if (!writer.Open(pathUtf8, false, true)) return false;
    bool written = writer.Write("# Aris settings (auto-generated)\n");
    for (const auto& it : items) {
        written = writer.Write(it.first) && written;
        written = writer.Write("=") && written;
        written = writer.Write(it.second) && written;
        written = writer.Write("\n") && written;
    }
    return written;
}

