static void LoadReleaseNotesFromExeDir(bool forceReload) {
    if (g_releaseNotesUiState.loadedOnce && !forceReload) {
        return;
    }

    g_releaseNotesUiState.loadedOnce = true;
    g_releaseNotesUiState.loadFailed = false;
    g_releaseNotesUiState.hasData = false;
    g_releaseNotesUiState.currentIndex = 0;
    g_releaseNotesUiState.message.clear();
    g_releaseNotesUiState.releases.clear();

    std::string notesPath = GetExeDirUtf8() + "\\" + kReleaseNotesFilename;
    std::string jsonText;
    if (!Platform::FileSystem::ReadFileText(notesPath, jsonText)) {
        // Silent compatibility read for release notes shipped before Aris was
        // established as the formal product identity.
        notesPath = GetExeDirUtf8() + "\\" + kLegacyReleaseNotesFilename;
        if (!Platform::FileSystem::ReadFileText(notesPath, jsonText)) {
            g_releaseNotesUiState.message.clear();
            return;
        }
    }
    if (jsonText.empty()) {
        g_releaseNotesUiState.message.clear();
        return;
    }

    g_releaseNotesUiState.hasData = aris::update::ParseHarkenSearchReleaseNotes(
        jsonText, g_releaseNotesUiState.releases);
    g_releaseNotesUiState.loadFailed = !g_releaseNotesUiState.hasData;
}

#if AURA_BUILD_DIAGNOSTICS
std::string ControlUpdateNoticeForQa(AppState& state, const std::string& action) {
    if (action == "open" || action == "history" || action == "reload") {
        LoadReleaseNotesFromExeDir(action == "reload");
        state.showUpdateCenter = true;
        if (action != "reload") g_releaseNotesUiState.showHistory = action == "history";
    } else if (action == "close") {
        aris::update::FinalizeHarkenSearchUpdateNoticeClose(state.showUpdateCenter, g_releaseNotesUiState);
        state.updateNoticeSeenThisSession = true;
    } else if (action != "state") {
        return R"({"ok":false,"error":"invalid_notice_action"})";
    }
    const auto qa = aris::update::GetHarkenSearchUpdateNoticeQaSnapshot();
    const auto update = aris::update::GetHarkenSearchUpdateUiState();
    return nlohmann::json({{"ok", true}, {"visible", state.showUpdateCenter},
        {"history", g_releaseNotesUiState.showHistory}, {"rendered_version", qa.version},
        {"items", qa.itemCount}, {"scroll_y", qa.scrollY}, {"scroll_max", qa.scrollMaxY},
        {"controls", qa.controls}, {"current_version", update.currentVersion},
        {"candidate_version", update.candidateVersion}, {"phase", static_cast<int>(update.phase)},
        {"downloaded_notes_bytes", update.candidateReleaseNotes.size()},
        {"notes_read_failed", update.candidateReleaseNotesFailed},
        {"local_history_count", g_releaseNotesUiState.releases.size()}}).dump();
}
#endif

static bool IsSendToDawSuccessStatus(const std::string& status) {
    // "Created new track" is a legit success outcome (fallback), not a failure.
    // "Spotted N clips on ..." is the mid/modern success message.
    return (status.size() >= 4 && status.compare(0, 4, "Sent") == 0) ||
           status.compare(0, 7, "Spotted") == 0 ||
           status.compare(0, 17, "Created new track") == 0;
}

// Toast for Send-to-DAW status (above DAW capsule, right-aligned; 3s hold + 0.5s fade)
static void DrawSendToDAWToast(AppState& state, float dawX, float dawY, float dawW, float dawH) {
    const bool isSending = state.dawSendState.load() == AppState::DawSendState::Sending;

    // H2a: take ONE locked snapshot of the worker-written trio. While
    // isSending we don't need the payload (progress atomics cover the UI),
    // but lastSendToDAWStatus may still be mid-refresh by a finished lane;
    // the snapshot keeps every read below internally consistent.
    std::string statusSnap;
    bool keyedSnap = false;
    HarkenSearch::DawBridge::InstallStatus bridgeSnap;
    {
        std::lock_guard<std::mutex> lkStat(g_lastSendToDAWStatusMutex);
        keyedSnap = state.lastSendToDAWKeyed;
        statusSnap = state.lastSendToDAWStatus;
        if (keyedSnap) bridgeSnap = g_lastSendToDAWBridgeStatus;
    }

    if (!isSending && statusSnap.empty() && !keyedSnap)
        return;

    float alpha = 1.0f;

    if (!isSending) {
        const double elapsed = ImGui::GetTime() - state.lastSendToDAWTime;
        if (elapsed > 3.5) {
            auto expected = AppState::DawSendState::Done;
            state.dawSendState.compare_exchange_strong(expected, AppState::DawSendState::Idle);
            return;
        }
        if (elapsed > 3.0)
            alpha = static_cast<float>(std::max(0.0, 1.0 - (elapsed - 3.0) / 0.5));
    }

    std::string display;
    bool success;

    if (isSending) {
        int sent = state.dawSendSent.load();
        int total = state.dawSendTotal.load();
        if (total > 1) {
            char buf[64];
            snprintf(buf, sizeof(buf), "Sending %d/%d ...", sent, total);
            display = buf;
        } else {
            display = "Sending...";
        }
        success = true;
    } else if (keyedSnap) {
        // H1b/H2a: render the snapshotted keyed bridge status here (UI thread).
        display = bridgeSnap.detail.Render();
        if (!bridgeSnap.remediation.empty()) {
            if (!display.empty()) display += " ";
            display += bridgeSnap.remediation.Render();
        }
    } else {
        display = statusSnap;
        if (IsSendToDawSuccessStatus(display)) {
            success = true;
            int& idx = state.selectedDAWIndex;
            auto& tgts = state.settings.dawTargets;
            const char* dawName = (idx >= 0 && idx < (int)tgts.size()) ? tgts[idx].name.c_str() : "DAW";
            int total = state.dawSendTotal.load();
            char buf[128];
            if (total > 1)
                snprintf(buf, sizeof(buf), "Sent %d files to %s", total, dawName);
            else
                snprintf(buf, sizeof(buf), "Sent to %s", dawName);
            display = buf;
        } else {
            success = false;
            const size_t kMaxDisplay = 60;
            if (display.size() > kMaxDisplay) {
                display.resize(kMaxDisplay - 3);
                display += "...";
            }
            display = "X " + display;
        }
    }

    ImDrawList* dl = ImGui::GetWindowDrawList();
    const ImVec2 textSize = ImGui::CalcTextSize(display.c_str());
    const float iconW = 18.0f;
    const float padX = 10.0f;
    const float padY = 5.0f;
    const float gapAbove = 6.0f;
    const float rectW = iconW + textSize.x + padX * 2.0f;
    const float rectH = textSize.y + padY * 2.0f;
    const float toastRight = dawX + dawW;
    const float toastX = toastRight - rectW;
    const float toastY = dawY - gapAbove - rectH;

    const ImU32 greenCol = ImGui::GetColorU32(ImVec4(0.30f, 0.82f, 0.45f, alpha));
    const ImU32 redCol   = ImGui::GetColorU32(ImVec4(0.90f, 0.35f, 0.30f, alpha));
    const ImU32 textCol  = success ? greenCol : redCol;
    const ImU32 bgCol    = ImGui::GetColorU32(ImVec4(0.06f, 0.06f, 0.08f, 0.88f * alpha));
    const ImU32 borderCol = ImGui::GetColorU32(ImVec4(
        success ? 0.20f : 0.40f,
        success ? 0.50f : 0.15f,
        success ? 0.25f : 0.12f,
        0.40f * alpha));

    const ImVec2 r0(toastX, toastY);
    const ImVec2 r1(toastX + rectW, toastY + rectH);
    dl->AddRectFilled(r0, r1, bgCol, 6.0f);
    dl->AddRect(r0, r1, borderCol, 6.0f);
    dl->AddText(ImVec2(toastX + padX, toastY + padY), textCol, display.c_str());
}

static bool ResolveUserDefaultConfigPaths(std::string& outSettingsPath, std::string& outImguiPath) {
    const std::string exeDirUtf8 = GetExeDirUtf8();
    std::string appDataRoot = Platform::GetAppDataDir();
    if (!appDataRoot.empty() && appDataRoot != ".") {
        Platform::FileSystem::CreateDirectories(appDataRoot);
#ifdef _WIN32
        outSettingsPath = appDataRoot + "\\settings.ini";
        outImguiPath = appDataRoot + "\\imgui.ini";
#else
        outSettingsPath = appDataRoot + "/settings.ini";
        outImguiPath = appDataRoot + "/imgui.ini";
#endif
        return true;
    }
#ifdef _WIN32
    outSettingsPath = exeDirUtf8 + "\\settings.ini";
    outImguiPath = exeDirUtf8 + "\\imgui.ini";
#else
    outSettingsPath = exeDirUtf8 + "/settings.ini";
    outImguiPath = exeDirUtf8 + "/imgui.ini";
#endif
    return false;
}

static bool PublishCurrentDevConfigToUserDefaults(const AppState& state, std::string* outMessage) {
#if AURA_INTERNAL_BETA
    // 内测版：此函数的入口按钮已在设置面板中被剥离；留空实现以保证无字符串残留
    (void)state;
    if (outMessage) *outMessage = "";
    return false;
#else
    if (g_appSettingsPathUtf8.empty() || g_imguiIniPathUtf8.empty()) {
        if (outMessage) *outMessage = L(Dev_ConfigEmpty);
        return false;
    }

    const std::string exeDirUtf8 = GetExeDirUtf8();
    const bool isDevMode = PathExistsUtf8(exeDirUtf8 + "\\dev_mode.txt");
    if (!isDevMode) {
        if (outMessage) *outMessage = L(Dev_DevModeOnly);
        return false;
    }

    SaveAppSettings(state);
    ImGui::SaveIniSettingsToDisk(g_imguiIniPathUtf8.c_str());

    std::string userSettingsPath;
    std::string userImguiPath;
    ResolveUserDefaultConfigPaths(userSettingsPath, userImguiPath);

    const fs::path userSettingsFs = Utf8ToPathMain(userSettingsPath);
    Platform::FileSystem::CreateDirectories(PathToUtf8Main(userSettingsFs.parent_path()));
    std::string copyError;
    if (!Platform::FileSystem::CopyFile(
            g_appSettingsPathUtf8, userSettingsPath, true, &copyError)) {
        if (outMessage) *outMessage = u8"发布 settings.ini 失败: " + copyError;
        return false;
    }

    if (!Platform::FileSystem::CopyFile(
            g_imguiIniPathUtf8, userImguiPath, true, &copyError)) {
        if (outMessage) *outMessage = u8"发布 imgui.ini 失败: " + copyError;
        return false;
    }

    if (outMessage) *outMessage = L(Dev_PublishSuccess);
    return true;
#endif  // AURA_INTERNAL_BETA
}

