// Search filter signature (avoid repeated identical queries)

static uint64_t HashString64Local(const std::string& s) {
    uint64_t h = 1469598103934665603ull;
    for (unsigned char c : s) {
        h ^= (uint64_t)c;
        h *= 1099511628211ull;
    }
    return h;
}

static uint64_t HashCombine64(uint64_t h, uint64_t v) {
    return h ^ (v + 0x9e3779b97f4a7c15ull + (h << 6) + (h >> 2));
}

static uint64_t BuildSearchFilterSignature(const AppState& state, const SearchFilter& filter) {
    uint64_t h = 0;
    h = HashCombine64(h, (uint64_t)state.viewMode);
    h = HashCombine64(h, (uint64_t)state.selectedPlaylistId);
    h = HashCombine64(h, state.playlistAggregatedView ? 1ull : 0ull);
    h = HashCombine64(h, HashString64Local(filter.keyword));
    h = HashCombine64(h, HashString64Local(filter.category));
    h = HashCombine64(h, HashString64Local(filter.folderPath));
    h = HashCombine64(h, HashString64Local(filter.artist));
    h = HashCombine64(h, HashString64Local(filter.album));
    h = HashCombine64(h, HashString64Local(filter.format));
    h = HashCombine64(h, HashString64Local(filter.specificCoverKey));
    h = HashCombine64(h, (uint64_t)(filter.minDuration * 1000.0f + 0.5f));
    h = HashCombine64(h, (uint64_t)(filter.maxDuration * 1000.0f + 0.5f));
    h = HashCombine64(h, (uint64_t)filter.minSampleRate);
    h = HashCombine64(h, (uint64_t)filter.maxSampleRate);
    h = HashCombine64(h, (uint64_t)filter.channels);
    h = HashCombine64(h, (uint64_t)filter.minChannels);
    h = HashCombine64(h, (uint64_t)filter.maxChannels);
    h = HashCombine64(h, (uint64_t)filter.coverFilter);
    h = HashCombine64(h, (uint64_t)filter.includeOnlyKnownExts);
    for (const auto& ext : filter.excludeExtensions) {
        h = HashCombine64(h, HashString64Local(ext));
    }
    for (const auto& a : filter.artists) {
        h = HashCombine64(h, HashString64Local(a));
    }
    return h;
}

