static bool CopyCoverToClipboard(AppState& state, const std::string& audioFilePath, const std::string& folderHint = "") {
    if (audioFilePath.empty()) return false;

    auto setClipboardFromImageFile = [&](const std::string& imagePathUtf8) -> bool {
        if (imagePathUtf8.empty()) return false;
        std::vector<uint8_t> imgData;
        std::string mime;
        if (!MetadataWriter::loadImageFile(imagePathUtf8, imgData, mime) || imgData.empty()) return false;
        state.coverClipboardData = std::move(imgData);
        state.coverClipboardMimeType = aura::cover_batch::ResolveCoverImageMime(
            state.coverClipboardData, mime);
        return true;
    };

    // 1) 先尝试真正的内嵌封面
    AlbumArt art;
    if (MetadataReader::readAlbumArt(audioFilePath, art) && art.hasData()) {
        state.coverClipboardData = art.data;
        state.coverClipboardMimeType = aura::cover_batch::ResolveCoverImageMime(
            state.coverClipboardData, art.mimeType);
        return true;
    }

    // 2) 再尝试"音频同名 jpg/png/jpeg 侧边图"
    try {
        fs::path audioPath = Utf8ToPathMain(audioFilePath);
        fs::path parentDir = audioPath.parent_path();
        fs::path stem = audioPath.stem();
        if (!parentDir.empty() && !stem.empty()) {
            static const char* kImageExts[] = { ".jpg", ".jpeg", ".png" };
            for (const char* ext : kImageExts) {
                fs::path imgPath = parentDir / (stem.string() + ext);
                const std::string imgPathUtf8 = PathToUtf8Main(imgPath);
                const auto imageInfo = Platform::FileSystem::ProbeRegularFile(imgPathUtf8);
                if (imageInfo.isRegularFile) {
                    if (setClipboardFromImageFile(imgPathUtf8)) {
                        return true;
                    }
                }
            }
        }
    } catch (...) {
    }

    // 3) 最后再尝试文件夹封面
    std::string folder = folderHint;
    if (folder.empty()) {
        try {
            folder = PathToUtf8Main(Utf8ToPathMain(audioFilePath).parent_path());
        } catch (...) {
            folder.clear();
        }
    }
    if (!folder.empty()) {
        std::string coverImagePath;
        if (CoverModule::GetFolderCoverImagePath(folder, coverImagePath)) {
            if (setClipboardFromImageFile(coverImagePath)) {
                return true;
            }
        }
    }

    return false;
}

