// Menu item with stable hover styling.
// Menu item with stable selected styling.
bool MenuItemWithTooltip(const char* label, const char* shortcut, const char* tooltip, bool selected = false, bool enabled = true) {
    // Apply the menu palette before rendering the item.
    // Header 是 MenuItem 的背景，HeaderHovered 是鼠标划过时的高亮背景
    ImGui::PushStyleColor(ImGuiCol_Header, COLOR_SELECTED);
    ImGui::PushStyleColor(ImGuiCol_HeaderHovered, COLOR_ACCENT);

    // 执行原生 MenuItem 渲染
    bool clicked = ImGui::MenuItem(label, shortcut, selected, enabled);

    // 只有在悬停且有内容时才显示 Tooltip，并增加 DelayShort 防闪烁
    if (tooltip && tooltip[0] != '\0' && ImGui::IsItemHovered(ImGuiHoveredFlags_DelayShort)) {
        HarkenSearch::SetTooltip("%s", tooltip);
    }

    // 弹出样式，确保不污染后续其他 UI 组件
    ImGui::PopStyleColor(2);

    return clicked;
}

// F-022: Gated menu item — shows lock icon + edition tooltip when feature requires higher edition
static bool GatedMenuItem(const char* label, ProductEdition::Edition required, const char* shortcut = nullptr) {
    bool unlocked = static_cast<int>(ProductEdition::current()) >= static_cast<int>(required);
    if (!unlocked) {
        char gatedLabel[256];
        snprintf(gatedLabel, sizeof(gatedLabel), "[PRO] %s", label);
        ImGui::BeginDisabled();
        ImGui::MenuItem(gatedLabel, shortcut, false, false);
        ImGui::EndDisabled();
        if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled)) {
            const char* edName = ProductEdition::editionName(required);
            char tip[128];
            snprintf(tip, sizeof(tip), L(Misc_NeedVersionFmt), edName);
            HarkenSearch::SetTooltip("%s", tip);
        }
        return false;
    }
    return ImGui::MenuItem(label, shortcut);
}

// Keyboard Shortcuts Dispatch (焦点/输入拦截 + 按帧快照)

static bool NavigatePlaybackHistory(AppState& state, bool backward) {
    PlayHistoryItem* item = backward ? state.goBack() : state.goForward();
    if (!item || item->filePath.empty()) return false;

    state.audioEngine.stop();
    state.audioEngine.loadFileAsync(item->filePath, state.settings.autoplayOnSelect);
    ResetWaveformZoom(state);
    ScheduleDeferredWaveformDetail(state, item->filePath, AppState::WAVEFORM_DEFAULT_DETAIL_PEAKS);

    int matchIndex = -1;
    if (item->fileId > 0) {
        for (int i = 0; i < (int)state.searchResults.size(); ++i) {
            if (state.searchResults[(size_t)i].id == item->fileId) {
                matchIndex = i;
                break;
            }
        }
    }
    if (matchIndex < 0) {
        for (int i = 0; i < (int)state.searchResults.size(); ++i) {
            if (state.searchResults[(size_t)i].filePath == item->filePath) {
                matchIndex = i;
                break;
            }
        }
    }
    if (matchIndex >= 0) {
        state.selectedIndicesSet.clear();
        state.selectedIndicesSet.insert(matchIndex);
        state.beginAudioTargetFromSearchResult(matchIndex);
        state.lastClickedIndex = matchIndex;
        state.scrollToSelected = true;
    }

    state.syncToTab();
    return true;
}

