// SECTION 2 - Keybindings and Shortcuts

static void ProcessKeybindings(AppState& state) {
    // AUDITION_NATIVE_EXCEPTION: keyboard-transport
    // Keyboard play/stop intentionally retains its origin-specific region and
    // rewind policy during the overnight control-plane proof.
    // Level 0: 系统级 - 非前台窗口一律不响应
    if (g_hwnd == nullptr || GetForegroundWindow() != g_hwnd) return;

    ImGuiIO& io = ImGui::GetIO();

// Helper lambdas (定义在前，供全函数使用)

    struct KeySnapshot {
        ImGuiKey keys[64] = {};
        bool justPressed[64] = {};
        int keyCount = 0;
        bool keyCtrl = false;
        bool keyShift = false;
        bool keyAlt = false;
        bool anyItemActive = false;
    };

    auto CaptureKeySnapshot = [&]() -> KeySnapshot {
        KeySnapshot ks;

        auto pushUnique = [&](ImGuiKey key) {
            if (key == ImGuiKey_None) return;
            for (int i = 0; i < ks.keyCount; ++i) {
                if (ks.keys[i] == key) return;
            }
            if (ks.keyCount < (int)(sizeof(ks.keys) / sizeof(ks.keys[0]))) {
                ks.keys[ks.keyCount++] = key;
            }
        };

        for (int i = 0; i < SHORTCUT_COUNT; ++i) {
            const KeyBinding& kb = (g_shortcuts[i].customKey.key != ImGuiKey_None)
                                   ? g_shortcuts[i].customKey
                                   : g_shortcuts[i].defaultKey;
            pushUnique(kb.key);
        }
        pushUnique(ImGuiKey_A);
        pushUnique(ImGuiKey_UpArrow);
        pushUnique(ImGuiKey_DownArrow);
        pushUnique(ImGuiKey_LeftArrow);
        pushUnique(ImGuiKey_RightArrow);

        for (int i = 0; i < ks.keyCount; ++i) {
            ks.justPressed[i] = ImGui::IsKeyPressed(ks.keys[i], false);
        }

        ks.keyCtrl = io.KeyCtrl;
        ks.keyShift = io.KeyShift;
        ks.keyAlt = io.KeyAlt;
        ks.anyItemActive = ImGui::IsAnyItemActive();
        return ks;
    };

    auto IsKeyJustPressed = [](const KeySnapshot& ks, ImGuiKey key) -> bool {
        for (int i = 0; i < ks.keyCount; ++i) {
            if (ks.keys[i] == key) return ks.justPressed[i];
        }
        return false;
    };

    auto IsShortcutPressedSnapshot = [&](ShortcutAction action, const KeySnapshot& ks) -> bool {
        for (int i = 0; i < SHORTCUT_COUNT; ++i) {
            if (g_shortcuts[i].action != action) continue;
            const KeyBinding& kb = (g_shortcuts[i].customKey.key != ImGuiKey_None)
                                   ? g_shortcuts[i].customKey
                                   : g_shortcuts[i].defaultKey;
            if (kb.key == ImGuiKey_None) return false;
            if (!IsKeyJustPressed(ks, kb.key)) return false;
            if (kb.ctrl != ks.keyCtrl) return false;
            if (kb.shift != ks.keyShift) return false;
            if (kb.alt != ks.keyAlt) return false;
            return true;
        }
        return false;
    };

// Transport Play/Pause: 最高优先级
    // 只要不在文本输入框中，空格播放/暂停必须始终响应，
    // 即使列表行有键盘焦点（WantCaptureKeyboard=true）也不能被阻断。
    const KeySnapshot ks = CaptureKeySnapshot();

    // 列表 ↑/↓ 选曲若不与 g_shortcuts 中任一绑定撞车再处理，避免 Shift+↑/↓ 调 pitch 同时切条目、Alt+↑/↓ 与试听历史重复等
    auto ModifiersMatchAnyShortcutBindingForKey = [&](ImGuiKey arrow) -> bool {
        for (int i = 0; i < SHORTCUT_COUNT; ++i) {
            const KeyBinding& kb = (g_shortcuts[i].customKey.key != ImGuiKey_None)
                                   ? g_shortcuts[i].customKey
                                   : g_shortcuts[i].defaultKey;
            if (kb.key != arrow || kb.key == ImGuiKey_None) continue;
            if (kb.ctrl == ks.keyCtrl && kb.shift == ks.keyShift && kb.alt == ks.keyAlt)
                return true;
        }
        return false;
    };

    bool playPauseHandled = false;
    if (!io.WantTextInput && IsShortcutPressedSnapshot(ShortcutAction::PlayPause, ks)) {
        const bool wasPlaying = state.audioEngine.isPlaying();
        if (wasPlaying) {
            state.audioEngine.pause();
        } else {
            const float inPt = state.audioEngine.getInPoint();
            const float outPt = state.audioEngine.getOutPoint();
            const bool hasRegion = (inPt < outPt) && (inPt > 0.0f || outPt < 1.0f);
            if (hasRegion) {
                state.audioEngine.playRegion(state.uiState.regionLoopEnabled,
                    state.uiState.regionFadeInNorm, state.uiState.regionFadeOutNorm);
            } else {
                state.audioEngine.play();
            }
        }
        UA_LOG(UACategory::Play, wasPlaying ? "Pause (Space)" : "Play (Space)");
        playPauseHandled = true;
    }

    // Dismiss search suggest popup when playback starts (any trigger)
    if (state.audioEngine.isPlaying() && state.searchSuggestPopupOpen) {
        state.searchSuggestPopupOpen = false;
        state.searchSuggestCandidates.clear();
        state.searchSuggestSelected = -1;
        state.searchSuggestUserSelected = false;
    }

    // Ctrl+F always routes focus to search.
    if (IsShortcutPressedSnapshot(ShortcutAction::FocusSearch, ks)) {
        state.focusSearchBar = true;
    }

    // Ctrl+Alt+C = copy file path(s) to clipboard
    if (!io.WantTextInput && ks.keyCtrl && !ks.keyShift && ks.keyAlt) {
        if (ImGui::IsKeyPressed(ImGuiKey_C, false)) {
            if (state.viewMode == ViewMode::Browser) {
                const std::string browserPaths = BuildBrowserSelectedAudioPaths(state);
                if (!browserPaths.empty()) {
                    ImGui::SetClipboardText(browserPaths.c_str());
                }
            } else {
                const bool canUse =
                    (state.viewMode == ViewMode::Database ||
                     state.viewMode == ViewMode::Playlist ||
                     state.viewMode == ViewMode::PlaylistLibrary) &&
                    !state.searchResults.empty();
                if (canUse) {
                    if (!state.selectedIndicesSet.empty()) {
                        std::string allPaths;
                        for (int idx : state.selectedIndicesSet) {
                            if (idx >= 0 && idx < (int)state.searchResults.size()) {
                                if (!allPaths.empty()) allPaths += "\n";
                                allPaths += state.searchResults[idx].filePath;
                            }
                        }
                        if (!allPaths.empty()) ImGui::SetClipboardText(allPaths.c_str());
                    } else if (state.selectedResultIndex >= 0 && state.selectedResultIndex < (int)state.searchResults.size()) {
                        ImGui::SetClipboardText(state.searchResults[state.selectedResultIndex].filePath.c_str());
                    }
                }
            }
        }
    }

    // Ctrl+Shift+C = copy cover, Ctrl+Shift+V = paste cover
    if (!io.WantTextInput && ks.keyCtrl && ks.keyShift && !ks.keyAlt) {
        const bool canUseDbSelection =
            (state.viewMode == ViewMode::Database ||
             state.viewMode == ViewMode::Playlist ||
             state.viewMode == ViewMode::PlaylistLibrary) &&
            !state.searchResults.empty();

        if (ImGui::IsKeyPressed(ImGuiKey_C, false)) {
            if (!canUseDbSelection) {
                ShowCoverClipboardMessage(Lw(CoverClip_CopyNoView).c_str(), MB_ICONWARNING);
            } else {
                int idx = state.selectedResultIndex;
                if (idx < 0 || idx >= (int)state.searchResults.size()) {
                    if (!state.selectedIndicesSet.empty()) idx = *state.selectedIndicesSet.begin();
                }

                if (idx >= 0 && idx < (int)state.searchResults.size()) {
                    const auto& rec = state.searchResults[idx];
                    if (CopyCoverToClipboard(state, rec.filePath, rec.folderPath)) {
                        ShowCoverClipboardMessage(Lw(CoverClip_Copied).c_str(), MB_ICONINFORMATION);
                    } else {
                        ShowCoverClipboardMessage(Lw(CoverClip_CopyFail).c_str(), MB_ICONWARNING);
                    }
                } else {
                    ShowCoverClipboardMessage(Lw(CoverClip_CopySelect).c_str(), MB_ICONWARNING);
                }
            }
        }

        if (ImGui::IsKeyPressed(ImGuiKey_V, false)) {
            if (!canUseDbSelection) {
                ShowCoverClipboardMessage(Lw(CoverClip_PasteNoView).c_str(), MB_ICONWARNING);
            } else if (!state.hasCoverClipboard()) {
                ShowCoverClipboardMessage(Lw(CoverClip_NoPasteData).c_str(), MB_ICONWARNING);
            } else {
                std::vector<std::string> targets;
                if (!state.selectedIndicesSet.empty()) {
                    targets.reserve(state.selectedIndicesSet.size());
                    for (int idx : state.selectedIndicesSet) {
                        if (idx >= 0 && idx < (int)state.searchResults.size()) {
                            targets.push_back(state.searchResults[idx].filePath);
                        }
                    }
                } else if (state.selectedResultIndex >= 0 && state.selectedResultIndex < (int)state.searchResults.size()) {
                    targets.push_back(state.searchResults[state.selectedResultIndex].filePath);
                }

                if (!targets.empty()) {
                    StartCoverBatchPaste(state, targets);
                } else {
                    ShowCoverClipboardMessage(Lw(CoverClip_PasteSelect).c_str(), MB_ICONWARNING);
                }
            }
        }
    }

    // Level 1: 控件级 - 仅在文本输入时拦截快捷键。
    // 注意：WantCaptureKeyboard 在列表/表格/组合框等场景常年为 true，
    // 若用于全局拦截会导致"所有快捷键失效"。
    if (io.WantTextInput) return;

    // Level 2: 焦点级 - ImGui 窗口未聚焦不处理
    if (!ImGui::IsWindowFocused(ImGuiFocusedFlags_AnyWindow)) return;

    const bool allowUiShortcuts = !ks.anyItemActive;
    const bool allowDbActions = !state.isScanning.load();

    bool historyNavConsumed = false;
    if (allowUiShortcuts) {
        // Transport
        if (!playPauseHandled && IsShortcutPressedSnapshot(ShortcutAction::PlayPause, ks)) {
            if (state.audioEngine.isPlaying()) {
                state.audioEngine.pause();
            } else {
                const float inPt = state.audioEngine.getInPoint();
                const float outPt = state.audioEngine.getOutPoint();
                const bool hasRegion = (inPt < outPt) && (inPt > 0.0f || outPt < 1.0f);
                if (hasRegion) {
                    state.audioEngine.playRegion(state.uiState.regionLoopEnabled,
                        state.uiState.regionFadeInNorm, state.uiState.regionFadeOutNorm);
                } else {
                    state.audioEngine.play();
                }
            }
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::Stop, ks)) {
            state.audioEngine.stop();
            state.audioEngine.seekToPosition(0.0f);
            UA_LOG(UACategory::Play, "Stop");
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::Rewind, ks)) {
            float pos = state.audioEngine.getPlaybackPosition();
            state.audioEngine.seekToPosition(std::max(0.0f, pos - 0.05f));
            UA_LOG(UACategory::Seek, "Rewind -5%");
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::FastForward, ks)) {
            float pos = state.audioEngine.getPlaybackPosition();
            state.audioEngine.seekToPosition(std::min(1.0f, pos + 0.05f));
            UA_LOG(UACategory::Seek, "FastForward +5%");
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::SkipToStart, ks)) {
            state.audioEngine.seekToPosition(0.0f);
            UA_LOG(UACategory::Seek, "SkipToStart");
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::SkipToEnd, ks)) {
            state.audioEngine.seekToPosition(1.0f);
            UA_LOG(UACategory::Seek, "SkipToEnd");
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::PlayRegion, ks)) {
            float inPt = state.audioEngine.getInPoint();
            float outPt = state.audioEngine.getOutPoint();
            if (inPt < outPt) {
                state.audioEngine.playRegion(
                    state.uiState.regionLoopEnabled,
                    state.uiState.regionFadeInNorm,
                    state.uiState.regionFadeOutNorm);
                UA_LOG(UACategory::Play, "PlayRegion");
            }
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::SetInPoint, ks)) {
            state.audioEngine.setInPoint(state.audioEngine.getPlaybackPosition());
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::SetOutPoint, ks)) {
            state.audioEngine.setOutPoint(state.audioEngine.getPlaybackPosition());
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::ClearInOut, ks)) {
            state.audioEngine.clearInOutPoints();
            aura::waveform::ResetRegionEditor(state.uiState, false);
        }

        // Execute waveform and channel shortcuts before general actions.
        if (IsShortcutPressedSnapshot(ShortcutAction::ToggleReverse, ks)) {
            bool wasReversed = state.audioEngine.isReversed();
            const bool reverseApplied = state.audioEngine.setReverse(!wasReversed);
            const bool nowReversed = state.audioEngine.isReversed();
            if (!wasReversed && !nowReversed) {
                // 想倒放却没能真正进入倒放（超长/解码失败）：给中文原因，且不镜像选区，避免假成功。
                state.loadErrorToast = L(Player_ReverseFailed);
                state.loadErrorToastUntil = ImGui::GetTime() + 4.0;
            } else if (reverseApplied && state.audioEngine.isLoaded()) {
                float inPt = state.audioEngine.getInPoint();
                float outPt = state.audioEngine.getOutPoint();
                if ((inPt > 0.0f || outPt < 1.0f) && inPt < outPt) {
                    float newIn = 1.0f - outPt;
                    float newOut = 1.0f - inPt;
                    state.audioEngine.clearInOutPoints();
                    state.audioEngine.setInPoint(newIn);
                    state.audioEngine.setOutPoint(newOut);
                    state.audioEngine.seekToPosition(newIn);
                    if (!state.audioEngine.isPlaying()) state.audioEngine.play();
                } else {
                    float curPos = state.audioEngine.getPlaybackPosition();
                    state.audioEngine.seekToPosition(1.0f - curPos);
                    if (!state.audioEngine.isPlaying()) state.audioEngine.play();
                }
            }
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::ToggleMono, ks)) {
            state.audioEngine.setMono(!state.audioEngine.isMono());
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::ToggleSoloL, ks)) {
            int current = state.audioEngine.getChannelSolo();
            state.audioEngine.setChannelSolo(current == 1 ? 0 : 1);
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::ToggleSoloR, ks)) {
            int current = state.audioEngine.getChannelSolo();
            state.audioEngine.setChannelSolo(current == 2 ? 0 : 2);
        }

        // Pitch
        if (IsShortcutPressedSnapshot(ShortcutAction::PitchUp, ks)) {
            state.audioEngine.setPitch(state.audioEngine.getPitch() + 1.0f);
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::PitchDown, ks)) {
            state.audioEngine.setPitch(state.audioEngine.getPitch() - 1.0f);
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::PitchReset, ks)) {
            state.audioEngine.setPitch(0.0f);
        }

        if (IsShortcutPressedSnapshot(ShortcutAction::PrevFile, ks)) {
            historyNavConsumed = NavigatePlaybackHistory(state, true);
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::NextFile, ks)) {
            historyNavConsumed = NavigatePlaybackHistory(state, false) || historyNavConsumed;
        }

        // Edit / DB actions (scan 中静默拦截)
        if (allowDbActions) {
            if (IsShortcutPressedSnapshot(ShortcutAction::EditFilename, ks)) {
                if (state.viewMode != ViewMode::Browser && state.selectedResultIndex >= 0 &&
                    state.selectedResultIndex < (int)state.searchResults.size()) {
                    const auto& record = state.searchResults[state.selectedResultIndex];
                    state.showEditFilenameDialog = true;
                    state.editFilenameRecordId = record.id;
                    state.editFilenameOriginalPath = record.filePath;
                    strncpy_s(state.editFilenameBuffer, sizeof(state.editFilenameBuffer), record.fileName.c_str(), _TRUNCATE);
                }
            }
            if (IsShortcutPressedSnapshot(ShortcutAction::RevealInExplorer, ks)) {
                if (state.viewMode != ViewMode::Browser && state.selectedResultIndex >= 0 &&
                    state.selectedResultIndex < (int)state.searchResults.size()) {
                    const auto& record = state.searchResults[state.selectedResultIndex];
                    RevealFileInExplorer(record.filePath);
                }
            }
            if (IsShortcutPressedSnapshot(ShortcutAction::Delete, ks)) {
                if (state.viewMode != ViewMode::Browser) {
                    auto selectedRecords = state.getSelectedRecords();
                    if (selectedRecords.empty() && state.selectedResultIndex >= 0 &&
                        state.selectedResultIndex < (int)state.searchResults.size()) {
                        selectedRecords.push_back(state.searchResults[state.selectedResultIndex]);
                    }
                    if (!selectedRecords.empty()) {
                        state.pendingDeleteIds.clear();
                        state.pendingDeletePaths.clear();
                        for (const auto& r : selectedRecords) {
                            state.pendingDeleteIds.push_back(r.id);
                            state.pendingDeletePaths.push_back(r.filePath);
                        }
                        state.deleteFromFileSystem = io.KeyShift;
                        state.showDeleteConfirmDialog = true;
                    }
                }
            }
            if (IsShortcutPressedSnapshot(ShortcutAction::BatchRename, ks)) {
                // Resolve selection through getSelectedRecords so virtual select-all is honored.
                auto selectedRecords = state.getSelectedRecords();
                if (state.viewMode != ViewMode::Browser && selectedRecords.size() > 1) {
                    state.showBatchRenameDialog = true;
                    state.renameRuleQueue.clear();
                    state.renamePreviewList.clear();
                }
            }
            if (IsShortcutPressedSnapshot(ShortcutAction::ClearSelection, ks)) {
                state.clearSelection();
            }

            // View
            if (IsShortcutPressedSnapshot(ShortcutAction::Refresh, ks)) {
                state.fileBrowser.refresh();
                if (state.viewMode == ViewMode::Database) {
                    ClearAllFiltersForShowAll(state);
                    aura::cover_wall::RequestDatabaseRefreshForExplicitRetry(state);
                    state.suppressFacetsForNextRefresh = true;
                    RefreshSearchResults(state, true);
                    state.syncToTab();
                } else if (IsPlaylistSystemView(state.viewMode)) {
                    RefreshSearchResults(state, true);
                    state.syncToTab();
                }
            }
            // Send to DAW (Ctrl+Shift+1/2/3/4)
            if (IsShortcutPressedSnapshot(ShortcutAction::SendToDAW1, ks)) SendToDAW(state, 0);
            if (IsShortcutPressedSnapshot(ShortcutAction::SendToDAW2, ks)) SendToDAW(state, 1);
            if (IsShortcutPressedSnapshot(ShortcutAction::SendToDAW3, ks)) SendToDAW(state, 2);
            if (IsShortcutPressedSnapshot(ShortcutAction::SendToDAW4, ks)) SendToDAW(state, 3);
            if (!io.WantTextInput && IsShortcutPressedSnapshot(ShortcutAction::SpotToDAW, ks)) SendToDAW(state, state.selectedDAWIndex);

            // Ctrl+Z: Global Undo (F-025)
            if (!io.WantTextInput &&
                io.KeyCtrl && !io.KeyShift && !io.KeyAlt &&
                ImGui::IsKeyPressed(ImGuiKey_Z, false)) {
                if (state.undoStack.canUndo()) {
                    state.undoStack.undo(state.database);
                    g_forceMetaCacheInvalidate = true;
                    RefreshSearchResults(state, true);
                }
            }
            // Ctrl+Y / Ctrl+Shift+Z: Global Redo
            if (!io.WantTextInput &&
                io.KeyCtrl && !io.KeyAlt &&
                (ImGui::IsKeyPressed(ImGuiKey_Y, false) ||
                 (io.KeyShift && ImGui::IsKeyPressed(ImGuiKey_Z, false)))) {
                if (state.undoStack.canRedo()) {
                    state.undoStack.redo(state.database);
                    g_forceMetaCacheInvalidate = true;
                    RefreshSearchResults(state, true);
                }
            }
            // Ctrl+N: New Database
            if (!io.WantTextInput &&
                io.KeyCtrl && !io.KeyShift && !io.KeyAlt &&
                ImGui::IsKeyPressed(ImGuiKey_N, false)) {
                state.showNewDbDialog = true;
            }
#ifdef _WIN32
            // Ctrl+O: Open Database
            if (!io.WantTextInput &&
                io.KeyCtrl && !io.KeyShift && !io.KeyAlt &&
                ImGui::IsKeyPressed(ImGuiKey_O, false)) {
                std::string p = Platform::DatabaseDialogs::OpenDatabaseFileDialogUtf8(g_hwnd);
                if (!p.empty()) {
                    SwitchDatabase(state, p);
                }
            }
#endif
            // Ctrl+Shift+T: Reopen closed Tab (moved from Ctrl+Z)
            if (!io.WantTextInput &&
                io.KeyCtrl && io.KeyShift && !io.KeyAlt &&
                ImGui::IsKeyPressed(ImGuiKey_T, false)) {
                int restored = state.reopenClosedTab();
                if (restored >= 0 && state.activateTab(restored, ImGui::GetTime())) {
                    RefreshSearchResults(state, true);
                }
            }
        }
    }

    // Keep the backing selection in sync for drag and context-menu actions.
    if (allowDbActions && allowUiShortcuts && IsKeyJustPressed(ks, ImGuiKey_A) && ks.keyCtrl) {
        if (state.viewMode == ViewMode::Browser) {
            const auto& entries = state.fileBrowser.activeEntries();
            state.browserSelectedIndicesSet.clear();
            for (int i = 0; i < (int)entries.size(); ++i)
                state.browserSelectedIndicesSet.insert(i);
            if (!entries.empty())
                state.browserLastClickedIndex = 0;
            DIAG_ACTION("UI", "Browser All-Select Executed");
        } else if (!state.searchResults.empty()) {
            state.selectedIndicesSet.clear();
            // 真实物理填充，保障所有下游功能 (拖拽/批量封面/右键) 正常运作
            for (int i = 0; i < (int)state.searchResults.size(); ++i) {
                state.selectedIndicesSet.insert(i);
            }
            state.lastClickedIndex = 0;
            state.selectedResultIndex = 0;
            state.allSelected = true;
            state.syncToTab(); // 同步到 Tab
            DIAG_ACTION("UI", "Physical All-Select Executed");
        }
    }

    // Up/Down arrows - Navigate and play files in database view
    const bool allowResultArrowNavigation =
        allowUiShortcuts || (g_searchBarFocusedForShortcuts && !state.searchSuggestPopupOpen);

    if (allowResultArrowNavigation && !historyNavConsumed &&
        state.viewMode != ViewMode::Browser && !state.searchResults.empty()) {
        bool moved = false;
        int newIndex = state.selectedResultIndex;

        if (IsKeyJustPressed(ks, ImGuiKey_UpArrow) && !ModifiersMatchAnyShortcutBindingForKey(ImGuiKey_UpArrow)) {
            if (newIndex > 0) {
                newIndex--;
                moved = true;
            } else if (newIndex < 0 && !state.searchResults.empty()) {
                newIndex = 0;
                moved = true;
            }
        }

        if (IsKeyJustPressed(ks, ImGuiKey_DownArrow) && !ModifiersMatchAnyShortcutBindingForKey(ImGuiKey_DownArrow)) {
            if (newIndex < (int)state.searchResults.size() - 1) {
                newIndex++;
                moved = true;
            } else if (newIndex < 0 && !state.searchResults.empty()) {
                newIndex = 0;
                moved = true;
            }
        }

        if (moved && newIndex >= 0 && newIndex < (int)state.searchResults.size()) {
            state.audioEngine.stop();
            state.selectedIndicesSet.clear();
            state.selectedIndicesSet.insert(newIndex);
            state.beginAudioTargetFromSearchResult(newIndex);
            state.lastClickedIndex = newIndex;
            state.scrollToSelected = true;

            const auto& record = state.searchResults[newIndex];
            UA_LOG_FMT(UACategory::Select, "Arrow #%d \"%s\"", newIndex, record.fileName.c_str());
            state.lastSelectionOrLoadTime = ImGui::GetTime();
            state.audioEngine.loadFileAsync(record.filePath, state.settings.autoplayOnSelect);
            ResetWaveformZoom(state);
            if (state.settings.autoplayOnSelect)
                MarkFilePlayed(state, record.filePath, record.id);
            ScheduleDeferredWaveformDetail(state, record.filePath, AppState::WAVEFORM_DEFAULT_DETAIL_PEAKS);
            state.syncToTab();
        }
    }

    // BPM Detection shortcuts (music mode only)
    if (!io.WantTextInput &&
        (state.settings.productMode == ProductMode::Music)) {
        auto SubmitBpmDetectKB = [&]() {
            if (!state.audioEngine.isLoaded()) return;
            ++state.bpmGeneration;
            state.pendingBpm.bpm         = 0.0f;
            state.pendingBpm.confidence  = 0.0f;
            state.pendingBpm.source      = 0;
            state.pendingBpm.isReady     = false;
            state.pendingBpm.isAnalyzing = true;
            state.pendingBpm.bubbleTimer = 0.0;

            std::string path = state.audioEngine.getLoadedFilePath();
            double startSec = 0.0, endSec = -1.0;
            float inPt  = state.audioEngine.getInPoint();
            float outPt = state.audioEngine.getOutPoint();
            float kbDur = state.audioEngine.getFileInfo().durationSeconds;
            if (inPt < outPt && inPt >= 0.0f && kbDur > 0.0f) {
                startSec = static_cast<double>(inPt) * kbDur;
                endSec   = static_cast<double>(outPt) * kbDur;
            }

            MusicAnalysisRequest req;
            req.fileId     = state.currentFileId;
            req.filePath   = path;
            req.priority   = AnalysisPriority::P0;
            req.generation = state.bpmGeneration;
            req.startSec   = startSec;
            req.endSec     = endSec;
            state.musicAnalyzer.submit(req);
        };

        if (IsShortcutPressedSnapshot(ShortcutAction::DetectBpm, ks)) {
            DIAG_ACTION("Music", "DetectBpmShortcut");
            SubmitBpmDetectKB();
        }
        if (IsShortcutPressedSnapshot(ShortcutAction::TapTempo, ks)) {
            DIAG_ACTION("Music", "TapTempoShortcut");
            state.tapTempo.tap();
            if (state.tapTempo.hasResult()) {
                int tapCount = state.tapTempo.tapCount();
                state.pendingBpm.bpm         = state.tapTempo.getBpm();
                state.pendingBpm.confidence  = std::min(1.0f,
                    0.4f + 0.06f * static_cast<float>(tapCount));
                state.pendingBpm.source      = static_cast<int>(MusicFieldSource::TapTempo);
                state.pendingBpm.isReady     = true;
                state.pendingBpm.isAnalyzing = false;
                state.pendingBpm.bubbleTimer = 0.0;
            }
        }
    }

    // Shift+Right/Left - Random file navigation (classic library layout)
    if (allowUiShortcuts && state.viewMode != ViewMode::Browser && !state.searchResults.empty() && ks.keyShift) {
        if (IsKeyJustPressed(ks, ImGuiKey_RightArrow) || IsKeyJustPressed(ks, ImGuiKey_LeftArrow)) {
            std::random_device rd;
            std::mt19937 g(rd());
            std::uniform_int_distribution<int> dist(0, (int)state.searchResults.size() - 1);
            int randomIdx = dist(g);

            state.selectedIndicesSet.clear();
            state.selectedIndicesSet.insert(randomIdx);
            state.beginAudioTargetFromSearchResult(randomIdx);
            state.lastClickedIndex = randomIdx;

            const auto& record = state.searchResults[randomIdx];
            state.lastSelectionOrLoadTime = ImGui::GetTime();
            state.audioEngine.stop();
            state.audioEngine.loadFileAsync(record.filePath, state.settings.autoplayOnSelect);
            ScheduleDeferredWaveformDetail(state, record.filePath, AppState::WAVEFORM_DEFAULT_DETAIL_PEAKS);
            ResetWaveformZoom(state);
            if (state.settings.autoplayOnSelect)
                MarkFilePlayed(state, record.filePath, record.id);
            state.syncToTab();
        }
    }
}

