static std::string TrimCopy(std::string s) {
    auto isSpace = [](unsigned char c) { return c == ' ' || c == '\t' || c == '\r' || c == '\n'; };
    while (!s.empty() && isSpace((unsigned char)s.front())) s.erase(s.begin());
    while (!s.empty() && isSpace((unsigned char)s.back())) s.pop_back();
    return s;
}

static void AutoRenameTabBySearch(AppState& state, const std::string& searchText) {
    if (!state.settings.autoRenameTabBySearch) return;
    if (state.activeTabIndex < 0 || state.activeTabIndex >= (int)state.listTabs.size()) return;

    // Build display name: strip NOT prefixes so tab shows "hit" instead of "NOT hit"
    std::string displayName;
    std::istringstream iss(TrimCopy(searchText));
    std::string word;
    while (iss >> word) {
        std::string lower = word;
        std::transform(lower.begin(), lower.end(), lower.begin(), ::tolower);
        if (lower == "not") {
            std::string next;
            if (iss >> next) {
                if (!displayName.empty()) displayName += ' ';
                displayName += next;
            }
        } else {
            if (!displayName.empty()) displayName += ' ';
            displayName += word;
        }
    }
    state.listTabs[state.activeTabIndex].name = displayName.empty() ? L(Misc_AllFiles) : displayName;
}

static std::string SanitizeWindowsName(std::string name) {
    const std::string invalid = "<>:\"/\\|?*";
    for (char& c : name) {
        if (invalid.find(c) != std::string::npos) c = '_';
    }
    name = TrimCopy(name);
    while (!name.empty() && (name.back() == '.' || name.back() == ' ')) name.pop_back();
    if (name.empty()) name = "_";
    return name;
}

