// Unified popup typography / hierarchy helpers
// Shared vocabulary for all popups and modals so title / section / body text
// reads at a consistent rhythm. Reference: docs .impeccable.md "Keep hierarchy
// strict" — never let two levels look the same.

// Level 1: popup title. Bold font, primary text at full opacity, tight bottom gap.
static std::string fmtStr(const char* fmt, const char* a) {
    char b[1024];
    std::snprintf(b, sizeof(b), fmt, a);
    return b;
}
static std::string fmtStr(const char* fmt) { return fmt; }
static void PopupTitle(const char* text) {
    ImFont* bold = GetUIFontEmphasis();
    if (bold) ImGui::PushFont(bold);
    ImVec4 col = ImGui::GetStyle().Colors[ImGuiCol_Text];
    col.w = 1.0f;
    ImGui::PushStyleColor(ImGuiCol_Text, col);
    ImGui::TextUnformatted(text);
    ImGui::PopStyleColor();
    if (bold) ImGui::PopFont();
    ImGui::Dummy(ImVec2(0.0f, 2.0f));
}

// Level 2: section label above a control group. Muted, slightly smaller.
static void PopupSectionLabel(const char* text) {
    ImGui::SetWindowFontScale(0.88f);
    ImVec4 col = ImGui::GetStyle().Colors[ImGuiCol_TextDisabled];
    col.w = 0.85f;
    ImGui::PushStyleColor(ImGuiCol_Text, col);
    ImGui::TextUnformatted(text);
    ImGui::PopStyleColor();
    ImGui::SetWindowFontScale(1.0f);
}

// Subtle horizontal divider — half-opacity of the theme border, with tight gap below.
static void PopupDivider() {
    ImDrawList* dl = ImGui::GetWindowDrawList();
    if (!dl) return;
    ImVec2 p = ImGui::GetCursorScreenPos();
    const float w = ImGui::GetContentRegionAvail().x;
    ImVec4 borderCol = ImGui::GetStyle().Colors[ImGuiCol_Border];
    borderCol.w *= 0.5f;
    dl->AddLine(p, ImVec2(p.x + w, p.y), ImGui::GetColorU32(borderCol), 1.0f);
    ImGui::Dummy(ImVec2(0.0f, 3.0f));
}

// Level 3: muted body text (meta info, empty state, hints).
static void PopupMuted(const char* fmt, ...) {
    va_list args;
    va_start(args, fmt);
    ImGui::TextDisabledV(fmt, args);
    va_end(args);
}

static std::string StripFtsMarkers(const std::string& s);

static void ParseInlineHighlightMarkers(const std::string& s,
                                        std::string& plainText,
                                        std::vector<std::pair<size_t, size_t>>& highlightSpans) {
    plainText.clear();
    highlightSpans.clear();
    if (s.empty()) return;

    const char kStart = (char)1;
    const char kEnd = (char)2;
    bool inHighlight = false;
    size_t spanStart = 0;
    plainText.reserve(s.size());

    for (char c : s) {
        if (c == kStart) {
            if (!inHighlight) {
                spanStart = plainText.size();
                inHighlight = true;
            }
            continue;
        }
        if (c == kEnd) {
            if (inHighlight && plainText.size() > spanStart) {
                highlightSpans.emplace_back(spanStart, plainText.size());
            }
            inHighlight = false;
            continue;
        }
        plainText.push_back(c);
    }

    if (inHighlight && plainText.size() > spanStart) {
        highlightSpans.emplace_back(spanStart, plainText.size());
    }
}

static bool IsWrapBlank(char c) {
    return c == ' ' || c == '\t';
}

// Keep highlighted snippets readable inside wrapped tooltips by rendering them as one
// wrap-aware block instead of multiple SameLine() text items.
static void RenderInlineHighlightedText(const std::string& s, const ImVec4& highlightColor) {
    (void)highlightColor;
    if (s.empty()) return;

    std::string plainSnippet;
    std::vector<std::pair<size_t, size_t>> highlightSpans;
    ParseInlineHighlightMarkers(s, plainSnippet, highlightSpans);
    if (plainSnippet.empty()) return;

    ImDrawList* drawList = ImGui::GetWindowDrawList();
    ImFont* font = ImGui::GetFont();
    const float fontSize = ImGui::GetFontSize();
    const ImVec2 startPos = ImGui::GetCursorScreenPos();
    const ImVec4 baseColor4 = ThemeColors::current().resultsText;
    const ImU32 textColor = ImGui::GetColorU32(baseColor4);
    const ImU32 highlightTextColor = textColor;
    const ImVec4 selectionColor = ThemeColors::current().resultsSelection;
    const ImVec4 highlightBg4 = ImVec4(selectionColor.x, selectionColor.y, selectionColor.z, 0.38f);
    const ImU32 highlightBgColor = ImGui::GetColorU32(highlightBg4);
    const float wrapWidth = (std::max)(ImGui::GetContentRegionAvail().x, fontSize * 8.0f);
    const float lineHeight = ImGui::GetTextLineHeightWithSpacing();
    const float highlightPadX = 2.0f;
    const float highlightPadY = 1.0f;

    const char* textBegin = plainSnippet.c_str();
    const char* textEnd = textBegin + plainSnippet.size();
    const char* lineStart = textBegin;
    float y = startPos.y;
    float maxLineWidth = 0.0f;

    while (lineStart < textEnd) {
        const char* lineEnd = font->CalcWordWrapPosition(fontSize, lineStart, textEnd, wrapWidth);
        if (lineEnd == lineStart) {
            lineEnd = lineStart + 1;
        }

        const size_t lineByteStart = static_cast<size_t>(lineStart - textBegin);
        const size_t lineByteEnd = static_cast<size_t>(lineEnd - textBegin);
        const ImVec2 lineSize = ImGui::CalcTextSize(lineStart, lineEnd, false, wrapWidth);
        maxLineWidth = (std::max)(maxLineWidth, lineSize.x);

        float x = startPos.x;
        size_t cursor = lineByteStart;
        for (const auto& span : highlightSpans) {
            const size_t spanStart = (std::max)(cursor, span.first);
            if (spanStart > lineByteEnd) break;

            const size_t plainEnd = (std::min)(lineByteEnd, span.first);
            if (plainEnd > cursor) {
                const char* segBegin = textBegin + cursor;
                const char* segEnd = textBegin + plainEnd;
                drawList->AddText(font, fontSize, ImVec2(x, y), textColor, segBegin, segEnd);
                x += ImGui::CalcTextSize(segBegin, segEnd).x;
                cursor = plainEnd;
            }

            const size_t hiEnd = (std::min)(lineByteEnd, span.second);
            if (hiEnd > spanStart) {
                const char* hiBegin = textBegin + spanStart;
                const char* hiTextEnd = textBegin + hiEnd;
                const ImVec2 hiSize = ImGui::CalcTextSize(hiBegin, hiTextEnd);
                const ImVec2 hiMin(x - highlightPadX, y - highlightPadY);
                const ImVec2 hiMax(x + hiSize.x + highlightPadX, y + fontSize + highlightPadY);
                drawList->AddRectFilled(hiMin, hiMax, highlightBgColor, 3.0f);
                drawList->AddText(font, fontSize, ImVec2(x, y), highlightTextColor, hiBegin, hiTextEnd);
                x += hiSize.x;
                cursor = hiEnd;
            }
        }

        if (cursor < lineByteEnd) {
            const char* segBegin = textBegin + cursor;
            const char* segEnd = textBegin + lineByteEnd;
            drawList->AddText(font, fontSize, ImVec2(x, y), textColor, segBegin, segEnd);
        }

        y += lineHeight;
        lineStart = lineEnd;
        if (lineStart < textEnd && *lineStart == '\n') {
            ++lineStart;
            continue;
        }
        while (lineStart < textEnd && IsWrapBlank(*lineStart)) {
            ++lineStart;
        }
    }

    ImGui::Dummy(ImVec2(maxLineWidth, (std::max)(lineHeight, y - startPos.y)));
}

static bool FindAsciiCaseInsensitiveSpan(const std::string& text, const std::string& query, size_t& outStart) {
    if (text.empty() || query.empty() || query.size() > text.size()) return false;

    auto isAscii = [](unsigned char c) -> bool {
        return c < 0x80;
    };
    auto lowerAscii = [](unsigned char c) -> unsigned char {
        return (c >= 'A' && c <= 'Z') ? static_cast<unsigned char>(c - 'A' + 'a') : c;
    };

    for (unsigned char c : query) {
        if (!isAscii(c)) return false;
    }

    const size_t lastStart = text.size() - query.size();
    for (size_t i = 0; i <= lastStart; ++i) {
        bool matched = true;
        for (size_t j = 0; j < query.size(); ++j) {
            const unsigned char textByte = static_cast<unsigned char>(text[i + j]);
            if (!isAscii(textByte) || lowerAscii(textByte) != lowerAscii(static_cast<unsigned char>(query[j]))) {
                matched = false;
                break;
            }
        }
        if (matched) {
            outStart = i;
            return true;
        }
    }
    return false;
}

static void DrawResultRowFilename(const std::string& displayName,
                                  const std::vector<std::pair<size_t, size_t>>& highlightSpans,
                                  const ImVec2& origin,
                                  float availW,
                                  float rowHeight,
                                  bool wrapFileName) {
    if (displayName.empty()) return;

    ImDrawList* drawList = ImGui::GetWindowDrawList();
    ImFont* font = ImGui::GetFont();
    const float fontSize = ImGui::GetFontSize();
    const ImU32 textColor = ImGui::GetColorU32(ImGuiCol_Text);
    const ImVec4 selectionColor = ThemeColors::current().resultsSelection;
    const ImU32 highlightBgColor = ImGui::GetColorU32(ImVec4(selectionColor.x, selectionColor.y, selectionColor.z, 0.38f));
    const float wrapW = wrapFileName
        ? ((availW > 12.0f) ? (availW - 6.0f) : availW)
        : 0.0f;
    const float lineHeight = ImGui::GetTextLineHeightWithSpacing();
    const float highlightPadX = 2.0f;
    const float highlightPadY = 1.0f;

    drawList->PushClipRect(origin, ImVec2(origin.x + availW, origin.y + rowHeight), true);

    if (highlightSpans.empty()) {
        if (wrapFileName) {
            drawList->AddText(font, fontSize, origin, textColor, displayName.c_str(), nullptr, wrapW);
        } else {
            drawList->AddText(font, fontSize, origin, textColor, displayName.c_str());
        }
        drawList->PopClipRect();
        return;
    }

    const char* textBegin = displayName.c_str();
    const char* textEnd = textBegin + displayName.size();
    const char* lineStart = textBegin;
    float y = origin.y;
    const float wrapLimit = wrapFileName ? wrapW : 1.0e8f;

    while (lineStart < textEnd) {
        const char* lineEnd = wrapFileName
            ? font->CalcWordWrapPosition(fontSize, lineStart, textEnd, wrapLimit)
            : textEnd;
        if (lineEnd == lineStart) {
            lineEnd = lineStart + 1;
        }

        const size_t lineByteStart = static_cast<size_t>(lineStart - textBegin);
        const size_t lineByteEnd = static_cast<size_t>(lineEnd - textBegin);
        float x = origin.x;
        size_t cursor = lineByteStart;
        for (const auto& span : highlightSpans) {
            const size_t spanStart = (std::max)(cursor, span.first);
            if (spanStart > lineByteEnd) break;

            const size_t plainEnd = (std::min)(lineByteEnd, span.first);
            if (plainEnd > cursor) {
                const char* segBegin = textBegin + cursor;
                const char* segEnd = textBegin + plainEnd;
                drawList->AddText(font, fontSize, ImVec2(x, y), textColor, segBegin, segEnd);
                x += ImGui::CalcTextSize(segBegin, segEnd).x;
                cursor = plainEnd;
            }

            const size_t hiEnd = (std::min)(lineByteEnd, span.second);
            if (hiEnd > spanStart) {
                const char* hiBegin = textBegin + spanStart;
                const char* hiTextEnd = textBegin + hiEnd;
                const ImVec2 hiSize = ImGui::CalcTextSize(hiBegin, hiTextEnd);
                drawList->AddRectFilled(
                    ImVec2(x - highlightPadX, y - highlightPadY),
                    ImVec2(x + hiSize.x + highlightPadX, y + fontSize + highlightPadY),
                    highlightBgColor,
                    3.0f);
                drawList->AddText(font, fontSize, ImVec2(x, y), textColor, hiBegin, hiTextEnd);
                x += hiSize.x;
                cursor = hiEnd;
            }
        }

        if (cursor < lineByteEnd) {
            const char* segBegin = textBegin + cursor;
            const char* segEnd = textBegin + lineByteEnd;
            drawList->AddText(font, fontSize, ImVec2(x, y), textColor, segBegin, segEnd);
        }

        if (!wrapFileName) break;
        y += lineHeight;
        lineStart = lineEnd;
        if (lineStart < textEnd && *lineStart == '\n') {
            ++lineStart;
            continue;
        }
        while (lineStart < textEnd && IsWrapBlank(*lineStart)) {
            ++lineStart;
        }
    }

    drawList->PopClipRect();
}

static const char* GetSearchMatchSourceLabel(SearchMatchSource source) {
    switch (source) {
    case SearchMatchSource::Name: return "Matched in: Name";
    case SearchMatchSource::Path: return "Matched in: Path";
    case SearchMatchSource::Description: return "Matched in: Description";
    case SearchMatchSource::Keywords: return "Matched in: Keywords";
    case SearchMatchSource::Metadata: return "Matched in: Metadata";
    case SearchMatchSource::FuzzyName: return "Matched by: Fuzzy name match";
    default: return nullptr;
    }
}

static const std::string* PickFallbackSearchField(const AudioRecord& record) {
    switch (record.matchSource) {
    case SearchMatchSource::Path:
        return !record.filePath.empty() ? &record.filePath : &record.folderPath;
    case SearchMatchSource::Description:
        return &record.description;
    case SearchMatchSource::Keywords:
        return &record.keywords;
    case SearchMatchSource::Metadata:
        if (!record.title.empty()) return &record.title;
        if (!record.artist.empty()) return &record.artist;
        if (!record.album.empty()) return &record.album;
        if (!record.category.empty()) return &record.category;
        return nullptr;
    case SearchMatchSource::Name:
    case SearchMatchSource::FuzzyName:
    case SearchMatchSource::None:
    default:
        if (!record.displayName.empty()) return &record.displayName;
        if (!record.fileName.empty()) return &record.fileName;
        if (!record.filePath.empty()) return &record.filePath;
        return nullptr;
    }
}

static std::string BuildFallbackSearchSnippet(const AudioRecord& record, const std::string& query) {
    const std::string* label = PickFallbackSearchField(record);
    if (!label || label->empty()) return {};

    auto collectTerms = [&](const std::string& rawQuery) {
        std::vector<std::string> terms;
        auto pushUnique = [&](const std::string& term) {
            const std::string trimmed = TrimCopy(term);
            if (trimmed.empty()) return;
            if (std::find(terms.begin(), terms.end(), trimmed) != terms.end()) return;
            terms.push_back(trimmed);
        };

        const std::string normalizedQuery = TrimCopy(rawQuery);
        pushUnique(normalizedQuery);
        for (const SearchQueryChip& chip : BuildSearchQueryChips(normalizedQuery)) {
            bool chipAllowed = false;
            switch (chip.kind) {
            case SearchQueryChipKind::ExcludeKeyword:
            case SearchQueryChipKind::ExcludeField:
                chipAllowed = false;
                break;
            case SearchQueryChipKind::Keyword:
                chipAllowed = true;
                break;
            case SearchQueryChipKind::Field:
                switch (record.matchSource) {
                case SearchMatchSource::Path:
                    chipAllowed = chip.field == "path";
                    break;
                case SearchMatchSource::Description:
                    chipAllowed = chip.field == "desc" || chip.field == "description";
                    break;
                case SearchMatchSource::Keywords:
                    chipAllowed = chip.field == "keywords";
                    break;
                case SearchMatchSource::Name:
                case SearchMatchSource::FuzzyName:
                    chipAllowed = chip.field == "name";
                    break;
                case SearchMatchSource::Metadata:
                    chipAllowed = chip.field == "artist" || chip.field == "album" ||
                                  chip.field == "title" || chip.field == "category" ||
                                  chip.field == "keywords" || chip.field == "tag" ||
                                  chip.field == "tags";
                    break;
                case SearchMatchSource::None:
                default:
                    chipAllowed = false;
                    break;
                }
                break;
            }
            if (chipAllowed) pushUnique(chip.label);
        }
        return terms;
    };

    size_t start = 0;
    size_t end = 0;
    bool matched = false;
    for (const std::string& term : collectTerms(query)) {
        const HarkenSearch::Search::PinyinSpan pinyinSpan = HarkenSearch::Search::FindPinyinSpanUtf8(*label, term);
        if (pinyinSpan.found && pinyinSpan.byteStart < pinyinSpan.byteEnd && pinyinSpan.byteEnd <= label->size()) {
            start = pinyinSpan.byteStart;
            end = pinyinSpan.byteEnd;
            matched = true;
            break;
        }
        if (FindAsciiCaseInsensitiveSpan(*label, term, start)) {
            end = start + term.size();
            matched = true;
            break;
        }
    }
    if (!matched) return {};

    std::string snippet;
    snippet.reserve(label->size() + 2);
    snippet.append(*label, 0, start);
    snippet.push_back((char)1);
    snippet.append(*label, start, end - start);
    snippet.push_back((char)2);
    snippet.append(*label, end, std::string::npos);
    return snippet;
}

static bool HasSearchExplainability(const AudioRecord& record, const std::string& query) {
    return GetSearchMatchSourceLabel(record.matchSource) != nullptr ||
           !record.matchSnippet.empty() ||
           !BuildFallbackSearchSnippet(record, query).empty();
}

// Local customization: suppress search-result hover popups in both the name
// and description columns. Search matching and inline highlights stay active.
static bool BeginSearchExplainabilityTooltip() {
    return false;
}

static bool HasBlockingSearchExplainabilityPopup() {
    if (!ImGui::IsPopupOpen("", ImGuiPopupFlags_AnyPopupId | ImGuiPopupFlags_AnyPopupLevel))
        return false;

    ImGuiContext& g = *GImGui;
    for (const ImGuiPopupData& popup : g.OpenPopupStack) {
        ImGuiWindow* window = popup.Window;
        if (!window || !window->Name)
            return true;
        if (std::strcmp(window->Name, "##SearchSuggestPopup") == 0)
            continue;
        return true;
    }
    return false;
}

static void LogSearchExplainabilityTooltipDiag(const AudioRecord& record,
                                               const std::string& query) {
    const char* sourceLabel = GetSearchMatchSourceLabel(record.matchSource);
    const bool hasSnippet = !record.matchSnippet.empty() ||
                            !BuildFallbackSearchSnippet(record, query).empty();
    DIAG_ACTION_FMT("Search",
                    "ExplainTooltip source=%s hasSnippet=%d guided=%d",
                    sourceLabel ? sourceLabel : "None",
                    hasSnippet ? 1 : 0,
                    g_showGuidedTooltips ? 1 : 0);
}

static void RenderSearchExplainability(const AudioRecord& record,
                                       const std::string& query,
                                       const ImVec4& highlightColor) {
    const char* sourceLabel = GetSearchMatchSourceLabel(record.matchSource);
    const std::string snippet = !record.matchSnippet.empty()
        ? record.matchSnippet
        : BuildFallbackSearchSnippet(record, query);
    if (sourceLabel) {
        ImGui::TextDisabled("%s", sourceLabel);
    }
    if (!snippet.empty()) {
        RenderInlineHighlightedText(snippet, highlightColor);
    } else if (sourceLabel) {
        ImGui::TextDisabled(L(Main_NoSnippetText));
    }
}

// Strip FTS highlight markers (char(1)/char(2)) so tooltip can show plain full text.
static std::string StripFtsMarkers(const std::string& s) {
    if (s.empty()) return s;
    std::string out;
    out.reserve(s.size());
    for (char c : s) {
        if (c == (char)1 || c == (char)2) continue;
        out.push_back(c);
    }
    return out;
}

    // Cover propagation is handled by the background cover pipeline.

static void PumpDeferredCoverImport(AppState& state) {
    if (!state.coverImportDeferredApply) return;
    if (state.coverImportImagePath.empty()) return;
    if (state.loadingMore) return; // wait until load-all completed
    if (state.viewMode == ViewMode::Browser) {
        state.coverImportDeferredApply = false;
        state.coverImportApplyMode = 0;
        state.coverImportImagePath.clear();
        return;
    }

    // Build targets from the fully loaded result set
    std::vector<std::string> targets;
    targets.reserve(state.searchResults.size());
    for (const auto& r : state.searchResults) {
        if (state.coverImportApplyMode == 1 && r.hasCover) continue; // only no cover
        if (state.coverImportApplyMode == 2 && !r.hasCover) continue; // only has cover
        targets.push_back(r.filePath);
    }

    // Import the image into the clipboard, then use the shared batch apply path.
    if (!targets.empty()) {
        std::vector<uint8_t> imageData;
        std::string mimeType;
        if (MetadataWriter::loadImageFile(state.coverImportImagePath, imageData, mimeType)) {
            state.coverClipboardData = std::move(imageData);
            state.coverClipboardMimeType = mimeType;
            StartCoverBatchPaste(state, targets);
        }
    }

    // Reset deferred state
    state.coverImportDeferredApply = false;
    state.coverImportApplyMode = 0;
    state.coverImportImagePath.clear();
}

