static void SyncBrowserPathBuffer(AppState& state) {
    std::snprintf(state.browserPathBuffer, sizeof(state.browserPathBuffer),
                  "%s", state.fileBrowser.getCurrentPath().c_str());
}

static void NavigateBrowserToFolder(AppState& state,
                                    const std::string& folderPath,
                                    BrowserScope scope) {
    if (folderPath.empty()) {
        return;
    }
    state.fileBrowser.navigateTo(folderPath);
    state.fileBrowser.setScope(scope);
    if (scope == BrowserScope::RecursiveAudio) {
        state.fileBrowser.buildRecursiveEntries();
    }
    state.fileBrowser.setSelectedIndex(-1);
    state.browserSelectedIndicesSet.clear();
    state.browserLastClickedIndex = -1;
    state.browserSortPath.clear();
    SyncBrowserPathBuffer(state);
}

static std::string ResolveBrowserEntryFolderPath(const FileEntry& entry) {
    if (entry.isDirectory) {
        return entry.fullPath;
    }
    try {
        return HarkenSearch::DisplayFolderFromFilePath(entry.fullPath);
    } catch (...) {
        return std::string();
    }
}

bool AddBrowserFolderToQuickPaths(AppState& state, const std::string& folderPath) {
    if (folderPath.empty()) {
        return false;
    }
    std::string folderName;
    try { folderName = BaseNameFromUtf8Path(folderPath); } catch (...) {}
    if (folderName.empty()) {
        folderName = folderPath;
    }
    if (!AddFolderShortcutIfMissing(state, folderName, folderPath, true)) {
        return false;
    }
    MarkSettingsDirty(state);
    return true;
}

void OpenFolderShortcut(AppState& state, const FolderShortcut& shortcut) {
    if (shortcut.openInBrowser) {
        state.viewMode = ViewMode::Browser;
        NavigateBrowserToFolder(state, shortcut.path, state.fileBrowser.getScope());
    } else {
        state.selectedFolderPath = HarkenSearch::CanonicalFolderPath(shortcut.path);
        state.folderFilterActive = true;
        state.viewMode = ViewMode::Database;
        state.preferDeferredCountForNextRefresh = true;
        RefreshSearchResults(state, true);
    }
    state.syncToTab();
}

