// RQ-20260817-01 other-differences-audit
// keyboard-selection-parity: Browser Up/Down walks filteredRows, skips directories, auditions the selected file.
// context-menu-parity: Browser audio rows reuse Edit_EditFilename, Ctx_DeleteFromFS,
// Edit_RevealInExplorer, and Ctx_CopyFilePath (Ctrl+Alt+C).
// selection-mode-parity: Existing Browser click/Ctrl/Shift selection is unchanged; directory rows stay folder actions.
// retained: directory rows are not keyboard-selected.
// Browser has no remove-from-database action because unindexed files are not in the database.
// follow-up not in this card (本卡不实现，需产品治理总管另开卡): batch rename/rating/color/metadata edit;
// desktop EXE QA.
static void BeginBrowserPathAudition(AppState& state,
                                     const FileEntry& entry,
                                     bool playWhenReady) {
    if (entry.isDirectory || entry.fullPath.empty()) {
        return;
    }
    state.audioEngine.loadFileAsync(entry.fullPath, playWhenReady);
    state.currentFileId = -1;
    ScheduleDeferredWaveformDetail(state, entry.fullPath, AppState::WAVEFORM_DEFAULT_DETAIL_PEAKS);
    ResetWaveformZoom(state);
}

static std::string BuildBrowserSelectedAudioPaths(AppState& state) {
    const auto& entries = state.fileBrowser.activeEntries();
    std::string allPaths;
    auto appendPath = [&](int idx) {
        if (idx < 0 || idx >= (int)entries.size()) {
            return;
        }
        const FileEntry& entry = entries[idx];
        if (entry.isDirectory || entry.fullPath.empty()) {
            return;
        }
        if (!allPaths.empty()) allPaths += "\n";
        allPaths += entry.fullPath;
    };
    if (!state.browserSelectedIndicesSet.empty()) {
        for (int idx : state.browserSelectedIndicesSet) {
            appendPath(idx);
        }
    } else {
        appendPath(state.fileBrowser.getSelectedIndex());
        if (allPaths.empty()) {
            appendPath(state.browserLastClickedIndex);
        }
    }
    return allPaths;
}

static void MoveBrowserAudioListSelectionByArrow(AppState& state,
                                                 const std::vector<FileEntry>& entries,
                                                 const std::vector<int>& filteredRows,
                                                 int direction) {
    if (filteredRows.empty() || direction == 0) {
        return;
    }

    int currentEntry = state.fileBrowser.getSelectedIndex();
    if (currentEntry < 0) {
        currentEntry = state.browserLastClickedIndex;
    }

    int currentVisible = -1;
    for (int i = 0; i < (int)filteredRows.size(); ++i) {
        if (filteredRows[i] == currentEntry) {
            currentVisible = i;
            break;
        }
    }

    int nextVisible = currentVisible;
    if (nextVisible < 0) {
        nextVisible = (direction > 0) ? -1 : (int)filteredRows.size();
    }
    nextVisible += direction;

    while (nextVisible >= 0 && nextVisible < (int)filteredRows.size()) {
        const int entryIndex = filteredRows[nextVisible];
        if (entryIndex < 0 || entryIndex >= (int)entries.size()) {
            nextVisible += direction;
            continue;
        }
        const FileEntry& entry = entries[entryIndex];
        if (entry.isDirectory) {
            nextVisible += direction;
            continue;
        }

        state.browserSelectedIndicesSet.clear();
        state.browserSelectedIndicesSet.insert(entryIndex);
        state.browserLastClickedIndex = entryIndex;
        state.fileBrowser.setSelectedIndex(entryIndex);
        state.browserLocateAnchorPath = entry.fullPath;
        BeginBrowserPathAudition(state, entry, state.settings.autoplayOnSelect);
        if (state.settings.autoplayOnSelect) {
            MarkFilePlayed(state, entry.fullPath, 0, false);
        }
        return;
    }
}

// Navigate file browser to the given audio file: switch to Browser view,
// navigate folder tree, select file, and begin playback.
static void OpenFileInFileBrowser(AppState& state, const std::string& filePath) {
    std::string parentDir;
    try {
        parentDir = PathToUtf8Main(Utf8ToPathMain(filePath).parent_path());
    } catch (...) {
        parentDir = filePath;
    }

    // Switch to file browser view.
    state.viewMode = ViewMode::Browser;

    // Navigate folder tree to parent directory and populate the file list.
    NavigateBrowserToFolder(state, parentDir, BrowserScope::CurrentDir);

    // Select the specific file in the list (may return -1 if not yet loaded).
    int idx = state.fileBrowser.selectByPath(filePath);
    state.browserSelectedIndicesSet.clear();
    state.browserLastClickedIndex = -1;
    state.browserSortPath.clear();
    if (idx >= 0) {
        state.browserSelectedIndicesSet.insert(idx);
        state.browserLastClickedIndex = idx;
    }

    // Flash the file entry and show source label.
    state.browserLocateAnchorPath = filePath;
    state.browserLocateSourceLabel = std::string(L(Cover_FromCmdLine)) +
        PathToUtf8Main(Utf8ToPathMain(filePath).filename());
    state.browserLocateSourceUntilMs = ImGui::GetTime() * 1000.0 + 5000.0;

    // Flash the folder in the folder tree sidebar.
    state.folderTreeHighlightPath = parentDir;
    state.folderTreeHighlightUntilMs =
        static_cast<int64_t>(Platform::MonotonicMilliseconds()) + 2000;

    state.syncToTab();

    // Begin playback immediately.
    FileEntry openedFile;
    openedFile.isDirectory = false;
    openedFile.fullPath = filePath;
    BeginBrowserPathAudition(state, openedFile, true);

    AppendDiagLogF(L"OpenFileInFileBrowser: %hs", filePath.c_str());
}

