class AppCoverBatchOperationPort final
    : public aura::cover_batch::CoverBatchPersistencePort,
      public aura::cover_batch::CoverBatchViewPort,
      public aura::cover_batch::CoverBatchStatePort {
public:
    explicit AppCoverBatchOperationPort(AppState& state) : state_(state) {}

    bool hasCoverThumb(const std::string& key) override {
        return state_.database.hasCoverThumb(key);
    }
    void saveCoverThumb(const std::string& key,
                        const std::vector<std::uint8_t>& data,
                        const std::string& mime) override {
        state_.database.saveCoverThumb(key, data, mime);
    }
    void assignEmbeddedCoverByPaths(const std::vector<std::string>& paths,
                                    const std::string& key,
                                    std::int64_t timestamp) override {
        state_.database.assignEmbeddedCoverByPaths(paths, key, timestamp);
    }
    void clearCoverByPaths(const std::vector<std::string>& paths) override {
        state_.database.clearCoverByPaths(paths);
    }
    std::int64_t currentUnixTime() override {
        return static_cast<std::int64_t>(std::time(nullptr));
    }

    void applyVisibleRows(const std::vector<std::string>& paths,
                          bool paste,
                          const std::string& key) override {
        const std::unordered_set<std::string> targetSet(paths.begin(), paths.end());
        for (auto& record : state_.searchResults) {
            if (!targetSet.count(record.filePath)) continue;
            record.hasCover = paste;
            record.embeddedCoverKey = paste ? key : std::string();
            record.folderCoverKey.clear();
            record.coverSuppressed = !paste;
        }
    }
    void invalidateFileCoverCaches(
        const std::vector<std::string>& paths) override {
        CoverModule::InvalidateFileCoverCaches(paths);
    }
    void clearFolderCoverNegativeCache() override {
        CoverModule::ClearFolderCoverNegativeCache();
    }
    void requestCoverWallRefresh() override {
        aura::cover_wall::RequestDatabaseInvalidation(state_);
    }
    void syncToTab() override { state_.syncToTab(); }

    void finishBatch(int total) override {
        state_.coverBatchProgress = total;
        state_.coverBatchActive = false;
        state_.coverBatchTargets.clear();
        state_.coverBatchSucceeded.clear();
    }

private:
    AppState& state_;
};

