// Explicit physical embedding for workflows that require file mutation.
static void StartEmbedMetadataBatch(AppState& state, const std::vector<AudioRecord>& targets) {
    if (targets.empty()) return;
    state.embedBatchActive = true;
    state.embedBatchTargets = targets;
    state.embedBatchTotal = (int)targets.size();
    state.embedBatchProgress = 0;
}

static void ClearPendingOriginalAudioWrite(AppState& state) {
    const bool clearImport =
        state.pendingOriginalAudioWriteKind ==
        AppState::OriginalAudioWritePendingKind::ImportCover;
    state.pendingOriginalAudioWriteKind = AppState::OriginalAudioWritePendingKind::None;
    state.pendingOriginalAudioWriteRecords.clear();
    state.pendingOriginalAudioWritePaths.clear();
    state.pendingOriginalAudioWriteImageData.clear();
    state.pendingOriginalAudioWriteMimeType.clear();
    state.showOriginalAudioWriteConfirm = false;
    if (clearImport) {
        state.coverImportIds.clear();
        state.coverImportPaths.clear();
    }
}

static void ApplyPendingOriginalAudioWriteUnlocked(AppState& state) {
    using Kind = AppState::OriginalAudioWritePendingKind;
    if (state.pendingOriginalAudioWriteKind == Kind::EmbedBatch) {
        StartEmbedMetadataBatch(state, state.pendingOriginalAudioWriteRecords);
    } else if (state.pendingOriginalAudioWriteKind == Kind::ImportCover) {
        std::vector<std::string> succeeded;
        succeeded.reserve(state.pendingOriginalAudioWritePaths.size());
        for (const auto& path : state.pendingOriginalAudioWritePaths) {
            if (Platform::FileSystem::IsNetworkPath(path)) {
                state.loadErrorToast = L(Write_BlockedNetworkLibrary);
                state.loadErrorToastUntil = ImGui::GetTime() + 5.0;
                continue;
            }
            if (MetadataWriter::writeAlbumArt(
                    path,
                    state.pendingOriginalAudioWriteImageData,
                    state.pendingOriginalAudioWriteMimeType)) {
                succeeded.push_back(path);
            }
        }
        if (!succeeded.empty()) {
            for (auto& record : state.searchResults) {
                for (const auto& path : succeeded) {
                    if (record.filePath == path) {
                        record.hasCover = true;
                        record.embeddedCoverKey.clear();
                        record.folderCoverKey.clear();
                        record.coverSuppressed = false;
                        break;
                    }
                }
            }
            state.database.assignEmbeddedCoverByPaths(succeeded, "", 0);
        }
        CoverModule::InvalidateFileCoverCaches(succeeded);
    }
    ClearPendingOriginalAudioWrite(state);
}

static void ApplyPendingOriginalAudioWrite(AppState& state) {
    using aura::metadata::EvaluateOriginalAudioWriteConfirm;
    using aura::metadata::OriginalAudioWriteConfirmRequest;
    using aura::metadata::TryInvokeOriginalAudioWrite;
    const OriginalAudioWriteConfirmRequest request{
        state.settings.suppressConfirmDialogs, true, false};
    (void)EvaluateOriginalAudioWriteConfirm(request);
    TryInvokeOriginalAudioWrite(request, [&state]() {
        ApplyPendingOriginalAudioWriteUnlocked(state);
    });
}

static void RequestOriginalAudioWriteConfirm(AppState& state) {
    using aura::metadata::EvaluateOriginalAudioWriteConfirm;
    using aura::metadata::OriginalAudioWriteConfirmRequest;
    using aura::metadata::ShouldWriteOriginalAudio;
    using aura::metadata::TryInvokeOriginalAudioWrite;
    const OriginalAudioWriteConfirmRequest request{
        state.settings.suppressConfirmDialogs, false, false};
    const auto decision = EvaluateOriginalAudioWriteConfirm(request);
    if (ShouldWriteOriginalAudio(decision)) {
        TryInvokeOriginalAudioWrite(request, [&state]() {
            ApplyPendingOriginalAudioWriteUnlocked(state);
        });
        return;
    }
    state.showOriginalAudioWriteConfirm = true;
}

class AppEmbedMetadataBatchPorts final
    : public aura::metadata::EmbedMetadataBatchStatePort,
      public aura::metadata::EmbedMetadataTaskPort {
public:
    explicit AppEmbedMetadataBatchPorts(AppState& state) : state_(state) {}

    bool active() const override { return state_.embedBatchActive; }
    int progress() const override { return state_.embedBatchProgress; }
    int total() const override { return state_.embedBatchTotal; }

    aura::metadata::EmbedMetadataTask currentTask() const override {
        const AudioRecord& record =
            state_.embedBatchTargets[state_.embedBatchProgress];
        return {
            record.filePath,
            record.embeddedCoverKey.empty() ? record.folderCoverKey
                                            : record.embeddedCoverKey,
            record.folderCoverSrcPath,
        };
    }

    void advance() override { ++state_.embedBatchProgress; }

    void finish() override {
        state_.embedBatchActive = false;
        state_.embedBatchTargets.clear();
    }

    std::future<bool> launch(aura::metadata::EmbedMetadataTask task) override {
        if (Platform::FileSystem::IsNetworkPath(task.path)) {
            state_.loadErrorToast = L(Write_BlockedNetworkLibrary);
            state_.loadErrorToastUntil = ImGui::GetTime() + 5.0;
            std::promise<bool> ready;
            ready.set_value(false);
            return ready.get_future();
        }
        return std::async(
            std::launch::async,
            [path = std::move(task.path),
             targetKey = std::move(task.targetKey),
             folderSrcPath = std::move(task.folderSourcePath),
             db = &state_.database]() -> bool {
            std::vector<uint8_t> coverData;
            std::string mimeType;

            // 1) 优先按 key 读取持久化 thumb
            if (!targetKey.empty()) {
                db->getCoverThumb(targetKey, coverData, mimeType);
            }

            // 2) thumb miss，再按数据库缓存的真实 src_path 读物理图
            if (coverData.empty() && !folderSrcPath.empty()) {
                MetadataWriter::loadImageFile(folderSrcPath, coverData, mimeType);
            }


            // 3) 有图则写入，没有则移除
            if (!coverData.empty()) {
                return MetadataWriter::writeAlbumArt(path, coverData, mimeType);
            } else {
                return MetadataWriter::removeAlbumArt(path);
            }
            });
    }

private:
    AppState& state_;
};

static void PumpEmbedMetadataBatch(AppState& state) {
    static aura::metadata::EmbedMetadataBatchRuntime runtime;
    AppEmbedMetadataBatchPorts ports(state);
    runtime.pump(ports, ports);
}

// 重建当前数据库所有封面（流式分批处理，支持百万级文件）
static const int COVER_REBUILD_BATCH_SIZE = 5000;   // 每批从 DB 读 5000 条
static const int COVER_REBUILD_PER_FRAME = 2000;   // 每帧处理 2000 条（文件夹级去重后几乎纯内存操作）

void StartCoverRebuild(AppState& state) {
    if (state.coverRebuildActive) return;

    // 只获取总数，不加载数据
    state.coverRebuildTotal = state.database.getFileCount();
    state.coverRebuildProgress = 0;
    state.coverRebuildFound = 0;
    state.coverRebuildCancel = false;
    state.coverRebuildOffset = 0;
    state.coverRebuildBatch.clear();
    state.coverRebuildBatchIdx = 0;
    state.coverRebuildFolderCache.clear();
    state.coverRebuildActive = true;

    // 不再清空封面缓存——改为渐进式覆盖，中途取消也不会导致全库无封面
    // CoverModule::ClearAllCoverCaches();  // 移除：这是取消后极卡的根因
}

class AppCoverRebuildFolderLookupPort final
    : public aura::cover_rebuild::CoverRebuildFolderLookupPort {
public:
    AppCoverRebuildFolderLookupPort(AppState& state, int& diskIoThisFrame)
        : state_(state), diskIoThisFrame_(diskIoThisFrame) {}

    aura::cover_rebuild::FolderCoverResolution resolve(
        const std::string& folderPath) override {
        auto it = state_.coverRebuildFolderCache.find(folderPath);
        if (it != state_.coverRebuildFolderCache.end()) {
            return {it->second, {}, 0, false};
        }
        if (diskIoThisFrame_ >= 20) return {{}, {}, 0, true};
        ++diskIoThisFrame_;

        std::string fastKey;
        std::string fastPath;
        std::string folderKey;
        std::string folderSrcPath;
        if (CoverModule::TryGetFolderCoverKeyFast(folderPath, fastKey, &fastPath) &&
            !fastKey.empty() && !fastPath.empty()) {
            folderKey = CoverModule::NormalizeCoverKeyByVisualIdentity(fastPath);
            folderSrcPath = fastPath;
        } else if (!folderPath.empty()) {
            std::string coverPath;
            if (CoverModule::GetFolderCoverImagePath(folderPath, coverPath, true) &&
                !coverPath.empty()) {
                folderKey = CoverModule::NormalizeCoverKeyByVisualIdentity(coverPath);
                folderSrcPath = coverPath;
            }
        }
        state_.coverRebuildFolderCache[folderPath] = folderKey;

        std::int64_t mtime = 0;
        if (!folderSrcPath.empty()) {
            mtime = PathMtimeUnixSecondsMain(Utf8ToPathMain(folderSrcPath));
        }
        return {folderKey, folderSrcPath, mtime, false};
    }

private:
    AppState& state_;
    int& diskIoThisFrame_;
};

