class AppCoverRebuildBatchPersistencePort final
    : public aura::cover_rebuild::CoverRebuildBatchPersistencePort {
public:
    explicit AppCoverRebuildBatchPersistencePort(AppState& state)
        : state_(state) {}
    void setHasCover(const std::vector<std::string>& paths) override {
        state_.database.updateHasCoverByPathsBatch(paths, true);
    }
    void clearHasCover(const std::vector<std::string>& paths) override {
        state_.database.updateHasCoverByPathsBatch(paths, false);
    }
    void updateCoverKeyCache(
        const std::vector<aura::cover_rebuild::CoverRebuildBatchCacheUpdate>& updates) override {
        std::vector<CoverKeyCacheUpdate> dbUpdates;
        dbUpdates.reserve(updates.size());
        for (const auto& update : updates) {
            CoverKeyCacheUpdate dbUpdate;
            dbUpdate.filePath = update.filePath;
            dbUpdate.updateFolder = true;
            dbUpdate.folderCoverKey = update.folderCoverKey;
            dbUpdate.folderCoverSrcPath = update.folderCoverSrcPath;
            dbUpdate.folderCoverSrcMtime = update.folderCoverSrcMtime;
            dbUpdates.push_back(std::move(dbUpdate));
        }
        state_.database.updateCoverKeyCacheBatch(dbUpdates);
    }

private:
    AppState& state_;
};

static void PumpCoverRebuild(AppState& state) {
    if (!state.coverRebuildActive) return;
    AppCoverRebuildLifecyclePorts lifecyclePorts(state);
    if (aura::cover_rebuild::ResolveCoverRebuildLifecycle(
            {state.coverRebuildCancel, false, false}, lifecyclePorts,
            lifecyclePorts)) return;
    // 如果当前批次处理完了，加载下一批
    if (state.coverRebuildBatchIdx >= (int)state.coverRebuildBatch.size()) {
        state.coverRebuildBatch = state.database.getAllFiles(COVER_REBUILD_BATCH_SIZE, state.coverRebuildOffset);
        state.coverRebuildBatchIdx = 0;
        if (state.coverRebuildBatch.empty()) {
            if (aura::cover_rebuild::ResolveCoverRebuildLifecycle(
                    {false, true, state.database.isCoverRegistryStale()},
                    lifecyclePorts, lifecyclePorts)) return;
        }
    }

    // 每帧处理若干条 — 文件夹级去重让大部分查询命中缓存
    // Fix #6: static + clear() 复用，避免每帧 2000 次 string 构造/析构的堆抖动
    static std::vector<CoverKeyCacheUpdate> dbUpdates;
    static std::vector<std::string> setHasCover;
    static std::vector<std::string> clearHasCover;
    dbUpdates.clear();
    setHasCover.clear();
    clearHasCover.clear();

    // 限制每帧磁盘 I/O 次数（缓存未命中的文件夹需要真正的磁盘读取）
    // 缓存命中后是纯内存操作，不受此限制，因此 2000/frame 的吞吐量仍可保持
    int diskIoThisFrame = 0;
    constexpr int kMaxDiskIoPerFrame = 20;

    for (int n = 0; n < COVER_REBUILD_PER_FRAME && state.coverRebuildBatchIdx < (int)state.coverRebuildBatch.size(); n++) {
        const auto& record = state.coverRebuildBatch[state.coverRebuildBatchIdx];
        state.coverRebuildBatchIdx++;
        state.coverRebuildOffset++;
        state.coverRebuildProgress++;

// Fix #1: 先检查嵌入封面（embedded cover），再查文件夹封面
        AppCoverRebuildFolderLookupPort lookup(state, diskIoThisFrame);
        const auto result = aura::cover_rebuild::ProcessCoverRebuildRecord(
            {record.filePath, record.folderPath, record.embeddedCoverKey,
             record.hasCover},
            lookup);
        if (result.budgetExhausted) break;
        state.coverRebuildFound += result.foundDelta;
        if (result.setHasCover) {
            setHasCover.push_back(record.filePath);
        } else if (result.clearHasCover) {
            clearHasCover.push_back(record.filePath);
        }
        if (result.folderUpdate.has_value()) {
            CoverKeyCacheUpdate upd;
            upd.filePath = result.folderUpdate->filePath;
            upd.updateFolder = true;
            upd.folderCoverKey = result.folderUpdate->folderCoverKey;
            upd.folderCoverSrcPath = result.folderUpdate->folderCoverSrcPath;
            upd.folderCoverSrcMtime = result.folderUpdate->folderCoverSrcMtime;
            dbUpdates.push_back(std::move(upd));
        }
    }

    AppCoverRebuildBatchPersistencePort persistence(state);
    std::vector<aura::cover_rebuild::CoverRebuildBatchCacheUpdate> cacheUpdates;
    cacheUpdates.reserve(dbUpdates.size());
    for (const auto& update : dbUpdates) {
        cacheUpdates.push_back({update.filePath, update.folderCoverKey,
                                update.folderCoverSrcPath,
                                update.folderCoverSrcMtime});
    }
    aura::cover_rebuild::CommitCoverRebuildBatch(
        {std::move(setHasCover), std::move(clearHasCover),
         std::move(cacheUpdates)},
        persistence);
}

// --- Rebuild all waveform caches (streaming batch, avoids kMaxPendingWaveforms truncation) ---
static const int WAVEFORM_REBUILD_BATCH_SIZE = 500;
static const int WAVEFORM_REBUILD_PER_FRAME  = 4;
static const size_t WAVEFORM_REBUILD_QUEUE_THRESHOLD = 16;
static aura::waveform_rebuild::SelectedWaveformRebuildWorkflow
    g_selectedWaveformRebuildWorkflow;

static void RestartWaveformWorkerForForegroundRebuild(AppState& state) {
    state.waveformWorker.stop();
    if (state.database.isOpen()) {
        state.waveformWorker.start(&state.database, 1);
    }
}

static bool StartWaveformRebuild(AppState& state,
                                 bool fullRebuild,
                                 int64_t totalOverride = -1,
                                 int64_t miniTotalOverride = -1,
                                 int64_t detailTotalOverride = -1) {
    if (state.waveformRebuildActive) return false;
    if (state.dbSwitchInProgress) return false;
    g_selectedWaveformRebuildWorkflow.clear();
    const int rebuildThreads = 1;
    const int64_t rebuildTotal = totalOverride >= 0
        ? totalOverride
        : (fullRebuild
            ? state.database.countAllFilesForWaveformRebuild()
            : state.database.countFilesNeedingAnyWaveformCache());
    const int64_t miniTotal = miniTotalOverride >= 0
        ? miniTotalOverride
        : (fullRebuild
            ? rebuildTotal
            : state.database.countFilesNeedingWaveformCache());
    const int64_t detailTotal = detailTotalOverride >= 0
        ? detailTotalOverride
        : (fullRebuild
            ? state.database.countFilesEligibleForPersistentDetailCache()
            : state.database.countFilesNeedingDetailCache());
    const bool libraryMiniOnly =
        state.database.getWaveformCacheMode() == WaveformCachePolicy::Mode::MiniOnly;
    if (!fullRebuild && rebuildTotal <= 0) {
        return false;
    }
    g_waveformRebuildRuntimeState.Reset(state, false);
    RestartWaveformWorkerForForegroundRebuild(state);
    state.waveformWorker.ensureThreadCount(rebuildThreads);
    state.waveformRebuildFullMode = fullRebuild;
    state.waveformRebuildMiniOnlyMode = false;
    state.waveformRebuildTotal = rebuildTotal;
    state.waveformRebuildMiniTotal = miniTotal;
    state.waveformRebuildDetailTotal = detailTotal;
    state.waveformRebuildActive   = true;
    DIAG_SYSTEM_FMT("Database",
        "Waveform rebuild state initialized: mode=%s policy=%s total=%lld mini=%lld detail=%lld db=%s",
        fullRebuild ? "full" : "incremental",
        libraryMiniOnly ? "mini_only" : "mini_and_main",
        (long long)state.waveformRebuildTotal,
        (long long)state.waveformRebuildMiniTotal,
        (long long)state.waveformRebuildDetailTotal,
        state.currentDbPathUtf8.c_str());
    return true;
}

static void StartIncrementalWaveformRebuild(AppState& state) {
    if (state.waveformRebuildActive) return;
    if (state.dbSwitchInProgress) {
        DIAG_SYSTEM_FMT("Database",
        "Waveform mini-only rebuild skipped: DB switch in progress for DB: %s",
            state.currentDbPathUtf8.c_str());
        return;
    }
    const int64_t rebuildTotal = state.database.countFilesNeedingWaveformCache();
    const int64_t miniTotal = rebuildTotal;
    const int64_t detailTotal = 0;
    if (rebuildTotal <= 0) {
        state.loadErrorToast = L(Wf_NoCacheToRebuild);
        state.loadErrorToastUntil = ImGui::GetTime() + 5.0;
        DIAG_SYSTEM_FMT("Database",
            "Waveform mini-only rebuild skipped: no missing mini cache debt for DB: %s",
            state.currentDbPathUtf8.c_str());
        return;
    }
    state.clearPendingWaveforms();
    state.waveformWorker.cancelAllPending();
    DIAG_SYSTEM_FMT("Database",
        "Waveform mini-only rebuild started: total=%lld mini=%lld detail=%lld db=%s",
        (long long)rebuildTotal,
        (long long)miniTotal,
        (long long)detailTotal,
        state.currentDbPathUtf8.c_str());
    if (StartWaveformRebuild(state, false, rebuildTotal, miniTotal, detailTotal)) {
        state.waveformRebuildMiniOnlyMode = true;
        g_waveformRebuildRuntimeState.setIncrementalMiniOnly(true);
    }
}

static bool DetectHarkenSearchUserInteractionForIdleAssetBackfill() {
    const ImGuiIO& io = ImGui::GetIO();
    const bool mouseMoved =
        io.MouseDelta.x != 0.0f || io.MouseDelta.y != 0.0f;
    const bool mouseWheel =
        io.MouseWheel != 0.0f || io.MouseWheelH != 0.0f;
    const bool mouseClickOrDrag =
        ImGui::IsAnyMouseDown() ||
        ImGui::IsMouseClicked(ImGuiMouseButton_Left) ||
        ImGui::IsMouseClicked(ImGuiMouseButton_Right) ||
        ImGui::IsMouseClicked(ImGuiMouseButton_Middle);

    bool keyboardActivity = io.InputQueueCharacters.Size > 0;
    if (io.WantCaptureKeyboard) {
        for (int key = ImGuiKey_NamedKey_BEGIN;
             key < ImGuiKey_NamedKey_END && !keyboardActivity;
             ++key) {
            keyboardActivity = ImGui::IsKeyDown(static_cast<ImGuiKey>(key));
        }
    }
    return mouseMoved || mouseWheel || mouseClickOrDrag || keyboardActivity;
}

static constexpr auto kIdleAssetBackfillCheckInterval = std::chrono::seconds(60);
static constexpr auto kIdleAssetBackfillProgressPollInterval = std::chrono::seconds(2);

static void ScheduleNextIdleAssetBackfillCheck(
    AppState& state,
    std::chrono::steady_clock::time_point now) {
    state.idleAssetBackfillNextCheckAt = now + kIdleAssetBackfillCheckInterval;
}

static void ScheduleNextIdleAssetBackfillProgressPoll(
    AppState& state,
    std::chrono::steady_clock::time_point now) {
    state.idleAssetBackfillNextProgressPollAt =
        now + kIdleAssetBackfillProgressPollInterval;
}

static const char* DescribeIdleAssetBackfillBlocker(const AppState& state) {
    if (!state.database.isOpen()) return "db_closed";
    if (state.dbSwitchInProgress) return "db_switch";
    if (state.audioEngine.isPlaying()) return "playback";
    if (state.isScanning.load(std::memory_order_acquire)) return "scan_running";
    if (state.database.isReconcileScanRunning()) return "reconcile_running";
    if (state.waveformRebuildActive && !state.idleAssetBackfillActive) {
        return "waveform_rebuild";
    }
    if (!state.idleAssetBackfillActive) {
        const auto snapshot = state.backfillQueue.snapshot();
        int queuedBackfillJobs = 0;
        for (int count : snapshot.byKind) queuedBackfillJobs += count;
        if (ShouldBlockIdleBackfillPoolTakeover(
                aura::GlobalBackfillWorkerPool().running(),
                snapshot.inFlight,
                queuedBackfillJobs)) {
            return "backfill_busy";
        }
    }
    return nullptr;
}

static int64_t CountIdleAssetCoverAndMetadataPending(AppState& state) {
    const int coverKind = static_cast<int>(aura::BackfillJobKind::CoverResolveAndThumb);
    const int metadataKind = static_cast<int>(aura::BackfillJobKind::MetadataRefresh);
    return (int64_t)state.database.countBackfillPendingKind(coverKind) +
           (int64_t)state.database.countBackfillPendingKind(metadataKind);
}

static int64_t RefreshIdleAssetBackfillProgress(AppState& state) {
    const int64_t miniDone = (std::max)(
        state.idleAssetBackfillCompletedMini,
        state.waveformRebuildProgress - state.idleAssetBackfillStartedMiniProgress);
    state.idleAssetBackfillCompletedMini = (std::max)(int64_t{0}, miniDone);
    const int64_t pendingCover = state.database.isOpen()
        ? CountIdleAssetCoverAndMetadataPending(state)
        : state.idleAssetBackfillStartedCoverPending;
    state.idleAssetBackfillCompletedCover = (std::max)(
        state.idleAssetBackfillCompletedCover,
        state.idleAssetBackfillStartedCoverPending - pendingCover);
    return pendingCover;
}

static bool StartIdleAssetBackfill(AppState& state) {
    if (state.idleAssetBackfillActive ||
        DescribeIdleAssetBackfillBlocker(state) != nullptr) {
        return false;
    }

    state.backfillQueue.refillFromDatabaseIfBelowWaterMark(&state.database, 128, 4096);
    const int64_t miniPending = state.database.countFilesNeedingWaveformCache();
    const int64_t coverAndMetadataPending = CountIdleAssetCoverAndMetadataPending(state);
    if (miniPending <= 0 && coverAndMetadataPending <= 0) {
        state.lastInputTime = std::chrono::steady_clock::now();
        return false;
    }

    state.idleAssetBackfillDbPath = state.currentDbPathUtf8;
    state.idleAssetBackfillStartedMiniProgress = 0;
    state.idleAssetBackfillStartedMiniTotal = miniPending;
    state.idleAssetBackfillStartedCoverPending = coverAndMetadataPending;
    state.idleAssetBackfillCompletedMini = 0;
    state.idleAssetBackfillCompletedCover = 0;
    state.idleAssetBackfillOwnsBackfillPool = false;

    if (miniPending > 0) {
        StartIncrementalWaveformRebuild(state);
        state.idleAssetBackfillStartedMiniProgress = state.waveformRebuildProgress;
    }
    if (coverAndMetadataPending > 0) {
        state.backfillQueue.refillFromDatabaseIfBelowWaterMark(&state.database, 128, 4096);
        aura::GlobalBackfillWorkerPool().start(
            state.backfillQueue.currentDbPath(),
            state.backfillQueue.currentGeneration(),
            &state.backfillQueue,
            1);
        state.idleAssetBackfillOwnsBackfillPool = true;
    }

    state.idleAssetBackfillActive =
        state.waveformRebuildActive || coverAndMetadataPending > 0;
    state.idleAssetBackfillNextProgressPollAt =
        std::chrono::steady_clock::time_point{};
    DIAG_SYSTEM_FMT("Backfill",
                    "IdleAssetBackfillStart: db=%s mini=%lld coverMetadata=%lld",
                    state.idleAssetBackfillDbPath.c_str(),
                    (long long)miniPending,
                    (long long)coverAndMetadataPending);
    return state.idleAssetBackfillActive;
}

static void StopIdleAssetBackfill(AppState& state, bool completed, bool interrupted) {
    if (!state.idleAssetBackfillActive && !completed) return;

    (void)RefreshIdleAssetBackfillProgress(state);

    if (!completed && state.waveformRebuildActive) {
        state.waveformRebuildCancel = true;
    }
    if (state.idleAssetBackfillOwnsBackfillPool) {
        aura::GlobalBackfillWorkerPool().stop();
        state.idleAssetBackfillOwnsBackfillPool = false;
    }
    state.idleAssetBackfillActive = false;
    state.idleAssetBackfillNextProgressPollAt =
        std::chrono::steady_clock::time_point{};
    ScheduleNextIdleAssetBackfillCheck(state, std::chrono::steady_clock::now());
    state.lastInputTime = std::chrono::steady_clock::now();
    DIAG_SYSTEM_FMT("Backfill",
                    "IdleAssetBackfillStop: completed=%d interrupted=%d mini=%lld coverMetadata=%lld db=%s",
                    completed ? 1 : 0,
                    interrupted ? 1 : 0,
                    (long long)state.idleAssetBackfillCompletedMini,
                    (long long)state.idleAssetBackfillCompletedCover,
                    state.idleAssetBackfillDbPath.c_str());
}

static void PumpIdleAssetBackfill(AppState& state, bool userInteraction) {
    const auto now = std::chrono::steady_clock::now();
    if (state.lastInputTime.time_since_epoch().count() == 0) {
        state.lastInputTime = now;
    }
    if (state.idleAssetBackfillNextCheckAt.time_since_epoch().count() == 0) {
        ScheduleNextIdleAssetBackfillCheck(state, now);
    }
    if (userInteraction) {
        state.lastInputTime = now;
        ScheduleNextIdleAssetBackfillCheck(state, now);
        if (state.idleAssetBackfillActive) {
            StopIdleAssetBackfill(state, false, true);
        }
        return;
    }

    if (!state.settings.idleAssetBackfillEnabled) {
        if (state.idleAssetBackfillActive) {
            StopIdleAssetBackfill(state, false, false);
        }
        state.idleAssetBackfillNextCheckAt =
            std::chrono::steady_clock::time_point{};
        state.idleAssetBackfillNextProgressPollAt =
            std::chrono::steady_clock::time_point{};
        return;
    }

    if (state.idleAssetBackfillActive) {
        if (state.idleAssetBackfillDbPath != state.currentDbPathUtf8 ||
            DescribeIdleAssetBackfillBlocker(state) != nullptr) {
            StopIdleAssetBackfill(state, false, true);
            return;
        }

        if (state.idleAssetBackfillNextProgressPollAt.time_since_epoch().count() == 0) {
            ScheduleNextIdleAssetBackfillProgressPoll(state, now);
        }
        if (now < state.idleAssetBackfillNextProgressPollAt) return;
        ScheduleNextIdleAssetBackfillProgressPoll(state, now);
        const int64_t coverPending = RefreshIdleAssetBackfillProgress(state);
        const auto snapshot = state.backfillQueue.snapshot();
        if (!state.waveformRebuildActive && coverPending <= 0 && snapshot.inFlight <= 0) {
            StopIdleAssetBackfill(state, true, false);
        }
        return;
    }

    if (!state.database.isOpen()) {
        ScheduleNextIdleAssetBackfillCheck(state, now);
        return;
    }
    if (!IsIdleAssetBackfillCheckDue(now, state.idleAssetBackfillNextCheckAt)) return;
    ScheduleNextIdleAssetBackfillCheck(state, now);
    if (!HasIdleAssetBackfillDelayElapsed(
            now,
            state.lastInputTime,
            state.settings.idleAssetBackfillDelayMinutes)) {
        return;
    }
    if (const char* blocker = DescribeIdleAssetBackfillBlocker(state)) {
        DIAG_SYSTEM_FMT("Backfill",
                        "IdleAssetBackfillCheck: skipped reason=%s db=%s",
                        blocker,
                        state.currentDbPathUtf8.c_str());
        return;
    }
    StartIdleAssetBackfill(state);
}

static void PollBackgroundReconcileScanToast(AppState& state) {
    const bool running = state.database.isOpen() &&
        state.database.isReconcileScanRunning();
    if (running) {
        state.backgroundReconcileScanToastActive = true;
        state.backgroundReconcileScanToast = u8"后台重扫中 · 正在核对库根目录";
        state.backgroundReconcileScanToastUntil = 0.0;
    } else if (state.backgroundReconcileScanToastActive) {
        state.backgroundReconcileScanToastActive = false;
        state.backgroundReconcileScanToast = u8"后台重扫完成";
        state.backgroundReconcileScanToastUntil = ImGui::GetTime() + 5.0;
    }
}

static void DrawForegroundMaintenanceToastCard(const std::string& text,
                                               float bottomOffset,
                                               ImU32 accentColor) {
    if (text.empty()) return;
    ImGuiViewport* vp = ImGui::GetMainViewport();
    if (!vp) return;
    ImDrawList* drawList = ImGui::GetForegroundDrawList(vp);
    if (!drawList) return;

    constexpr float kWidth = 380.0f;
    constexpr float kHeight = 58.0f;
    const ImVec2 max(vp->WorkPos.x + vp->WorkSize.x - 16.0f,
                     vp->WorkPos.y + vp->WorkSize.y - bottomOffset);
    const ImVec2 min(max.x - kWidth, max.y - kHeight);
    drawList->AddRectFilled(min, max, IM_COL32(24, 28, 36, 238), 8.0f);
    drawList->AddRect(min, max, IM_COL32(110, 125, 150, 170), 8.0f, 0, 1.0f);
    drawList->AddRectFilled(min, ImVec2(min.x + 4.0f, max.y), accentColor, 8.0f);
    drawList->AddText(ImGui::GetFont(), ImGui::GetFontSize(),
                      ImVec2(min.x + 14.0f, min.y + 10.0f),
                      IM_COL32(235, 239, 246, 255),
                      text.c_str(), nullptr, kWidth - 26.0f);
}

static void DrawBackgroundReconcileScanToast(AppState& state) {
    const bool visible = state.backgroundReconcileScanToastActive ||
        state.backgroundReconcileScanToastUntil > ImGui::GetTime();
    DrawForegroundMaintenanceToastCard(
        visible ? state.backgroundReconcileScanToast : std::string(),
        82.0f,
        IM_COL32(92, 205, 145, 255));
}

static void RenderForegroundMaintenanceToasts(AppState& state) {
    DrawBackgroundReconcileScanToast(state);
}

static bool StartFullWaveformRebuild(AppState& state) {
    if (state.waveformRebuildActive) return false;
    if (state.dbSwitchInProgress) {
        DIAG_SYSTEM_FMT("Database",
            "Waveform full rebuild skipped: DB switch in progress for DB: %s",
            state.currentDbPathUtf8.c_str());
        return false;
    }
    DIAG_SYSTEM_FMT("Database",
        "Waveform full rebuild scheduled for DB: %s",
    state.currentDbPathUtf8.c_str());
    state.clearPendingWaveforms();
    state.waveformWorker.cancelAllPending();
    // Do not synchronously delete/compact the whole waveform sidecar here.
    // At 1M+ rows that blocks the UI thread on the click path. Full rebuild
    // streams every audio file through the bounded rebuild cursor below and
    // overwrites cache rows as each worker result lands.
    state.waveformFailed.clear();
    state.waveformMiniCacheMiss.clear();
    const int64_t rebuildTotal = state.database.countAllFilesForWaveformRebuild();
    const int64_t detailTotal = state.database.countFilesEligibleForPersistentDetailCache();
    return StartWaveformRebuild(state, true, rebuildTotal, rebuildTotal, detailTotal);
}

static void MaybeStartAdaptiveMiniWaveformFormatUpgrade(AppState& state) {
    if (!state.adaptiveMiniWaveformFormatRebuildPending) return;
    if (!state.database.isOpen() || state.dbSwitchInProgress || state.waveformRebuildActive) return;
    aura::waveform_rebuild::DatabaseAdaptiveMiniFormatPreparationSource
        preparationSource(state.database);
    const auto preparation =
        aura::waveform_rebuild::PrepareAdaptiveMiniWaveformFormat(
            preparationSource,
            {state.adaptiveMiniWaveformFormatRebuildPending,
             state.adaptiveMiniWaveformFormatStampPending});
    state.adaptiveMiniWaveformFormatRebuildPending =
        preparation.state.rebuildPending;
    state.adaptiveMiniWaveformFormatStampPending =
        preparation.state.stampPending;
    if (preparation.decision == aura::waveform_rebuild::
            AdaptiveMiniFormatPreparationDecision::Disabled) {
        return;
    }

    DIAG_SYSTEM_FMT("Waveform",
                    "Adaptive mini format upgrade purge: purged=%d rebuildTotal=%lld db=%s",
                    preparation.purged,
                    (long long)preparation.rebuildTotal,
                    state.currentDbPathUtf8.c_str());

    if (preparation.decision == aura::waveform_rebuild::
            AdaptiveMiniFormatPreparationDecision::NoWork) {
        aura::waveform_rebuild::DatabaseAdaptiveMiniFormatStampPort stampPort(
            state.database);
        const auto finalization =
            aura::waveform_rebuild::FinalizeAdaptiveMiniWaveformFormat(
                stampPort,
                aura::waveform_rebuild::
                    AdaptiveMiniFormatFinalizationReason::NoWork,
                {state.adaptiveMiniWaveformFormatRebuildPending,
                 state.adaptiveMiniWaveformFormatStampPending});
        state.adaptiveMiniWaveformFormatRebuildPending =
            finalization.state.rebuildPending;
        state.adaptiveMiniWaveformFormatStampPending =
            finalization.state.stampPending;
        return;
    }

    const bool startSucceeded = StartWaveformRebuild(
        state,
        false,
        preparation.rebuildTotal,
        preparation.rebuildTotal,
        0);
    const auto activation =
        aura::waveform_rebuild::ActivateAdaptiveMiniWaveformRebuild(
            startSucceeded,
            {state.waveformRebuildMiniOnlyMode,
             g_waveformRebuildRuntimeState.incrementalMiniOnly(),
             state.adaptiveMiniWaveformFormatRebuildPending,
             state.adaptiveMiniWaveformFormatStampPending});
    if (activation.activated) {
        state.waveformRebuildMiniOnlyMode =
            activation.state.waveformRebuildMiniOnlyMode;
        g_waveformRebuildRuntimeState.setIncrementalMiniOnly(
            activation.state.incrementalMiniOnly);
        state.adaptiveMiniWaveformFormatRebuildPending =
            activation.state.rebuildPending;
        state.adaptiveMiniWaveformFormatStampPending =
            activation.state.stampPending;
        DIAG_SYSTEM_FMT("Waveform",
                        "Adaptive mini format upgrade rebuild started: total=%lld db=%s",
                        (long long)preparation.rebuildTotal,
                        state.currentDbPathUtf8.c_str());
    }
}

static void PumpWaveformRebuild(AppState& state) {
    if (!state.waveformRebuildActive) return;
    if (state.waveformRebuildCancel) {
        aura::waveform_rebuild::DatabaseAdaptiveMiniFormatStampPort stampPort(
            state.database);
        aura::waveform_rebuild::
            WaveformRebuildCancellationRecoveryStateAdapter recoveryAdapter(
                state, g_waveformRebuildRuntimeState);
        recoveryAdapter.recover(
            stampPort,
            {state.adaptiveMiniWaveformFormatRebuildPending,
             state.adaptiveMiniWaveformFormatStampPending});
        return;
    }
    const int capacityWorkerPending = state.waveformWorker.pendingCount();
    const auto capacityGate =
        aura::waveform_rebuild::EvaluateWaveformRebuildCapacityGate(
            {state.waveformUrgentPending.size(),
             state.waveformNormalPending.size(),
             (size_t)capacityWorkerPending,
             WAVEFORM_REBUILD_QUEUE_THRESHOLD});
    size_t pending = capacityGate.pending;
    if (capacityGate.wait) return;

    aura::waveform_rebuild::WaveformRebuildBatchGateInput batchGateInput{
        state.waveformRebuildBatchIdx,
        state.waveformRebuildBatch.size(),
        state.waveformRebuildProgress,
        state.waveformRebuildOffset,
        0};
    if (aura::waveform_rebuild::
            ShouldSampleWaveformRebuildDrain(batchGateInput)) {
        // Wait only for the worker thread queue to drain before fetching next batch.
        // UI browsing queues (urgent/normal) are continuously replenished by the
        // file list renderer and must NOT block rebuild completion.
        batchGateInput.workerPending =
            (size_t)state.waveformWorker.pendingCount();
    }
    const auto batchGate =
        aura::waveform_rebuild::EvaluateWaveformRebuildBatchGate(batchGateInput);
    if (batchGate == aura::waveform_rebuild::
            WaveformRebuildBatchGateDecision::WaitForDrain) return;
    if (batchGate == aura::waveform_rebuild::
            WaveformRebuildBatchGateDecision::LoadBatch) {
        aura::waveform_rebuild::DatabaseWaveformRebuildBatchSource source(state.database);
        aura::waveform_rebuild::DatabaseAdaptiveMiniFormatStampPort stampPort(
            state.database);
        auto lifecycle =
            aura::waveform_rebuild::LoadWaveformRebuildBatchLifecycle(
            source,
            stampPort,
            state.waveformRebuildQueuedIds,
            {{state.waveformRebuildFullMode,
              g_waveformRebuildRuntimeState.incrementalMiniOnly(),
              WAVEFORM_REBUILD_BATCH_SIZE,
              state.waveformRebuildOffset},
             {state.adaptiveMiniWaveformFormatRebuildPending,
              state.adaptiveMiniWaveformFormatStampPending}});
        state.waveformRebuildBatch = std::move(lifecycle.records);
        g_waveformRebuildRuntimeState.setBatchMiniOnly(
            lifecycle.batchMiniOnly);
        state.waveformRebuildBatchIdx = lifecycle.batchIndex;
        state.adaptiveMiniWaveformFormatRebuildPending =
            lifecycle.finalization.state.rebuildPending;
        state.adaptiveMiniWaveformFormatStampPending =
            lifecycle.finalization.state.stampPending;
        if (lifecycle.decision == aura::waveform_rebuild::
                WaveformRebuildBatchLifecycleDecision::RebuildCompleted) {
            if (lifecycle.finalization.stampAttempted) {
                DIAG_SYSTEM_FMT("Waveform",
                                "Adaptive mini format upgrade stamp: ok=%d db=%s",
                                lifecycle.finalization.stampSucceeded ? 1 : 0,
                                state.currentDbPathUtf8.c_str());
            }
            DIAG_SYSTEM_FMT("Database",
                "Waveform rebuild complete: mode=%s total=%lld progress=%lld skipped=%d failed=%d",
                state.waveformRebuildFullMode ? "full" : "incremental",
                (long long)state.waveformRebuildTotal,
                (long long)state.waveformRebuildProgress,
                state.waveformRebuildSkipped,
                state.waveformRebuildFailed);
            g_waveformRebuildRuntimeState.Reset(state, false);
            return;
        }
    }
    aura::waveform_rebuild::DatabaseWaveformRebuildFailureSink failureSink(
        state.database);
    aura::waveform_rebuild::WaveformWorkerRebuildSubmissionPort submissionPort(
        state.waveformWorker);
    for (int n = 0; n < WAVEFORM_REBUILD_PER_FRAME &&
                    pending < WAVEFORM_REBUILD_QUEUE_THRESHOLD &&
                    state.waveformRebuildBatchIdx < (int)state.waveformRebuildBatch.size(); n++) {
        const auto recordResult =
            aura::waveform_rebuild::ProcessNextWaveformRebuildRecord(
                failureSink,
                submissionPort,
                state.waveformRebuildQueuedIds,
                state.waveformFailed,
                {state.waveformRebuildBatch,
                 {state.waveformRebuildBatchIdx,
                  state.waveformRebuildOffset,
                  state.waveformRebuildProgress,
                  state.waveformRebuildFailed,
                  state.waveformRebuildSkipped,
                  pending},
                 state.waveformRebuildFullMode,
                 g_waveformRebuildRuntimeState.incrementalMiniOnly(),
                 g_waveformRebuildRuntimeState.batchMiniOnly()});
        state.waveformRebuildBatchIdx = recordResult.state.batchIndex;
        state.waveformRebuildOffset = recordResult.state.offset;
        state.waveformRebuildProgress = recordResult.state.progress;
        state.waveformRebuildFailed = recordResult.state.failed;
        state.waveformRebuildSkipped = recordResult.state.skipped;
        pending = recordResult.state.pending;
    }
}

class AppScanWaveformBackfillDrainPorts final
    : public aura::backfill::ScanWaveformBackfillObservationPort,
      public aura::backfill::ScanWaveformBackfillQueuePort,
      public aura::backfill::ScanWaveformBackfillRecordPort,
      public aura::backfill::ScanWaveformBackfillSubmissionPort {
public:
    explicit AppScanWaveformBackfillDrainPorts(AppState& state)
        : state_(state) {}

    bool admissionScanning() const override {
        return state_.isScanning.load(std::memory_order_acquire);
    }
    bool batchScanning() const override {
        return state_.isScanning.load();
    }
    bool reconcileScanRunning() const override {
        return state_.database.isReconcileScanRunning();
    }
    std::size_t urgentPending() const override {
        return state_.waveformUrgentPending.size();
    }
    std::size_t normalPending() const override {
        return state_.waveformNormalPending.size();
    }
    std::size_t workerPending() const override {
        return static_cast<std::size_t>(state_.waveformWorker.pendingCount());
    }

    int queuedWaveformCount() const override {
        return state_.backfillQueue.snapshot().byKind[
            static_cast<int>(aura::BackfillJobKind::WaveformL1Overview)];
    }
    bool tryDequeueWaveform(aura::BackfillJob& job) override {
        return state_.backfillQueue.tryDequeueKind(
            aura::BackfillJobKind::WaveformL1Overview, job);
    }
    void reportOutcome(
        const aura::BackfillJob& job,
        aura::BackfillCompletionOutcome outcome) override {
        state_.backfillQueue.reportOutcome(job, outcome);
    }
    aura::BackfillItemState itemState(
        std::int64_t fileId,
        aura::BackfillJobKind kind) const override {
        return state_.backfillQueue.itemState(fileId, kind);
    }

    std::vector<aura::backfill::ScanWaveformBackfillRecordRef> loadByIds(
        const std::vector<std::int64_t>& ids) override {
        const auto loaded = state_.database.getFilesByIds(ids);
        std::vector<aura::backfill::ScanWaveformBackfillRecordRef> records;
        records.reserve(loaded.size());
        for (const auto& record : loaded) {
            records.push_back({record.id, record.filePath});
        }
        return records;
    }
    bool markForegroundMiniFailed(
        std::int64_t sessionId,
        std::int64_t fileId,
        const char* reason) override {
        return state_.database.markScanForegroundMiniTerminal(
            sessionId,
            fileId,
            ScanForegroundTerminalState::Failed,
            reason);
    }
    void clearPending(
        std::int64_t fileId,
        aura::BackfillJobKind kind) override {
        state_.database.clearBackfillPending(
            fileId, static_cast<int>(kind));
    }
    bool submit(
        const std::string& filePath,
        const aura::BackfillJob& job) override {
        return state_.waveformWorker.submitBackfillDetailRequest(filePath, job);
    }

private:
    AppState& state_;
};

static void PumpScanWaveformBackfillQueue(AppState& state) {
    if (!state.database.isOpen()) return;
    if (state.waveformRebuildActive) return;
    const bool foregroundCompletionActive =
        state.scanCompletionPending.load(std::memory_order_acquire);
    // Automatic L1 waveform backfill is disabled by default. Product
    // semantics: only current-file playback, explicit rebuild, or scan-time
    // cache actions may decode uncached source audio.
    bool autoBackfillEnabled = false;
#ifdef _WIN32
    char* autoBackfill = nullptr;
    size_t autoBackfillLen = 0;
    if (_dupenv_s(&autoBackfill, &autoBackfillLen, "AURA_ENABLE_WAVEFORM_BACKFILL_DRAIN") == 0 &&
        autoBackfill && std::strcmp(autoBackfill, "1") == 0) {
        autoBackfillEnabled = true;
    }
    if (autoBackfill) free(autoBackfill);
#else
    const char* autoBackfill = std::getenv("AURA_ENABLE_WAVEFORM_BACKFILL_DRAIN");
    autoBackfillEnabled = autoBackfill && std::strcmp(autoBackfill, "1") == 0;
#endif
    AppScanWaveformBackfillDrainPorts ports(state);
    aura::backfill::DrainScanWaveformBackfillQueue(
        ports,
        ports,
        ports,
        ports,
        {foregroundCompletionActive, autoBackfillEnabled});
}

static bool MarkScanForegroundMiniTerminalForJob(AppState& state,
                                                 const aura::BackfillJob& job,
                                                 bool success,
                                                 const std::string& reason) {
    if (job.scanSessionId <= 0 ||
        job.kind != aura::BackfillJobKind::WaveformL1Overview) {
        return true;
    }
    return state.database.markScanForegroundMiniTerminal(
        job.scanSessionId,
        job.fileId,
        success ? ScanForegroundTerminalState::Cached : ScanForegroundTerminalState::Failed,
        reason);
}

static bool CanClearBackfillPendingForJob(AppState& state,
                                          const aura::BackfillJob& job,
                                          bool success,
                                          const std::string& reason) {
    return MarkScanForegroundMiniTerminalForJob(state, job, success, reason);
}

static aura::record_rescan::SelectedRecordRescanItem MakeSelectedRecordRescanItem(
    const AudioRecord& record,
    std::size_t sourceIndex) {
    aura::record_rescan::SelectedRecordRescanItem item;
    item.sourceIndex = sourceIndex;
    item.filePath = record.filePath;
    item.title = record.title;
    item.artist = record.artist;
    item.album = record.album;
    item.description = record.description;
    item.category = record.category;
    item.keywords = record.keywords;
    item.extendedMetadata = record.meta;
    item.sampleRate = record.sampleRate;
    item.channels = record.channels;
    item.totalFrames = record.totalFrames;
    item.durationSeconds = record.durationSeconds;
    return item;
}

class AppSelectedRecordRescanOperationPort final
    : public aura::record_rescan::SelectedRecordRescanOperationPort {
public:
    AppSelectedRecordRescanOperationPort(
        AppState& state,
        const std::vector<AudioRecord>& records)
        : state_(state), records_(records) {}

    aura::record_rescan::SelectedRecordRescanFileFacts observeFile(
        const std::string& filePath) override {
        const auto info = Platform::FileSystem::ProbeRegularFile(filePath);
        return {info.isRegularFile, info.sizeAvailable, info.sizeBytes};
    }

    bool readMetadata(
        const std::string& filePath,
        aura::record_rescan::SelectedRecordRescanMetadata& out) override {
        AudioMetadata metadata;
        if (!MetadataReader::readMetadata(filePath, metadata)) return false;
        out.title = metadata.title;
        out.artist = metadata.artist;
        out.album = metadata.album;
        out.description = metadata.description;
        out.category = metadata.category;
        out.genre = metadata.genre;
        out.keywords = metadata.keywords;
        out.comment = metadata.comment;
        PopulateExtendedMeta(out.extendedMetadata, metadata);
        return true;
    }

    bool wasDecoderInitFailure(const std::string& filePath) override {
        WaveformCacheState previous;
        return state_.database.getWaveformCacheStateByPath(filePath, previous) &&
               previous.status == "failed" &&
               previous.errorCode == "decoder_init_failed";
    }

    bool probeAudio(
        const std::string& filePath,
        aura::record_rescan::SelectedRecordRescanAudioFacts& facts) override {
        return state_.database.probeAudioFileInfo(
            filePath,
            facts.sampleRate,
            facts.channels,
            facts.totalFrames,
            facts.durationSeconds);
    }

    std::int64_t lastWriteTimeUnixSeconds(
        const std::string& filePath) override {
        return Platform::FileSystem::LastWriteTimeUnixSeconds(filePath);
    }

    std::int64_t nowUnixSeconds() override {
        return static_cast<std::int64_t>(std::time(nullptr));
    }

    bool updateRecord(
        const aura::record_rescan::SelectedRecordRescanItem& item,
        const aura::record_rescan::SelectedRecordRescanUpdate& update) override {
        if (item.sourceIndex >= records_.size()) return false;
        AudioRecord record = records_[item.sourceIndex];
        record.title = update.title;
        record.artist = update.artist;
        record.album = update.album;
        record.description = update.description;
        record.category = update.category;
        record.keywords = update.keywords;
        record.meta = update.extendedMetadata;
        record.sampleRate = update.sampleRate;
        record.channels = update.channels;
        record.totalFrames = update.totalFrames;
        record.durationSeconds = update.durationSeconds;
        record.fileSize = static_cast<int64_t>(update.fileSize);
        record.fileMtime = update.fileMtime;
        record.lastIndexed = update.lastIndexed;
        return state_.database.updateFile(record);
    }

    void clearWaveformCache(const std::string& filePath) override {
        state_.database.clearWaveformCacheByPath(filePath);
    }

private:
    AppState& state_;
    const std::vector<AudioRecord>& records_;
};

#ifdef _WIN32
static int ProcessSelectedRecordRescanSEH(
    const aura::record_rescan::SelectedRecordRescanItem& item,
    aura::record_rescan::SelectedRecordRescanOperationPort& port) {
    __try {
        return static_cast<int>(aura::record_rescan::RescanSelectedRecord(item, port));
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return -1;
    }
}
#endif

class AppSelectedRecordRescanBatchPort final
    : public aura::record_rescan::SelectedRecordRescanBatchPort {
public:
    AppSelectedRecordRescanBatchPort(
        AppState& state,
        aura::record_rescan::SelectedRecordRescanOperationPort& operation)
        : state_(state), operation_(operation) {}

    bool beginTransaction() override {
        return state_.database.beginTransaction();
    }

    aura::record_rescan::SelectedRecordRescanItemResult processProtected(
        const aura::record_rescan::SelectedRecordRescanItem& item) override {
#ifdef _WIN32
        const int result = ProcessSelectedRecordRescanSEH(item, operation_);
        if (result < 0) {
            DiagnosticsLogger::instance().logAction(
                "Rescan.FileCrash",
                (item.filePath + " | SEH exception caught").c_str());
            return aura::record_rescan::SelectedRecordRescanItemResult::Failed;
        }
        return static_cast<aura::record_rescan::SelectedRecordRescanItemResult>(result);
#else
        try {
            return aura::record_rescan::RescanSelectedRecord(item, operation_);
        } catch (...) {
            return aura::record_rescan::SelectedRecordRescanItemResult::Failed;
        }
#endif
    }

    bool commitTransaction() override {
        const bool committed = state_.database.commitTransaction();
        if (!committed) state_.database.rollbackTransaction();
        return committed;
    }

private:
    AppState& state_;
    aura::record_rescan::SelectedRecordRescanOperationPort& operation_;
};

static void RescanSelectedFiles(AppState& state, const std::vector<AudioRecord>& records) {
    if (records.empty()) return;

    std::vector<aura::record_rescan::SelectedRecordRescanItem> items;
    items.reserve(records.size());
    for (std::size_t index = 0; index < records.size(); ++index) {
        items.push_back(MakeSelectedRecordRescanItem(records[index], index));
    }
    AppSelectedRecordRescanOperationPort operation(state, records);
    AppSelectedRecordRescanBatchPort batch(state, operation);
    const auto result = aura::record_rescan::RescanSelectedRecords(items, batch);

    if (result.updated > 0 || result.failed > 0) {
        std::string msg;
        if (result.updated > 0) {
            msg = std::to_string(result.updated) + u8" 个文件元数据已更新";
        }
        if (result.failed > 0) {
            if (!msg.empty()) msg += u8"，";
            msg += std::to_string(result.failed) + u8" 个失败";
        }
        state.loadErrorToast = msg;
        state.loadErrorToastUntil = ImGui::GetTime() + 4.0;
    }

    // Keep searchResults alive while the table row still references its record.
    // Clearing the vector inside the ImGui row loop would dangle that reference.
    // The asynchronous refresh replaces results after rendering completes.

    RefreshSearchResults(state, false);
}

// Rebuild waveforms for selected files
static void RebuildWaveformsForSelected(AppState& state, const std::vector<AudioRecord>& records) {
    std::vector<SelectedWaveformRebuildItem> items;
    items.reserve(records.size());

    for (const auto& record : records) {
        if (record.filePath.empty()) continue;
        SelectedWaveformRebuildItem item;
        item.id = record.id;
        item.filePath = record.filePath;
        items.push_back(std::move(item));
    }

    g_selectedWaveformRebuildWorkflow.start(items);

    const int rebuildThreads = 2;
    state.waveformWorker.start(&state.database, rebuildThreads);
    state.waveformWorker.ensureThreadCount(rebuildThreads);

    DIAG_SYSTEM_FMT("Waveform",
        "Manual rebuild selected waveforms queued: count=%d unique=%zu",
        (int)records.size(),
        g_selectedWaveformRebuildWorkflow.remaining());
}

static void ShowCurrentFileWaveformRebuildToast(AppState& state) {
    const auto life = g_selectedWaveformRebuildWorkflow.lifecycle();
    switch (life.state) {
        case aura::waveform_rebuild::SelectedWaveformRebuildLifecycle::Running:
            state.loadErrorToast = u8"正在重建当前文件波形";
            state.loadErrorToastUntil = ImGui::GetTime() + 8.0;
            break;
        case aura::waveform_rebuild::SelectedWaveformRebuildLifecycle::Completed:
            state.loadErrorToast = L(Wf_RebuildDone);
            state.loadErrorToastUntil = ImGui::GetTime() + 4.0;
            break;
        case aura::waveform_rebuild::SelectedWaveformRebuildLifecycle::Failed:
            state.loadErrorToast = life.message == "missing"
                ? L(Wave_RebuildMissing)
                : L(Wave_RebuildFailed);
            state.loadErrorToastUntil = ImGui::GetTime() + 4.0;
            break;
        case aura::waveform_rebuild::SelectedWaveformRebuildLifecycle::Cancelled:
            state.loadErrorToast = L(Wave_RebuildCancelled);
            state.loadErrorToastUntil = ImGui::GetTime() + 3.0;
            break;
        default:
            break;
    }
}

static void RebuildCurrentFileMainWaveform(AppState& state) {
    if (!state.database.isOpen()) return;
    if (!state.audioEngine.isLoaded()) return;

    const std::string loadedPath = state.audioEngine.getLoadedFilePath();
    if (loadedPath.empty()) return;

    SelectedWaveformRebuildItem item;
    item.id = state.currentFileId;
    item.filePath = loadedPath;
    const auto decision = g_selectedWaveformRebuildWorkflow.queueCurrentFile(
        item,
        PathExistsUtf8(loadedPath));
    if (decision ==
        aura::waveform_rebuild::SelectedWaveformRebuildQueueDecision::Queued) {
        const int rebuildThreads = 2;
        state.waveformWorker.start(&state.database, rebuildThreads);
        state.waveformWorker.ensureThreadCount(rebuildThreads);
        DIAG_SYSTEM_FMT(
            "Waveform",
            "Manual rebuild current file waveform queued: %s",
            loadedPath.c_str());
    }
    ShowCurrentFileWaveformRebuildToast(state);
}

void ShutdownSelectedWaveformRebuild() {
    g_selectedWaveformRebuildWorkflow.shutdown();
}

class AppSelectedWaveformRebuildPorts final
    : public aura::waveform_rebuild::SelectedWaveformRebuildStoragePort,
      public aura::waveform_rebuild::SelectedWaveformRebuildEffectsPort {
public:
    explicit AppSelectedWaveformRebuildPorts(AppState& state) : state_(state) {}

    bool beginTransaction() override {
        return state_.database.beginTransaction();
    }
    bool clearWaveformCacheByPath(const std::string& filePath) override {
        return state_.database.clearWaveformCacheByPath(filePath);
    }
    bool commitTransaction() override {
        return state_.database.commitTransaction();
    }
    void rollbackTransaction() override {
        state_.database.rollbackTransaction();
    }
    bool miniOnlyPolicy() const override {
        return state_.database.getWaveformCacheMode() ==
               WaveformCachePolicy::Mode::MiniOnly;
    }

    std::string loadedFilePath() const override {
        return state_.audioEngine.isLoaded()
            ? state_.audioEngine.getLoadedFilePath()
            : std::string();
    }
    void clearWaveformUiCachesForPath(const std::string& filePath) override {
        ClearWaveformUiCachesForPath(state_, filePath);
    }
    void addPendingWaveform(
        const std::string& filePath,
        bool detail) override {
        state_.addPendingWaveform(filePath, detail);
    }
    bool isLoadedItem(
        const SelectedWaveformRebuildItem& item,
        const std::string& loadedPath) const override {
        return (item.id > 0 && item.id == state_.currentFileId) ||
               NormalizePathForWaveformCompare(item.filePath) ==
                   NormalizePathForWaveformCompare(loadedPath);
    }
    void forceLoadedItem(const SelectedWaveformRebuildItem&) override {
        state_.pendingDetailFilePath.clear();
        state_.pendingDetailTime = 0.0;
        state_.pendingDetailPeaks = 0;
        state_.audioEngine.clearCurrentWaveformVisual();
        state_.audioEngine.forceRegenerateWaveform(
            AppState::WAVEFORM_DEFAULT_DETAIL_PEAKS);
    }
    void reportTransactionCommitFailure() override {
        DIAG_SYSTEM(
            "Waveform",
            "Manual rebuild selected waveforms: transaction commit failed");
    }
    void reportForcedCurrent(
        const SelectedWaveformRebuildItem& item) override {
        DIAG_SYSTEM_FMT(
            "Waveform",
            "Manual rebuild selected current waveform forced: id=%lld path=%s",
            (long long)item.id,
            item.filePath.c_str());
    }
    void reportCompleted(
        const aura::waveform_rebuild::SelectedWaveformRebuildStats& stats)
        override {
        DIAG_SYSTEM_FMT(
            "Waveform",
            "Manual rebuild selected waveforms complete: cleared=%d queued=%d pending=%d",
            stats.cleared,
            stats.queued,
            stats.pending);
    }

private:
    AppState& state_;
};

static void PumpSelectedWaveformRebuild(AppState& state) {
    if (!g_selectedWaveformRebuildWorkflow.active()) return;
    if (state.waveformRebuildActive) return;

    AppSelectedWaveformRebuildPorts ports(state);
    aura::waveform_rebuild::WaveformWorkerRebuildSubmissionPort submissionPort(
        state.waveformWorker);
    g_selectedWaveformRebuildWorkflow.pump(
        ports,
        ports,
        submissionPort,
        {false, state.database.isOpen()});
}

// Remove records from database only
static void RemoveRecordsFromDatabase(AppState& state, const std::vector<int64_t>& ids) {
    if (ids.empty()) return;

    aura::records::RemoveRecordsFromDatabase(state.database, ids);

    // 立即从当前 UI 列表中剔除，实现无感瞬间刷新
    state.searchResults.erase(std::remove_if(state.searchResults.begin(), state.searchResults.end(),
        [&ids](const AudioRecord& r) {
            return std::find(ids.begin(), ids.end(), r.id) != ids.end();
        }), state.searchResults.end());

    // 触发 UI 层面的强制刷新
    aura::cover_wall::RequestDatabaseInvalidation(state);
    state.currentCoverFacets.clear();

    // 若正在播放的文件被移除，停止播放
    if (std::find(ids.begin(), ids.end(), state.currentFileId) != ids.end()) {
        state.audioEngine.stop();
        state.currentFileId = -1;
    }

    // Refresh
    state.setFolderHierarchy(state.database.getFolderHierarchy(state.settings.folderTreePathMode), state.currentDbPathUtf8);
    RefreshSearchResults(state, true);
    state.selectedResultIndex = -1;
}

// Delete files from file system and remove from database
static void DeleteFilesFromSystem(AppState& state, const std::vector<int64_t>& ids, const std::vector<std::string>& paths) {
    if (ids.empty() || paths.empty()) return;

    const aura::records::FileDeletionOutcome outcome =
        aura::records::DeleteFilesFromSystem(
        state.database, state.audioEngine, ids, paths);

    // Report any failures via the loadErrorToast
    if (!outcome.filesystemFailures.empty()) {
        { char rmb[256]; std::snprintf(rmb, sizeof(rmb), L(Fs_DeleteFilesBlockedFmt),
                      std::to_string(outcome.filesystemFailures.size()).c_str()); state.loadErrorToast = rmb; }
        state.loadErrorToastUntil = ImGui::GetTime() + 5.0;
    }

    // 立即从当前 UI 列表中剔除
    state.searchResults.erase(std::remove_if(state.searchResults.begin(), state.searchResults.end(),
        [&ids](const AudioRecord& r) {
            return std::find(ids.begin(), ids.end(), r.id) != ids.end();
        }), state.searchResults.end());

    // 触发 UI 层面的强制刷新
    aura::cover_wall::RequestDatabaseInvalidation(state);
    state.currentCoverFacets.clear();

    // 若正在播放的文件被删除，确保 currentFileId 已清空（unload 已在上方处理）
    if (std::find(ids.begin(), ids.end(), state.currentFileId) != ids.end())
        state.currentFileId = -1;

    // Refresh — use resetPagination=false to preserve scroll; in-place erase already removed items
    state.setFolderHierarchy(state.database.getFolderHierarchy(state.settings.folderTreePathMode), state.currentDbPathUtf8);
    RefreshSearchResults(state, false);
    state.selectedResultIndex = -1;
}

// Rename file on disk and update database
bool RenameFileOnDisk(AppState& state,
                      int64_t recordId,
                      const std::string& oldPath,
                      const std::string& newFileName) {
    (void)recordId;

    const aura::records::RecordRenameOutcome outcome =
        aura::records::RenameFileAndDatabase(
        state.database, state.audioEngine, oldPath, newFileName);
    if (!outcome.success) return false;

    try {
        auto it = state.waveformCache.find(oldPath);
        if (it != state.waveformCache.end()) {
            WaveformData data = std::move(it->second);
            state.waveformCache.erase(it);
            state.waveformCache[outcome.newPath] = std::move(data);
        }

        // Update the renamed entry in-place so the user doesn't lose
        // their scroll position or selection. Full refresh is deferred
        // until the next natural trigger (filter change, etc.).
        for (auto& r : state.searchResults) {
            if (r.filePath == oldPath) {
                r.filePath = outcome.newPath;
                r.fileName = newFileName;
                break;
            }
        }

        // Reload the renamed file if it was playing before
        if (outcome.reloadRenamedAudio) {
            state.audioEngine.loadFileAsync(outcome.newPath);
        }

        return true;
    } catch (...) {
        // Rename failed — if we had unloaded the file, reload from original path
        if (!state.audioEngine.isLoaded()) {
            state.audioEngine.loadFileAsync(oldPath);
        }
        return false;
    }
}

// Batch Rename Helper Functions

static const char* GetRenameModeName(AppState::RenameMode mode) {
    switch (mode) {
        case AppState::RenameMode::TextReplace: return L(RenMode_Replace);
        case AppState::RenameMode::RegexReplace: return L(RenMode_Regex);
        case AppState::RenameMode::DeleteText: return L(RenMode_DeleteText);
        case AppState::RenameMode::AddPrefix: return L(RenMode_AddPrefix);
        case AppState::RenameMode::AddSuffix: return L(RenMode_AddSuffix);
        case AppState::RenameMode::DeleteStartChars: return L(RenMode_DeleteFrontN);
        case AppState::RenameMode::DeleteEndChars: return L(RenMode_DeleteEndN);
        case AppState::RenameMode::DeleteChinese: return L(RenMode_DeleteChinese);
        case AppState::RenameMode::DeleteEnglish: return L(RenMode_DeleteEnglish);
        case AppState::RenameMode::DeleteNumbers: return L(RenMode_DeleteDigits);
        case AppState::RenameMode::DeletePunctuation: return L(RenMode_DeletePunct);
        case AppState::RenameMode::UpperToTitle: return L(RenMode_CapToTitle);
        case AppState::RenameMode::TraditionalToSimplified: return L(RenMode_TradToSimp);
        case AppState::RenameMode::RemoveExtraBrackets: return L(RenMode_DeleteBrackets);
        case AppState::RenameMode::ExtractBracketContent: return L(RenMode_ExtractBrackets);
        case AppState::RenameMode::InsertSequenceNumber: return L(RenMode_InsertSeq);
        case AppState::RenameMode::ToLowercase: return L(RenMode_ToLower);
        case AppState::RenameMode::ToUppercase: return L(RenMode_ToUpper);
        case AppState::RenameMode::ReplaceSpaces: return L(RenMode_ReplaceSpaces);
        case AppState::RenameMode::TrimSpaces: return L(RenMode_TrimSpaces);
        case AppState::RenameMode::DeleteFromMatchedTextToEnd: return L(RenMode_DeleteFromMatched);
        default: return L(RenMode_Unknown);
    }
}

static const char* GetRenameModeDescription(AppState::RenameMode mode) {
    switch (mode) {
        case AppState::RenameMode::TextReplace: return L(RenDesc_Replace);
        case AppState::RenameMode::RegexReplace: return L(RenDesc_Regex);
        case AppState::RenameMode::DeleteText: return L(RenDesc_DeleteText);
        case AppState::RenameMode::AddPrefix: return L(RenDesc_AddPrefix);
        case AppState::RenameMode::AddSuffix: return L(RenDesc_AddSuffix);
        case AppState::RenameMode::DeleteStartChars: return L(RenDesc_DeleteFrontN);
        case AppState::RenameMode::DeleteEndChars: return L(RenDesc_DeleteEndN);
        case AppState::RenameMode::DeleteChinese: return L(RenDesc_DeleteChinese);
        case AppState::RenameMode::DeleteEnglish: return L(RenDesc_DeleteEnglish);
        case AppState::RenameMode::DeleteNumbers: return L(RenDesc_DeleteDigits);
        case AppState::RenameMode::DeletePunctuation: return L(RenDesc_DeletePunct);
        case AppState::RenameMode::UpperToTitle: return L(RenDesc_CapToTitle);
        case AppState::RenameMode::TraditionalToSimplified: return L(RenDesc_TradToSimp);
        case AppState::RenameMode::RemoveExtraBrackets: return L(RenDesc_DeleteBrackets);
        case AppState::RenameMode::ExtractBracketContent: return L(RenDesc_ExtractBrackets);
        case AppState::RenameMode::InsertSequenceNumber: return L(RenDesc_InsertSeq);
        case AppState::RenameMode::ToLowercase: return L(RenDesc_ToLower);
        case AppState::RenameMode::ToUppercase: return L(RenDesc_ToUpper);
        case AppState::RenameMode::ReplaceSpaces: return L(RenDesc_ReplaceSpaces);
        case AppState::RenameMode::TrimSpaces: return L(RenDesc_TrimSpaces);
        case AppState::RenameMode::DeleteFromMatchedTextToEnd: return L(RenMode_DeleteFromMatchedDesc);
        default: return "";
    }
}


// Generate rename preview for selected files
static void GenerateBatchRenamePreview(AppState& state) {
    const auto selectedRecords = state.getSelectedRecords();
    std::vector<aura::rename::PreviewInput> inputs;
    inputs.reserve(selectedRecords.size());
    for (const auto& record : selectedRecords) {
        inputs.push_back({record.fileName, record.filePath, record.id});
    }

    const aura::rename::PreviewLabels labels{
        L(RenStatus_NoRules),
        L(RenStatus_NoChange),
        L(RenStatus_EmptyName),
        L(RenStatus_Duplicate),
        L(RenStatus_Exists),
        u8"OK",
        L(RenStatus_Suffix),
    };
    state.renamePreviewList =
        aura::rename::BuildPreview(inputs, state.renameRuleQueue, labels);
}

// Execute batch rename
static void ExecuteBatchRename(AppState& state) {
    const aura::rename::BatchRenameExecutionLabels labels{
        u8"OK",
        L(RenStatus_Done),
        L(RenStatus_FileError),
        L(RenStatus_UnknownError),
    };
    const auto completedRenames = aura::rename::ExecuteEligibleRenames(
        state.renamePreviewList,
        labels,
        [&](int64_t recordId,
            const std::string& oldPath,
            const std::string& newName) {
            return RenameFileOnDisk(state, recordId, oldPath, newName);
        });

    // Register undo operation for successful renames (F-025)
    if (!completedRenames.empty()) {
        auto undoOp = std::make_unique<FileRenameOp>();
        for (const auto& completed : completedRenames) {
            undoOp->entries.push_back(
                {0, completed.oldPath, completed.newPath});
        }
        state.undoStack.push(std::move(undoOp));
    }

    state.setFolderHierarchy(state.database.getFolderHierarchy(state.settings.folderTreePathMode), state.currentDbPathUtf8);
    RefreshSearchResults(state, true);
    state.clearSelection();
}

// Helper: check if folder name matches search (case-insensitive)

// 模糊搜索：子串匹配 + 拼音首字母匹配（与主搜索能力同步）

static bool FolderMatchesSearch(const std::string& folderName, const std::string& searchLower) {
    if (searchLower.empty()) return true;
    if (folderName.length() < searchLower.length()) return false;

    // 1. 直接子串匹配（零分配，大多数情况在此命中）
    auto it = std::search(
        folderName.begin(), folderName.end(),
        searchLower.begin(), searchLower.end(),
        [](unsigned char ch1, unsigned char ch2) { return std::tolower(ch1) == ch2; }
    );
    if (it != folderName.end()) return true;

    // 2. 拼音首字母匹配：仅对纯 ASCII token 启用
    //    避免中文搜索词「怪」经 GetPinyinInitials 变成 "g" 后误匹配所有 g 开头的文件夹
    bool asciiOnly = true;
    for (unsigned char c : searchLower) {
        if (c > 127) { asciiOnly = false; break; }
    }
    if (asciiOnly) {
        std::string pinyin = GetPinyinInitials(folderName);
        if (pinyin.length() >= searchLower.length()) {
            // pinyin 和 searchLower 均为小写，直接字节比较
            auto it2 = std::search(pinyin.begin(), pinyin.end(),
                                   searchLower.begin(), searchLower.end());
            if (it2 != pinyin.end()) return true;
        }
    }

    return false;
}

// 多词搜索：文件夹名包含任一 token 即高亮
static bool FolderMatchesAnyToken(const std::string& folderName, const std::vector<std::string>& tokens) {
    for (const auto& token : tokens) {
        if (FolderMatchesSearch(folderName, token)) return true;
    }
    return false;
}

// 文件夹完整路径子串匹配（与主搜索 trigram 能力对齐）。
// 让深层文件夹（name 本身不含关键字但 path 含）也能直接命中，不依赖祖先回传。
// 例：搜 "bbc" 时 "Sound Ideas BBC/B-Series/B30017_Gun Shots/" 下面任一节点都应命中。
// 拼音首字母仅对 basename 应用（全路径拼音过长会引入误匹配）。
static bool FolderPathMatchesSearch(const std::string& folderPath, const std::string& searchLower) {
    if (searchLower.empty()) return true;
    if (folderPath.length() < searchLower.length()) return false;

    // 1. 整路径子串匹配（case-insensitive）
    auto it = std::search(
        folderPath.begin(), folderPath.end(),
        searchLower.begin(), searchLower.end(),
        [](unsigned char ch1, unsigned char ch2) { return std::tolower(ch1) == ch2; }
    );
    return (it != folderPath.end());
}

static bool FolderOrChildMatchesSearch(const FolderInfo& folder, const std::string& searchLower) {
    if (searchLower.empty()) return true;
    if (FolderMatchesSearch(folder.name, searchLower)) return true;
    // 整路径子串命中：深层文件夹的 name 可能不含关键字但 path 含（如 name=B30017_Gun
    // Shots 搜 "bbc" 时本节点 name 不含 bbc，但 path 包含 Sound Ideas BBC → 命中自身）
    if (FolderPathMatchesSearch(folder.path, searchLower)) return true;
    for (const auto& sub : folder.subfolders) {
        if (FolderOrChildMatchesSearch(sub, searchLower)) return true;
    }
    return false;
}

struct BrowserSystemFolderCacheEntry {
    bool loaded = false;
    bool loadFailed = false;
    std::vector<std::pair<std::string, std::string>> children;
};

static char g_browserSystemFolderSearchBuffer[128] = "";
static std::string g_browserSystemFolderSearchFocusRoot;
static std::string g_browserSystemFolderSearchSubmittedQuery;
static std::string g_browserSystemFolderSearchSubmittedFocusPath;
static std::vector<aura::browser::SystemFolderSearchHit> g_browserSystemFolderSearchResults;
static aura::browser::SystemFolderSearchRuntime g_browserSystemFolderSearchRuntime;
static bool g_browserSystemFolderSearchTruncated = false;
static std::string g_browserSystemFolderTreeScrollTarget;
static std::string g_browserSystemFolderRelatedPath;
static bool g_browserSystemFolderTreeExpandSearchHitsOnce = false;
static bool g_browserSystemFolderSearchNeedsFirstHitReveal = false;
static bool g_browserSystemFolderTreeCollapseAll = false;

static std::unordered_map<std::string, BrowserSystemFolderCacheEntry>& BrowserSystemFolderChildrenCache() {
    static std::unordered_map<std::string, BrowserSystemFolderCacheEntry> cache;
    return cache;
}

static void ResetBrowserSystemFolderTreeCache() {
    BrowserSystemFolderChildrenCache().clear();
}

static void SetBrowserSystemFolderSearchFocusRoot(const std::string& folderPath) {
    g_browserSystemFolderSearchFocusRoot = HarkenSearch::CanonicalFolderPath(folderPath);
}

static void ClearBrowserSystemFolderSearchState() {
    g_browserSystemFolderSearchRuntime.Cancel();
    g_browserSystemFolderSearchTruncated = false;
    g_browserSystemFolderSearchResults.clear();
    g_browserSystemFolderSearchSubmittedQuery.clear();
    g_browserSystemFolderSearchSubmittedFocusPath.clear();
    g_browserSystemFolderTreeScrollTarget.clear();
    g_browserSystemFolderRelatedPath.clear();
    g_browserSystemFolderTreeExpandSearchHitsOnce = false;
    g_browserSystemFolderSearchNeedsFirstHitReveal = false;
}

static std::vector<std::pair<std::string, std::string>>& BrowserSystemFolderRoots() {
    static std::vector<std::pair<std::string, std::string>> roots;
    if (!roots.empty()) {
        return roots;
    }
#ifdef _WIN32
    const DWORD driveMask = GetLogicalDrives();
    for (int i = 0; i < 26; ++i) {
        if ((driveMask & (1u << i)) == 0) continue;
        const char driveLetter = static_cast<char>('A' + i);
        std::string rootPath;
        rootPath.push_back(driveLetter);
        rootPath += ":\\";
        roots.push_back({rootPath, rootPath});
    }
#else
    roots.push_back({"/", "/"});
#endif
    return roots;
}

static BrowserSystemFolderCacheEntry& GetBrowserSystemFolderChildren(const std::string& folderPath) {
    auto& cache = BrowserSystemFolderChildrenCache();
    BrowserSystemFolderCacheEntry& entry = cache[folderPath];
    if (entry.loaded) {
        return entry;
    }

    entry.loaded = true;
    entry.loadFailed = false;
    try {
        Platform::FileSystem::DirectoryIterator iterator;
        if (!iterator.Open(folderPath, false, true)) {
            entry.loadFailed = true;
            return entry;
        }
        Platform::FileSystem::DirectoryEntry child;
        std::string iteratorError;
        while (iterator.Next(child, &iteratorError) ==
               Platform::FileSystem::DirectoryReadStatus::Entry) {
            if (!child.isDirectory) continue;
            std::string childPath = child.pathUtf8;
            std::string childName;
            try { childName = BaseNameFromUtf8Path(childPath); } catch (...) {}
            if (childName.empty()) {
                childName = childPath;
            }
            entry.children.push_back({childPath, childName});
        }
        if (!iteratorError.empty()) entry.loadFailed = true;
        std::sort(entry.children.begin(), entry.children.end(),
                  [](const auto& a, const auto& b) {
                      std::string aLower = a.second;
                      std::string bLower = b.second;
                      std::transform(aLower.begin(), aLower.end(), aLower.begin(), ::tolower);
                      std::transform(bLower.begin(), bLower.end(), bLower.begin(), ::tolower);
                      if (aLower == bLower) return a.first < b.first;
                      return aLower < bLower;
                  });
    } catch (...) {
        entry.loadFailed = true;
        entry.children.clear();
    }
    return entry;
}

static std::vector<aura::browser::SystemFolderSearchRoot> BrowserSystemFolderSearchRoots(const std::string& focusPath) {
    std::vector<aura::browser::SystemFolderSearchRoot> roots;
    std::unordered_set<std::string> seen;
    auto addRoot = [&](const std::string& path, const std::string& fallbackName) {
        if (path.empty()) return;
        const std::string canonical = HarkenSearch::CanonicalFolderPath(path);
        if (canonical.empty() || seen.count(canonical) > 0) return;
        std::string name;
        try { name = BaseNameFromUtf8Path(path); } catch (...) {}
        if (name.empty()) name = fallbackName.empty() ? path : fallbackName;
        roots.push_back({path, name});
        seen.insert(canonical);
    };

    const std::string canonicalFocus = HarkenSearch::CanonicalFolderPath(focusPath);
    if (!canonicalFocus.empty()) {
        addRoot(focusPath, focusPath);
        return roots;
    }

    for (const auto& root : BrowserSystemFolderRoots()) {
        addRoot(root.first, root.second);
    }
    return roots;
}

static void PollBrowserSystemFolderSearchTask() {
    aura::browser::SystemFolderSearchSnapshot snapshot;
    if (!g_browserSystemFolderSearchRuntime.Poll(snapshot)) {
        return;
    }
    g_browserSystemFolderSearchResults = std::move(snapshot.results);
    g_browserSystemFolderSearchTruncated = snapshot.truncated;
    if (g_browserSystemFolderSearchNeedsFirstHitReveal &&
        !g_browserSystemFolderSearchResults.empty()) {
        g_browserSystemFolderTreeScrollTarget = HarkenSearch::CanonicalFolderPath(g_browserSystemFolderSearchResults.front().path);
        g_browserSystemFolderTreeExpandSearchHitsOnce = true;
        g_browserSystemFolderSearchNeedsFirstHitReveal = false;
    }
}

static size_t BrowserSystemFolderSearchVisitedCount() {
    return g_browserSystemFolderSearchRuntime.VisitedCount();
}

static void RunBrowserSystemFolderSearchIfNeeded(bool forceRestart = false, const std::string& focusPath = std::string()) {
    PollBrowserSystemFolderSearchTask();

    const std::string query = TrimCopy(g_browserSystemFolderSearchBuffer);
    const std::string canonicalFocusPath = HarkenSearch::CanonicalFolderPath(focusPath);
    if (!forceRestart &&
        query == g_browserSystemFolderSearchSubmittedQuery &&
        canonicalFocusPath == g_browserSystemFolderSearchSubmittedFocusPath) {
        return;
    }

    g_browserSystemFolderSearchSubmittedQuery = query;
    g_browserSystemFolderSearchSubmittedFocusPath = canonicalFocusPath;
    g_browserSystemFolderSearchRuntime.Cancel();
    g_browserSystemFolderSearchTruncated = false;
    g_browserSystemFolderSearchResults.clear();
    g_browserSystemFolderTreeExpandSearchHitsOnce = false;
    g_browserSystemFolderSearchNeedsFirstHitReveal = false;

    if (query.empty()) {
        return;
    }

    g_browserSystemFolderSearchNeedsFirstHitReveal = true;

    const auto roots = BrowserSystemFolderSearchRoots(focusPath);
    g_browserSystemFolderSearchRuntime.Start(query, roots);
}

static void PrimeBrowserSystemFolderPathChain(const std::string& folderPath) {
    const auto chain = aura::browser::BuildSystemFolderPathChain(folderPath);
    for (const auto& part : chain) {
        if (!part.first.empty()) {
            (void)GetBrowserSystemFolderChildren(part.first);
        }
    }
}

static void LocateBrowserSystemFolderPath(const std::string& folderPath) {
    if (folderPath.empty()) {
        return;
    }
    SetBrowserSystemFolderSearchFocusRoot(folderPath);
    PrimeBrowserSystemFolderPathChain(folderPath);
    g_browserSystemFolderTreeScrollTarget = HarkenSearch::CanonicalFolderPath(folderPath);
}

static void QueueBrowserSystemFolderTreeLocate(const std::string& folderPath) {
    LocateBrowserSystemFolderPath(folderPath);
}

static void RenderBrowserSystemFolderContextMenu(AppState& state, const std::string& folderPath) {
    if (ImGui::MenuItem(L(Edit_RevealInExplorer))) {
        Platform::OpenInFileManager(folderPath);
    }
    if (ImGui::MenuItem(L(Browser_BookmarkFolder))) {
        AddBrowserFolderToQuickPaths(state, folderPath);
    }
    if (ImGui::MenuItem(L(Scan_QuickScan))) {
        QueueBrowserFolderScan(state, folderPath);
    }
    if (ImGui::MenuItem(L(Browser_AddFolderToLibrary))) {
        QueueBrowserFolderLibraryAdd(state, folderPath);
    }
}

static void RenderBrowserSystemFolderNode(AppState& state,
                                          const std::string& folderPath,
                                          const std::string& displayName) {
    BrowserSystemFolderCacheEntry& cache = GetBrowserSystemFolderChildren(folderPath);
    const bool hasChildren = !cache.children.empty();
    const std::string currentPath = state.fileBrowser.getCurrentPath();
    const std::string canonicalFolder = HarkenSearch::CanonicalFolderPath(folderPath);
    const std::string canonicalCurrent = HarkenSearch::CanonicalFolderPath(currentPath);
    const bool exactCurrentPath = !canonicalCurrent.empty() && canonicalCurrent == canonicalFolder;
    const bool currentPathMatches =
        exactCurrentPath ||
        (!canonicalCurrent.empty() &&
         aura::browser::IsSystemFolderAncestorOf(canonicalFolder, canonicalCurrent));

    ImGuiTreeNodeFlags flags = ImGuiTreeNodeFlags_OpenOnArrow |
                               ImGuiTreeNodeFlags_SpanAvailWidth |
                               ImGuiTreeNodeFlags_NoTreePushOnOpen;
    if (!hasChildren) {
        flags |= ImGuiTreeNodeFlags_Leaf;
    }
    if (exactCurrentPath) {
        flags |= ImGuiTreeNodeFlags_Selected;
    }
    if (g_browserSystemFolderTreeCollapseAll) {
        ImGui::SetNextItemOpen(false);
    } else if (!g_browserSystemFolderTreeCollapseAll && currentPathMatches) {
        ImGui::SetNextItemOpen(true, ImGuiCond_Once);
    }

    ImGui::PushID(folderPath.c_str());
    const bool opened = ImGui::TreeNodeEx(displayName.c_str(), flags);
    if (ImGui::IsItemToggledOpen() && opened && !folderPath.empty()) {
        g_browserSystemFolderRelatedPath = folderPath;
    }
    if (!g_browserSystemFolderTreeScrollTarget.empty() &&
        g_browserSystemFolderTreeScrollTarget == canonicalFolder) {
        ImGui::ScrollToItem();
        g_browserSystemFolderTreeScrollTarget.clear();
    }
    if (ImGui::IsItemClicked() && !folderPath.empty()) {
        SetBrowserSystemFolderSearchFocusRoot(folderPath);
        g_browserSystemFolderRelatedPath = folderPath;
        NavigateBrowserToFolder(state, folderPath, state.fileBrowser.getScope());
    }
    if (HoveredForHelp()) {
        HarkenSearch::SetTooltip("%s", folderPath.c_str());
    }

    if (ImGui::BeginPopupContextItem("##BrowserSystemFolderCtx")) {
        RenderBrowserSystemFolderContextMenu(state, folderPath);
        ImGui::EndPopup();
    }

    if (opened && hasChildren) {
        ImGui::Indent();
        for (const auto& child : cache.children) {
            RenderBrowserSystemFolderNode(state, child.first, child.second);
        }
        ImGui::Unindent();
    }
    ImGui::PopID();
}

static void RenderBrowserSystemFolderTree(AppState& state) {
    auto& roots = BrowserSystemFolderRoots();
    for (const auto& root : roots) {
        RenderBrowserSystemFolderNode(state, root.first, root.second);
    }
}

static void RenderBrowserSystemFolderSearchNode(AppState& state,
                                                const aura::browser::SystemFolderSearchTreeNode& node) {
    const std::string currentPath = state.fileBrowser.getCurrentPath();
    const std::string canonicalFolder = HarkenSearch::CanonicalFolderPath(node.path);
    const std::string canonicalCurrent = HarkenSearch::CanonicalFolderPath(currentPath);
    const bool exactCurrentPath = !canonicalCurrent.empty() && canonicalCurrent == canonicalFolder;

    ImGuiTreeNodeFlags flags = ImGuiTreeNodeFlags_OpenOnArrow |
                               ImGuiTreeNodeFlags_SpanAvailWidth |
                               ImGuiTreeNodeFlags_NoTreePushOnOpen;
    if (node.children.empty()) {
        flags |= ImGuiTreeNodeFlags_Leaf;
    }
    if (exactCurrentPath) {
        flags |= ImGuiTreeNodeFlags_Selected;
    }
    const bool shouldAutoOpen =
        g_browserSystemFolderTreeExpandSearchHitsOnce && !node.children.empty();
    if (shouldAutoOpen) {
        ImGui::SetNextItemOpen(true);
    }

    const ThemeColorScheme& theme = ThemeColors::current();
    if (node.directHit) {
        ImGui::PushStyleColor(ImGuiCol_Text, theme.filterBrowserSearchHitText);
    }
    ImGui::PushID(node.path.c_str());
    const bool opened = ImGui::TreeNodeEx(node.displayName.c_str(), flags);
    if (node.directHit && ImGui::IsItemVisible()) {
        ImVec2 rMin = ImGui::GetItemRectMin();
        ImVec2 rMax = ImGui::GetItemRectMax();
        rMin.x += ImGui::GetTreeNodeToLabelSpacing();
        const ImVec4 hitBg(theme.filterBrowserSearchHitText.x,
                           theme.filterBrowserSearchHitText.y,
                           theme.filterBrowserSearchHitText.z,
                           0.16f);
        ImGui::GetWindowDrawList()->AddRectFilled(rMin, rMax, ImGui::GetColorU32(hitBg), 3.0f);
    }
    if (node.directHit) {
        ImGui::PopStyleColor();
    }

    if (!g_browserSystemFolderTreeScrollTarget.empty() &&
        g_browserSystemFolderTreeScrollTarget == canonicalFolder) {
        ImGui::ScrollToItem();
        g_browserSystemFolderTreeScrollTarget.clear();
    }
    if (ImGui::IsItemClicked() && !node.path.empty()) {
        g_browserSystemFolderRelatedPath = node.path;
        NavigateBrowserToFolder(state, node.path, state.fileBrowser.getScope());
    }
    if (HoveredForHelp()) {
        HarkenSearch::SetTooltip("%s", node.path.c_str());
    }
    if (ImGui::BeginPopupContextItem("##BrowserSystemFolderSearchCtx")) {
        RenderBrowserSystemFolderContextMenu(state, node.path);
        ImGui::EndPopup();
    }
    if (ImGui::IsItemToggledOpen() && opened && !node.path.empty()) {
        g_browserSystemFolderRelatedPath = node.path;
    }
    if (opened && !node.children.empty()) {
        ImGui::Indent();
        for (const auto& child : node.children) {
            RenderBrowserSystemFolderSearchNode(state, child.second);
        }
        ImGui::Unindent();
    }
    ImGui::PopID();
}

static void RenderBrowserSystemFolderSearchTree(AppState& state) {
    const auto roots = aura::browser::BuildSystemFolderSearchTree(
        g_browserSystemFolderSearchResults);
    if (g_browserSystemFolderSearchRuntime.Busy()) {
        ImGui::TextDisabled(L(Main_FileCountsFmt),
                            L(Msg_Loading),
                            g_browserSystemFolderSearchResults.size(),
                            BrowserSystemFolderSearchVisitedCount());
        ImGui::Spacing();
    }
    if (roots.empty()) {
        ImGui::TextDisabled("%s", g_browserSystemFolderSearchRuntime.Busy() ? L(Msg_Loading) : L(Nav_NoRelatedPaths));
        return;
    }
    for (const auto& root : roots) {
        RenderBrowserSystemFolderSearchNode(state, root.second);
    }
    g_browserSystemFolderTreeExpandSearchHitsOnce = false;
}

static void ShowBrowserCurrentPathContextMenu(AppState& state,
                                              const std::string& currentPath,
                                              bool canNavigateUp) {
    if (currentPath.empty()) {
        return;
    }
    if (ImGui::BeginPopupContextItem("##BrowserCurrentPathCtx")) {
        if (canNavigateUp && ImGui::MenuItem(L(Filter_ParentDir))) {
            state.fileBrowser.navigateUp();
            SyncBrowserPathBuffer(state);
        }
        if (ImGui::MenuItem(L(Filter_OpenFolder))) {
            std::string folder = OpenFolderDialog(g_hwnd);
            if (!folder.empty()) {
                NavigateBrowserToFolder(state, folder, state.fileBrowser.getScope());
            }
        }
        ImGui::Separator();
        if (ImGui::MenuItem(L(Edit_RevealInExplorer))) {
            Platform::OpenInFileManager(currentPath);
        }
        if (ImGui::MenuItem(L(Browser_BookmarkFolder))) {
            AddBrowserFolderToQuickPaths(state, currentPath);
        }
        if (ImGui::MenuItem(L(Scan_QuickScan))) {
            QueueBrowserFolderScan(state, currentPath);
        }
        if (ImGui::MenuItem(L(Browser_AddFolderToLibrary))) {
            QueueBrowserFolderLibraryAdd(state, currentPath);
        }
        ImGui::Separator();
        if (ImGui::MenuItem(L(Ctx_CopyFolderPath))) {
            ImGui::SetClipboardText(currentPath.c_str());
        }
        ImGui::EndPopup();
    }
}

