static void RenderRelatedPathsExplorerPane(
    AppState& state,
    const char* childId,
    const char* splitterId,
    float minHeight,
    float maxHeight,
    const ExplorerShellCapabilities& capabilities,
    const std::function<void()>& renderRows)
{
    state.settings.sidebarRelatedPathsHeight = std::clamp(
        state.settings.sidebarRelatedPathsHeight,
        minHeight,
        maxHeight);
    const ThemeColorScheme& theme = ThemeColors::current();
    ImGui::PushStyleColor(ImGuiCol_ChildBg, theme.filterBrowserBG);
    ImGui::PushStyleColor(ImGuiCol_Border, theme.filterBrowserOutline);
    ImGui::PushStyleVar(ImGuiStyleVar_ChildRounding, 7.0f);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(8.0f, 6.0f));
    BeginTransientScrollbarChild(
        childId,
        ImVec2(0, state.settings.sidebarRelatedPathsHeight),
        true,
        ImGuiWindowFlags_AlwaysVerticalScrollbar);
    renderRows();
    ImGui::EndChild();
    ImGui::PopStyleVar(2);
    ImGui::PopStyleColor(2);
    if (capabilities.canResizeRelatedPaths) {
        if (HorizontalSplitter(
                splitterId,
                &state.settings.sidebarRelatedPathsHeight,
                minHeight,
                maxHeight,
                0.0f,
                true)) {
            MarkSettingsDirty(state);
        }
    } else {
        ImGui::Dummy(ImVec2(0.0f, 4.0f));
    }
}

static void RenderFolderTreeExplorerToolbar(
    const char* searchId,
    const char* searchHint,
    char* searchBuf,
    size_t searchBufSize,
    const char* refreshId,
    bool refreshBusy,
    const char* locateId,
    bool canLocate,
    bool inheritContextColors,
    bool drawLocateRipple,
    const std::function<void()>& onSearchEscape,
    const std::function<void()>& onRefresh,
    const std::function<void()>& onLocate,
    const std::function<void(bool hovered)>& onLocateHover)
{
    constexpr float kRefreshW = 26.0f;
    constexpr float kLocateW = 22.0f;
    constexpr float kBtnGap = 4.0f;
    constexpr float kSameLine = 4.0f;
    const float searchReserve = kSameLine + kRefreshW + kBtnGap + kLocateW + 2.0f;
    ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(4.0f, 3.0f));
    ImGui::PushStyleVar(ImGuiStyleVar_FramePadding, ImVec2(7.0f, 2.0f));
    const float searchWidth = std::max(80.0f, ImGui::GetContentRegionAvail().x - searchReserve);
    DrawUnifiedSearchInput(
        searchId,
        searchHint,
        searchBuf,
        searchBufSize,
        0,
        searchWidth,
        inheritContextColors);
    if (ImGui::IsItemFocused() && ImGui::IsKeyPressed(ImGuiKey_Escape, false)) {
        onSearchEscape();
        ImGui::ClearActiveID();
    }
    ImGui::SameLine(0, kSameLine);
    ImGui::PushStyleVar(ImGuiStyleVar_FramePadding, ImVec2(4, 1));
    ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(kBtnGap, 2));
    if (SidebarRefreshGlyphButton(refreshId, ImVec2(kRefreshW, 22.0f), refreshBusy)) {
        onRefresh();
    }
    if (HoveredForHelp()) {
        HarkenSearch::SetTooltip("%s", L(Nav_ReloadTree));
    }
    ImGui::SameLine();
    if (!canLocate) {
        ImGui::BeginDisabled();
    }
    {
        const float btnSize = kLocateW;
        const ImVec2 btnPos = ImGui::GetCursorScreenPos();
        ImGui::InvisibleButton(locateId, ImVec2(btnSize, btnSize));
        const bool locHovered = ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled);
        const bool locClicked = ImGui::IsItemClicked();
        ImDrawList* dl = ImGui::GetWindowDrawList();
        const ImVec2 center(btnPos.x + btnSize * 0.5f, btnPos.y + btnSize * 0.5f);
        const float maxR = btnSize * 0.40f;
        if (drawLocateRipple) {
            static float rippleStart = -10.f;
            const float rippleDuration = 0.5f;
            const float time = (float)ImGui::GetTime();
            if (locClicked && canLocate) {
                rippleStart = time;
            }
            const float elapsed = time - rippleStart;
            if (elapsed >= 0.f && elapsed < rippleDuration) {
                const float t = elapsed / rippleDuration;
                const float radius = maxR * 0.3f + btnSize * 0.7f * t;
                const ImU32 rippleCol = IM_COL32(100, 200, 150, (int)(140 * (1.0f - t * t)));
                dl->AddCircle(center, radius, rippleCol, 20, 1.2f);
            }
        }
        const ImU32 colRing = locHovered && canLocate
            ? IM_COL32(180, 180, 180, 200)
            : IM_COL32(90, 90, 90, 140);
        const ImU32 colDot = locHovered && canLocate
            ? IM_COL32(220, 220, 220, 255)
            : IM_COL32(140, 140, 140, 180);
        dl->AddCircle(center, maxR, colRing, 16, 1.2f);
        dl->AddCircleFilled(center, maxR * 0.25f, colDot, 8);
        if (locClicked && canLocate) {
            onLocate();
        }
        onLocateHover(locHovered);
    }
    if (!canLocate) {
        ImGui::EndDisabled();
    }
    ImGui::PopStyleVar(2);
    ImGui::PopStyleVar(2);
}

static void RenderFolderTreeExplorerList(
    const char* childId,
    float treeH,
    bool collapseAll,
    bool useRoundedChrome,
    const std::function<void()>& renderRows)
{
    const ThemeColorScheme& theme = ThemeColors::current();
    ImGui::PushStyleColor(ImGuiCol_ChildBg, theme.filterBrowserBG);
    ImGui::PushStyleColor(ImGuiCol_Border, theme.filterBrowserOutline);
    int styleVars = 0;
    if (useRoundedChrome) {
        ImGui::PushStyleVar(ImGuiStyleVar_ChildRounding, 7.0f);
        ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(6.0f, 6.0f));
        styleVars = 2;
    }
    BeginTransientScrollbarChild(childId, ImVec2(-1, treeH), true);
    if (collapseAll) {
        ImGuiWindow* tw = ImGui::GetCurrentWindow();
        if (tw && tw->DC.StateStorage) {
            tw->DC.StateStorage->Clear();
        }
    }
    renderRows();
    ImGui::EndChild();
    if (styleVars > 0) {
        ImGui::PopStyleVar(styleVars);
    }
    ImGui::PopStyleColor(2);
}

static void RenderExplorerShell(
    const std::function<void()>& renderRelatedPaths,
    const std::function<void()>& renderToolbar,
    const std::function<void()>& renderTreeList)
{
    renderRelatedPaths();
    renderToolbar();
    renderTreeList();
}

static void RenderBrowserFolderTreeSidebarPanel(AppState& state) {
    constexpr float kBrowserSidebarTreeMinHeight = 140.0f;
    constexpr float kBrowserRelatedPathsMinHeight = 72.0f;
    const std::string currentBrowserPath = state.fileBrowser.getCurrentPath();
    RunBrowserSystemFolderSearchIfNeeded(false, g_browserSystemFolderSearchFocusRoot);

    const float relatedPathsMaxHeight = std::max(
        kBrowserRelatedPathsMinHeight,
        ImGui::GetContentRegionAvail().y - kBrowserSidebarTreeMinHeight - 8.0f);

    const bool canLocateCurrent = !state.fileBrowser.getCurrentPath().empty();
    const ExplorerSource browserSource = BrowserExplorerSource();
    const ExplorerShellCapabilities browserCaps = browserSource.capabilities;
    RenderExplorerShell(
        [&state, relatedPathsMaxHeight, browserSource, browserCaps, kBrowserRelatedPathsMinHeight]() {
            ImGui::TextDisabled("%s", L(Nav_RelatedPaths));
            if (!g_browserSystemFolderRelatedPath.empty()) {
                ImGui::SameLine();
                ImGui::TextDisabled(L(Main_DotPrefixFmt), g_browserSystemFolderRelatedPath.c_str());
            }
            RenderRelatedPathsExplorerPane(
                state,
                browserSource.relatedPathsChildId,
                browserSource.relatedPathsSplitterId,
                kBrowserRelatedPathsMinHeight,
                relatedPathsMaxHeight,
                browserCaps,
                [&state]() {
                    // Browser folder search mirrors the database folder-tree contract:
                    // the search box filters/expands the tree below, while this pane remains
                    // reserved for actual related-path facets. Do not render current-path or
                    // search-hit rows here, otherwise the Browser sidebar diverges from the DB
                    // folder-tree semantics and looks like a second result list.
                    if (g_browserSystemFolderRelatedPath.empty()) {
                        return;
                    }
                    BrowserSystemFolderCacheEntry& relatedChildren =
                        GetBrowserSystemFolderChildren(g_browserSystemFolderRelatedPath);
                    for (const auto& child : relatedChildren.children) {
                        ImGui::PushID(child.first.c_str());
                        if (ImGui::Selectable(child.second.c_str(), false, ImGuiSelectableFlags_SpanAvailWidth)) {
                            g_browserSystemFolderRelatedPath = child.first;
                            NavigateBrowserToFolder(state, child.first, state.fileBrowser.getScope());
                        }
                        if (HoveredForHelp()) {
                            HarkenSearch::SetTooltip("%s", child.first.c_str());
                        }
                        if (ImGui::BeginPopupContextItem("##BrowserRelatedFolderCtx")) {
                            RenderBrowserSystemFolderContextMenu(state, child.first);
                            ImGui::EndPopup();
                        }
                        ImGui::PopID();
                    }
                });
        },
        [&state, canLocateCurrent, browserSource]() {
            RenderFolderTreeExplorerToolbar(
                browserSource.searchId,
                "",
                g_browserSystemFolderSearchBuffer,
                sizeof(g_browserSystemFolderSearchBuffer),
                browserSource.refreshId,
                g_browserSystemFolderSearchRuntime.Busy(),
                browserSource.locateId,
                canLocateCurrent,
                false,
                false,
                []() {
                    g_browserSystemFolderSearchBuffer[0] = '\0';
                    RunBrowserSystemFolderSearchIfNeeded(true, g_browserSystemFolderSearchFocusRoot);
                },
                []() {
                    g_browserSystemFolderTreeCollapseAll = true;
                    g_browserSystemFolderSearchBuffer[0] = '\0';
                    g_browserSystemFolderSearchFocusRoot.clear();
                    ResetBrowserSystemFolderTreeCache();
                    ClearBrowserSystemFolderSearchState();
                },
                [&state]() {
                    g_browserSystemFolderSearchBuffer[0] = '\0';
                    SetBrowserSystemFolderSearchFocusRoot(state.fileBrowser.getCurrentPath());
                    RunBrowserSystemFolderSearchIfNeeded(true, g_browserSystemFolderSearchFocusRoot);
                    LocateBrowserSystemFolderPath(state.fileBrowser.getCurrentPath());
                },
                [canLocateCurrent](bool hovered) {
                    if (!hovered) {
                        return;
                    }
                    HarkenSearch::SetTooltip("%s", canLocateCurrent ? L(Browser_LocateCurrentFolder) : L(Browser_NoCurrentFolderToLocate));
                });
        },
        [&state, browserSource]() {
            ImGui::Dummy(ImVec2(0.0f, 2.0f));
            float treeH = ImGui::GetContentRegionAvail().y;
            if (treeH < 60.0f) {
                treeH = 60.0f;
            }
            const std::string searchQuery = TrimCopy(g_browserSystemFolderSearchBuffer);
            if (!searchQuery.empty() && g_browserSystemFolderSearchRuntime.Busy()) {
                ImGui::TextDisabled(L(Main_FileCountsFmt),
                                    L(Msg_Loading),
                                    g_browserSystemFolderSearchResults.size(),
                                    BrowserSystemFolderSearchVisitedCount());
            }
            ReadingTextScope _readingTree;
            const ImVec2 previousFramePadding = ImGui::GetStyle().FramePadding;
            const ImVec2 previousItemSpacing = ImGui::GetStyle().ItemSpacing;
            const float previousIndentSpacing = ImGui::GetStyle().IndentSpacing;
            const float compactTreePadY = ImClamp(previousFramePadding.y * 0.45f, 1.0f, 2.0f);
            const float compactTreeSpacingY = ImClamp(previousItemSpacing.y * 0.35f, 1.0f, 3.0f);
            const float compactTreeIndentSpacing = ImClamp(previousIndentSpacing, 12.0f, 16.0f);
            ImGui::PushStyleVar(ImGuiStyleVar_FramePadding, ImVec2(previousFramePadding.x, compactTreePadY));
            ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(previousItemSpacing.x, compactTreeSpacingY));
            ImGui::PushStyleVar(ImGuiStyleVar_IndentSpacing, compactTreeIndentSpacing);
            RenderFolderTreeExplorerList(
                browserSource.treeListChildId,
                treeH,
                g_browserSystemFolderTreeCollapseAll,
                false,
                [&state, searchQuery]() {
                    if (!searchQuery.empty()) {
                        RenderBrowserSystemFolderSearchTree(state);
                    } else {
                        RenderBrowserSystemFolderTree(state);
                    }
                });
            ImGui::PopStyleVar(3);
            g_browserSystemFolderTreeCollapseAll = false;
        });
}

// Path filter click should only clear specific cover-key filter from previous
// cover-click selection, without disabling cover display system.
static void ClearSpecificCoverKeyFilter(AppState& state) {
    if (!state.coverFilterActive) return;
    state.coverFilterActive = false;
    state.coverFilterPath.clear();
    state.coverFilterMatchSig = 0;
    state.coverFilterMatchPaths.clear();
    state.coverWall.pinnedCoverFilterItem = CoverModule::CoverItem{};
}

static void ResetPlaylistCoverWallScope(AppState& state) {
    state.currentCoverFacets.clear();
    state.currentPathFacets.clear();
    state.bumpFacetsGen();

    auto& cw = state.coverWall;
    cw.items.clear();
    cw.pendingFacetItems.clear();
    cw.filteredItems.clear();
    cw.fallbackItems.clear();
    cw.displaySnapshot.clear();
    cw.lastDisplaySnapshotCursor = 0;
    cw.lastFacetGenSnapshot = 0;
    cw.lastPreviewSearchGen = 0;
    cw.lastPreviewFacetGen = 0;
    cw.pendingFacetCursor = 0;
    cw.fallbackResultsGen = 0;
    cw.fallbackFacetsGen = 0;
    cw.filteredLastSelSize = 0;
    cw.filteredLastId0 = 0;
    aura::cover_wall::RequestDisplayRefresh(state);
}

// Reset folder + cover click-filters when a new search query is committed,
// so a fresh query isn't constrained by stale facet clicks. Does NOT clear
// the search buffer itself (that would loop with the search-change handler).
static void ClearPathAndCoverFiltersForNewSearch(AppState& state) {
    bool changed = false;
    if (state.folderFilterActive) {
        state.folderFilterActive = false;
        state.selectedFolderPath.clear();
        changed = true;
    }
    if (state.coverFilterActive) {
        ClearSpecificCoverKeyFilter(state);
        state.coverFilterIndex = 0;
        changed = true;
    }
    if (changed) {
        DIAG_ACTION("Filter", "AutoClearOnSearchChange");
    }
}

static void RequestRemoveFolderFromDatabase(AppState& state, const std::string& folderPath) {
    if (folderPath.empty()) return;
    state.pendingRemoveFolderDbPath = folderPath;
    state.showRemoveFolderDbConfirm = true;
}

static void RefreshFolderTreeAfterDbRemoval(AppState& state) {
    state.database.rebuildFolderIndex();
    FolderInfo refreshedTree = state.database.getFolderHierarchyFromIndex(state.settings.folderTreePathMode);
    if (refreshedTree.subfolders.empty()) {
        refreshedTree = state.database.getFolderHierarchy(state.settings.folderTreePathMode);
    }
    state.setFolderHierarchy(std::move(refreshedTree), state.currentDbPathUtf8);
    state.folderSearchHits.clear();
    state.folderSearchDirectHits.clear();
    state.folderSearchExpandPaths.clear();
    state.lastFolderSearch.clear();
    state.folderTreeScrollTarget.clear();
    state.folderTreeHighlightPath.clear();
    state.folderTreeCollapseAll = true;
}

static void ScheduleDatabasePackageCompactAfterFolderRemoval(const std::string& dbPathUtf8) {
    if (dbPathUtf8.empty()) return;
    std::thread([dbPathUtf8]() {
        auto isRetryableLockError = [](const std::string& error) {
            std::string lower = error;
            std::transform(lower.begin(), lower.end(), lower.begin(),
                           [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
            return lower.find("locked") != std::string::npos ||
                   lower.find("busy") != std::string::npos;
        };

        std::this_thread::sleep_for(std::chrono::milliseconds(500));
        for (int attempt = 0; attempt < 12; ++attempt) {
            Database compactDb;
            if (!compactDb.open(dbPathUtf8)) {
                return;
            }
            std::string error;
            const bool ok = compactDb.compactCachePackage(error);
            compactDb.close();
            if (ok) {
                DIAG_ACTION_FMT("Database",
                                "AutoCompactCachePackage: reason=remove_folder_subtree_async ok=1 attempt=%d",
                                attempt + 1);
                return;
            }
            DIAG_ACTION_FMT("Database",
                            "AutoCompactCachePackage: reason=remove_folder_subtree_async ok=0 attempt=%d error=%s",
                            attempt + 1,
                            error.c_str());
            if (!isRetryableLockError(error) || attempt == 11) {
                return;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
        }
    }).detach();
}

void FinalizeFolderSubtreeDbRemoval(AppState& state,
                                    const std::string& targetPath,
                                    int removed) {
    const std::string canonTarget = HarkenSearch::CanonicalFolderPath(targetPath);
    const std::string loadedPath = state.audioEngine.getLoadedFilePath();
    const bool loadedFileRemoved = IsFileUnderFolderForCacheClear(loadedPath, targetPath);
    const bool currentRecordRemoved =
        state.currentFileId > 0 && state.database.getFileById(state.currentFileId).id <= 0;
    if (state.folderFilterActive &&
        (state.selectedFolderPath == canonTarget ||
         aura::browser::IsSystemFolderAncestorOf(canonTarget, state.selectedFolderPath))) {
        state.folderFilterActive = false;
        state.selectedFolderPath.clear();
        state.currentTab().folderFilterActive = false;
        state.currentTab().selectedFolderPath.clear();
    }

    state.clearSelection();
    ClearAllWaveformUiCaches(state);
    if (loadedFileRemoved || currentRecordRemoved) {
        state.audioEngine.stop();
        state.audioEngine.clearCurrentWaveformVisual();
        state.currentFileId = -1;
    }

    RefreshFolderTreeAfterDbRemoval(state);
    state.currentCoverFacets.clear();
    state.currentPathFacets.clear();
    state.bumpFacetsGen();
    ForceCoverWallReload(state);
    state.needsDatabaseRefresh = false;
    RefreshSearchResults(state, true);
    if (removed > 0) {
        ScheduleDatabasePackageCompactAfterFolderRemoval(state.currentDbPathUtf8);
    }

    state.loadErrorToast = std::string(u8"已从 Harken Search 移除 ")
        + std::to_string(removed)
        + u8" 条入库记录";
    state.loadErrorToastUntil = ImGui::GetTime() + 4.0;
}

static void RenderRemoveFolderDbConfirmPopup(AppState& state) {
    const char* kPopupTitle = L(Misc_ClearFolderCache);
    if (state.showRemoveFolderDbConfirm) {
        ImGui::OpenPopup(kPopupTitle);
        state.showRemoveFolderDbConfirm = false;
    }

    if (!BeginTransientScrollbarPopupModal(kPopupTitle, nullptr, ImGuiWindowFlags_AlwaysAutoResize)) {
        return;
    }
    { ReadingTextScope _readingPopup;  // dialog body is a reading surface

    const std::string targetPath = state.pendingRemoveFolderDbPath;
    ImGui::TextWrapped(L(Main_ClearPathExplainWrap));    ImGui::Spacing();
    ImGui::TextWrapped("%s", targetPath.c_str());
    ImGui::Spacing();

    ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.56f, 0.16f, 0.12f, 1.0f));
    ImGui::PushStyleColor(ImGuiCol_ButtonHovered, ImVec4(0.70f, 0.22f, 0.17f, 1.0f));
    ImGui::PushStyleColor(ImGuiCol_ButtonActive, ImVec4(0.46f, 0.12f, 0.10f, 1.0f));
    if (ImGui::Button(L(Main_RemoveBtnReuse), ImVec2(96, 0))) {
        const int removed = state.database.removeFolderSubtreeFromDb(targetPath);
        FinalizeFolderSubtreeDbRemoval(state, targetPath, removed);
        state.pendingRemoveFolderDbPath.clear();
        ImGui::CloseCurrentPopup();
    }
    ImGui::PopStyleColor(3);

    ImGui::SameLine();
    if (ImGui::Button(L(Main_CancelBtn4), ImVec2(96, 0))) {
        state.pendingRemoveFolderDbPath.clear();
        ImGui::CloseCurrentPopup();
    }

    }
    ImGui::EndPopup();
}

// Flat folder-search results avoid recursive matching during every frame.
static void SelectPlaylistFolderFilter(AppState& state, const std::string& folderPath);

enum class FolderTreeSelectionMode {
    DatabaseFilter,
    PlaylistFilter,
};

static void RenderFolderTreeNode(AppState& state,
                                 const FolderInfo& folder,
                                 const std::string& search,
                                 FolderTreeSelectionMode mode,
                                 bool revealSubtree = false) {
    // Use the precomputed folderSearchHits set for constant-time membership.
    // 杜绝调用 FolderOrChildMatchesSearch 这种每帧递归的"性能黑洞"
    if (!search.empty() && !revealSubtree) {
        if (state.folderSearchHits.find(folder.path) == state.folderSearchHits.end()) {
            return;
        }
    }

    bool hasChildren = !folder.subfolders.empty();
    // T2.6: folder.path 来自 tree (raw); selectedFolderPath 已 canonical → 比较右侧也 canonical
    bool isSelected = (state.folderFilterActive && state.selectedFolderPath == HarkenSearch::CanonicalFolderPath(folder.path));
    const bool isSearchTerminalHit =
        !search.empty() &&
        state.folderSearchDirectHits.find(folder.path) != state.folderSearchDirectHits.end();
    // 防抖期间"待确认"的文件夹，用于按下态视觉反馈，避免高亮与列表内容脱节
    bool isPending = (mode == FolderTreeSelectionMode::DatabaseFilter &&
                      !state.uiState.pendingFolderPath.empty() &&
                      folder.path == state.uiState.pendingFolderPath);

    // 只有在搜索词不为空时，才进行当前节点的高亮匹配判断
    // 多词搜索：任一 token 命中即高亮（token 分布在祖先→后代路径上）
    bool matchesSearch = isSearchTerminalHit;
    if (!search.empty()) {
        if (state.folderSearchTokens.size() > 1) {
            matchesSearch = isSearchTerminalHit;
        } else {
            matchesSearch = isSearchTerminalHit;
        }
    }

    // 2. 优化展开逻辑
    // 搜索激活时自动展开命中链路（folderSearchHits 包含直接命中节点及其所有祖先）
    bool shouldAutoOpen = (!state.folderTreeScrollTarget.empty() &&
                           (aura::browser::IsSystemFolderAncestorOf(
                                folder.path, state.folderTreeScrollTarget) ||
                            folder.path == state.folderTreeScrollTarget))
                       || (!revealSubtree &&
                           state.folderTreeExpandSearchHitsOnce &&
                           (state.folderSearchExpandPaths.count(folder.path) > 0 ||
                            state.folderSearchDirectHits.count(folder.path) > 0));

    ImGuiTreeNodeFlags flags = ImGuiTreeNodeFlags_OpenOnArrow |
                             ImGuiTreeNodeFlags_SpanAvailWidth |
                             ImGuiTreeNodeFlags_NoTreePushOnOpen;
    if (!hasChildren) flags |= ImGuiTreeNodeFlags_Leaf;
    if (state.folderTreeCollapseAll && !shouldAutoOpen) ImGui::SetNextItemOpen(false);
    else if (shouldAutoOpen) ImGui::SetNextItemOpen(true);

    // 3. 复用静态缓冲，杜绝字符串分配
    // T2.5: 渲染用 displayName (raw case) 而非 name (canonical 小写); fallback 到 name 防空
    const char* displayLabel = !folder.displayName.empty() ? folder.displayName.c_str() : folder.name.c_str();
    static char labelBuf[512];
    if (Platform::FileSystem::IsNetworkPath(folder.path)) {
        snprintf(labelBuf, sizeof(labelBuf), "%s [%s]###%s",
                 displayLabel, L(Lib_ReadonlyNetwork), folder.path.c_str());
    } else {
        snprintf(labelBuf, sizeof(labelBuf), "%s###%s", displayLabel, folder.path.c_str());
    }

    const auto& tcs = ThemeColors::current();
    const auto mixColor = [](const ImVec4& a, const ImVec4& b, float t) {
        return ImVec4(
            a.x + (b.x - a.x) * t,
            a.y + (b.y - a.y) * t,
            a.z + (b.z - a.z) * t,
            a.w + (b.w - a.w) * t);
    };
    const auto withAlpha = [](const ImVec4& c, float alpha) {
        return ImVec4(c.x, c.y, c.z, alpha);
    };
    ImVec4 treeTextColor = tcs.filterBrowserTreeText;
    if (matchesSearch) {
        treeTextColor = tcs.filterBrowserSearchHitText;
    }
    ImDrawList* treeDrawList = ImGui::GetWindowDrawList();
    ImDrawListSplitter treeBgSplitter;
    treeBgSplitter.Split(treeDrawList, 2);
    treeBgSplitter.SetCurrentChannel(treeDrawList, 1);

    ImGui::PushStyleColor(ImGuiCol_Text, treeTextColor);

    // 禁用默认高亮，减少 Overdraw
    ImGui::PushStyleColor(ImGuiCol_HeaderHovered, ImVec4(0, 0, 0, 0));
    ImGui::PushStyleColor(ImGuiCol_HeaderActive, ImVec4(0, 0, 0, 0));
    ImGui::PushStyleColor(ImGuiCol_Header, ImVec4(0, 0, 0, 0));

    bool nodeOpen = ImGui::TreeNodeEx(labelBuf, flags);

    ImGui::PopStyleColor(4);

    // 定位后高亮：◎ 定位到的文件夹在有效期内用醒目色绘制
    int64_t nowMs = (int64_t)(ImGui::GetTime() * 1000.0);
    bool isLocateHighlight = ShouldHighlightFolderNodeForLocate(folder.path, state.folderTreeHighlightPath, state.folderTreeHighlightUntilMs, nowMs);

    // 手动绘制搜索命中 / 选中 / 待确认(pending) / 定位高亮 / 悬停背景
    if (matchesSearch || isSelected || isPending || isLocateHighlight || ImGui::IsItemHovered()) {
        float arrowWidth = ImGui::GetTreeNodeToLabelSpacing();
        ImVec2 rMin = ImGui::GetItemRectMin();
        ImVec2 rMax = ImGui::GetItemRectMax();
        rMin.x += arrowWidth;
        const bool isLightTreeTheme = (tcs.filterBrowserBG.x + tcs.filterBrowserBG.y + tcs.filterBrowserBG.z) > 2.15f;
        const ImVec4 searchCol = withAlpha(
            mixColor(tcs.filterBrowserSearchHitText, tcs.filterBrowserBG, isLightTreeTheme ? 0.64f : 0.78f),
            isLightTreeTheme ? 0.34f : 0.26f);
        const ImVec4 locateCol = withAlpha(mixColor(tcs.filterBrowserTreeSelection, tcs.filterBrowserLocateTint, 0.38f), 0.54f);
        const ImVec4 selectedCol = withAlpha(mixColor(tcs.filterBrowserTreeSelection, tcs.filterBrowserBG, 0.60f), 0.28f);
        const ImVec4 pendingCol = withAlpha(mixColor(tcs.filterBrowserTreeSelection, tcs.filterBrowserBG, 0.52f), 0.22f);
        const ImVec4 hoverCol = withAlpha(mixColor(tcs.filterBrowserTreeSelection, tcs.filterBrowserBG, 0.78f), 0.14f);
        treeBgSplitter.SetCurrentChannel(treeDrawList, 0);
        if (matchesSearch) {
            treeDrawList->AddRectFilled(rMin, rMax, ImGui::GetColorU32(searchCol), 3.0f);
        }
        if (isLocateHighlight || isSelected || isPending || ImGui::IsItemHovered()) {
            ImU32 col = isLocateHighlight ? ImGui::GetColorU32(locateCol)
                       : isSelected ? ImGui::GetColorU32(selectedCol)
                       : isPending  ? ImGui::GetColorU32(pendingCol)
                       : ImGui::GetColorU32(hoverCol);
            treeDrawList->AddRectFilled(rMin, rMax, col, 3.0f);
        }
        treeBgSplitter.SetCurrentChannel(treeDrawList, 1);
    }

    treeBgSplitter.Merge(treeDrawList);

    // 自动滚动：只要绘制到目标节点就滚动到视口中间（不要求已选中，否则定位后不会滚动）
    if (!state.folderTreeScrollTarget.empty() && folder.path == state.folderTreeScrollTarget) {
        ImGui::SetScrollHereY(0.5f);  // 0.5 = 目标行出现在视口垂直中间
        ImGui::SetScrollX(0.0f);      // 水平滚动到最左，确保深层子文件夹名称可见
        state.folderTreeScrollTarget.clear();
        state.folderTreeHighlightPath = folder.path;
        state.folderTreeHighlightUntilMs = nowMs + 500;  // 高亮持续约 0.5 秒
    }

    // 4. 交互优化：防抖与 I/O 优先级抢占
    if (ImGui::IsItemClicked()) {
        float arrowWidth = ImGui::GetTreeNodeToLabelSpacing();
        if (ImGui::GetIO().MousePos.x > ImGui::GetItemRectMin().x + arrowWidth) {
            if (mode == FolderTreeSelectionMode::PlaylistFilter) {
                SelectPlaylistFolderFilter(state, folder.path);
            } else {
                // Database scope keeps the deferred folder-switch handshake.
                state.uiState.pendingFolderPath = folder.path;
                state.uiState.pendingFolderTime = ImGui::GetTime();
                state.preferDeferredCountForNextRefresh = true;

                // Keep cover-wall facets alive until the refreshed result set swaps in.
                aura::cover_wall::RequestDisplayRefresh(state);

                // Preempt background waveform work before the database refresh.
                state.clearPendingWaveforms();

                // Preserve navigation history before applying the folder filter.
                state.pushViewState();
            }
        }
    }

    if (ImGui::IsItemHovered() && !folder.path.empty()) {
        HarkenSearch::SetTooltip("%s", folder.path.c_str());
    }

    // Folder-tree rows do not accept AUDIO_FILES drag payloads.
    // 禁止从播放列表或主波形区域拖动音效到侧边栏文件夹进行归类
    // 唯一合法的归类方式：仅保留右键菜单操作
    // 这样设计可以防止用户在快速操作（如拖入 DAW）时误触文件夹归类
    // 注意：此处不添加 BeginDragDropTarget，确保文件夹树不具备"磁性"

    if (ImGui::BeginDragDropSource(ImGuiDragDropFlags_SourceAllowNullID)) {
        MaybePausePlaybackOnInScopeDragStart();
        ImGui::SetDragDropPayload("FOLDER_PATH", folder.path.c_str(), (int)(folder.path.size() + 1));
        // T2.5: drag preview text uses display name (raw case)
        ImGui::Text(L(Misc_CategorizeFolder),
                    !folder.displayName.empty() ? folder.displayName.c_str() : folder.name.c_str());
        ImGui::EndDragDropSource();
    }

    // 右键菜单：路径查新 / 添加快捷方式
    if (ImGui::BeginPopupContextItem(folder.path.c_str())) {
        if (ImGui::MenuItem(L(Scan_QuickScan))) {
            PrepareQuickScanDialogForPath(state, folder.path);
        }
        if (ImGui::MenuItem(L(Misc_ClearFolderCache))) {
            g_pendingClearCachePath = folder.path;
            g_pendingClearCacheConfirm = true;
        }
        if (ImGui::MenuItem(L(Misc_AddToQuickNav))) {
            // T2.5: shortcut name uses display name so user sees raw case
            const std::string& shortcutName =
                !folder.displayName.empty() ? folder.displayName : folder.name;
            if (AddFolderShortcutIfMissing(state, shortcutName, folder.path)) {
                MarkSettingsDirty(state);
            }
        }
        ImGui::EndPopup();
    }

    if (nodeOpen && hasChildren) {
        ImGui::Indent();
        // Search-mode subtree visibility:
        //  - Ancestor-chain nodes keep search filtering on their descendants
        //    (only nodes in folderSearchHits render).
        //  - Direct-hit nodes reveal their FULL subtree once expanded — the user
        //    explicitly drilled in, so we honor "show me what's under this match".
        //    Children stay collapsed by default (shouldAutoOpen disables itself
        //    in reveal mode), so the user keeps control of further expansion.
        const bool revealChildren = revealSubtree || isSearchTerminalHit;
        for (const auto& sub : folder.subfolders) {
            RenderFolderTreeNode(state, sub, search, mode, revealChildren);
        }
        ImGui::Unindent();
    }
}

// Helper: apply all active filters and refresh results
// Filter results by file type visibility settings
void FilterResultsByFileType(AppState& state) {
    if (state.showWAV && state.showMP3 && state.showFLAC && state.showOGG &&
        state.showAIFF && state.showM4A && state.showWMA && state.showOther) {
        return;  // All types visible, no filtering needed
    }

    std::vector<AudioRecord> filtered;
    filtered.reserve(state.searchResults.size());

    for (const auto& record : state.searchResults) {
        if (state.shouldShowFile(record.extension)) {
            filtered.push_back(record);
        }
    }

    state.searchResults = std::move(filtered);
    state.bumpSearchResultsGen();
}

// Random Sampling - Show random subset of files without repeating

// Forward declaration
// 异步随机池构建：避免主线程 searchFiles(100000) 卡顿（规范 §11）
static std::future<std::vector<AudioRecord>> g_randomPoolFuture;
static std::atomic<bool> g_randomPoolPending{false};

void PumpInitRandomSamplingPoolIfPending(AppState& state) {
    if (!g_randomPoolPending.load(std::memory_order_acquire)) return;
    if (!g_randomPoolFuture.valid()) return;
    if (g_randomPoolFuture.wait_for(std::chrono::seconds(0)) != std::future_status::ready) return;

    std::vector<AudioRecord> allMatching;
    try {
        allMatching = g_randomPoolFuture.get();
    } catch (...) {
        g_randomPoolPending.store(false, std::memory_order_release);
        return;
    }
    g_randomPoolPending.store(false, std::memory_order_release);

    state.resetRandomSampling();
    for (const auto& record : allMatching) {
        if (state.shouldShowFile(record.extension)) {
            if (state.playedFileIds.find(record.id) == state.playedFileIds.end())
                state.randomAvailableIds.push_back(record.id);
        }
    }
    state.randomAllPlayed = state.randomAvailableIds.empty();
    if (state.randomAllPlayed) {
        for (const auto& record : allMatching) {
            if (state.shouldShowFile(record.extension))
                state.randomAvailableIds.push_back(record.id);
        }
    }
    state.randomTotalPool = (int64_t)state.randomAvailableIds.size();
    std::random_device rd;
    std::mt19937 gen(rd());
    std::shuffle(state.randomAvailableIds.begin(), state.randomAvailableIds.end(), gen);
}

static void StartInitRandomSamplingPoolAsync(AppState& state) {
    if (g_randomPoolPending.load(std::memory_order_acquire)) return;
    SearchFilter filter = BuildCurrentDbFilter(state);
    Database* db = &state.database;
    g_randomPoolPending.store(true, std::memory_order_release);
    g_randomPoolFuture = std::async(std::launch::async, [db, filter]() {
        return db->searchFiles(filter, 100000, 0);
    });
}

// Initialize random sampling pool from current filter (async: 不阻塞主线程)
static void InitRandomSamplingPool(AppState& state) {
    StartInitRandomSamplingPoolAsync(state);
}

// Play a random file from current results (fast! no database query)
// Prioritize files with cached waveforms for smoother experience
void PlayRandomFile(AppState& state) {
    // Use current search results directly - FAST!
    if (state.searchResults.empty()) {
        return;  // No files to choose from
    }

    const size_t totalResults = state.searchResults.size();
    const size_t maxRange = std::min((size_t)200, totalResults);

    // 随机抽样找未播放的（O(1) 每次，不全量扫描，百万级零卡顿）
    std::random_device rd;
    std::mt19937 gen(rd());
    constexpr int kMaxAttempts = 40;
    size_t chosenIdx = 0;
    bool found = false;

    // 第一轮：前 200 条随机抽样找未播放的
    {
        std::uniform_int_distribution<size_t> dist(0, maxRange - 1);
        for (int a = 0; a < kMaxAttempts && !found; a++) {
            size_t idx = dist(gen);
            if (state.playedFileIds.find(state.searchResults[idx].id) == state.playedFileIds.end()) {
                chosenIdx = idx;
                found = true;
            }
        }
    }

    // 第二轮：前 200 大概都播过了，从全范围随机抽
    if (!found && totalResults > maxRange) {
        std::uniform_int_distribution<size_t> dist(0, totalResults - 1);
        for (int a = 0; a < kMaxAttempts && !found; a++) {
            size_t idx = dist(gen);
            if (state.playedFileIds.find(state.searchResults[idx].id) == state.playedFileIds.end()) {
                chosenIdx = idx;
                found = true;
            }
        }
    }

    // 全部播过 — 清空记录，新一轮
    if (!found) {
        state.randomAllPlayed = true;
        state.playedFileIds.clear();
        chosenIdx = std::uniform_int_distribution<size_t>(0, maxRange - 1)(gen);
    }

    const AudioRecord& chosen = state.searchResults[chosenIdx];

    // Load and play!（异步加载，pump 中绑定并 play）
    state.audioEngine.loadFileAsync(chosen.filePath, true);
    ScheduleDeferredWaveformDetail(state, chosen.filePath, AppState::WAVEFORM_DEFAULT_DETAIL_PEAKS);
    ResetWaveformZoom(state);
    MarkFilePlayed(state, chosen.filePath, chosen.id);
    state.selectedIndicesSet.clear();
    state.selectedIndicesSet.insert((int)chosenIdx);
    state.beginAudioTargetFromSearchResult((int)chosenIdx);
    state.lastClickedIndex = (int)chosenIdx;
    state.scrollToSelected = true;
    state.syncToTab();
}

// Shuffle: randomly sample PAGE_SIZE items from the FULL database (respecting current filters),
// not just shuffle the currently-loaded page.
static void ShuffleCurrentResultsAndPlayFirst(AppState& state) {
    // Random ordering must stay on the search worker, not the UI thread.
    // 我们仅发起一个异步请求，UI 线程立即返回，保持 120FPS 丝滑。
    SearchFilter filter = BuildCurrentDbFilter(state);

    // 设置 UI 加载状态，给用户视觉反馈
    state.loadingMore = true;
    state.filterQueryState = FilterQueryState::Running;

    // 提交异步随机任务：isRandomShuffle = true
    SubmitAsyncSearch(state, filter, AsyncSearchKind::Refresh, AppState::PAGE_SIZE, 0, true, false, true);

    // 剩下的"播放第一首"逻辑将由 PumpAsyncSearchResults 在后台数据返回后自动触发
    state.syncToTab();
    DIAG_ACTION("Search", "Async Random Shuffle Triggered");
}

// Load next random batch - one page (50 items) [kept for scrolling]
static void LoadRandomSampleBatch(AppState& state) {
    state.searchResults.clear();
    state.bumpSearchResultsGen();
    state.clearPendingWaveforms();

    if (state.randomAvailableIds.empty()) {
        // All files have been shown
        state.hasMoreResults = false;
        state.randomAllPlayed = true;
        return;
    }

    // Use fixed page size of 50
    int batchSize = std::min(state.RANDOM_PAGE_SIZE, (int)state.randomAvailableIds.size());
    std::vector<int64_t> batchIds;
    batchIds.reserve(batchSize);

    // Take from the end (pre-shuffled)
    for (int i = 0; i < batchSize && !state.randomAvailableIds.empty(); ++i) {
        int64_t id = state.randomAvailableIds.back();
        state.randomAvailableIds.pop_back();
        state.randomShownIds.insert(id);
        batchIds.push_back(id);
    }

    // Fetch full records for these IDs
    state.searchResults = state.database.getFilesByIds(batchIds);
    state.bumpSearchResultsGen();

    state.totalFileCount = (int64_t)state.searchResults.size();
    state.loadedCount = (int)state.searchResults.size();
    state.hasMoreResults = !state.randomAvailableIds.empty();

    // Check if we've exhausted unplayed files
    if (state.randomAvailableIds.empty()) {
        state.randomAllPlayed = true;
    }
}

// Get random sampling status text
static std::string GetRandomSamplingStatus(const AppState& state) {
    int shown = (int)state.randomShownIds.size();
    int remaining = (int)state.randomAvailableIds.size();
    int total = (int)state.randomTotalPool;

    char buf[128];
    snprintf(buf, sizeof(buf), L(Nav_ItemsShown), shown, total, remaining);
    return std::string(buf);
}

