    ImDrawList* fg = ImGui::GetForegroundDrawList();
    const ImVec2 mouse = ImGui::GetMousePos();
    const char* label = g_playlistQuickDrag.label.empty() ? "Add to playlist" : g_playlistQuickDrag.label.c_str();
