void DrawPlaylistDropTargetHighlight(ImDrawList* dl,
                                            const ImVec2& p0,
                                            const ImVec2& p1,
                                            const ImVec4& accent,
                                            float rounding,
                                            bool expandCue) {
    if (!dl) return;

    const float pulse = 0.5f + 0.5f * std::sin((float)ImGui::GetTime() * 8.5f);
    auto accentWithAlpha = [&](float alpha) -> ImU32 {
        ImVec4 c = accent;
        c.w = std::clamp(alpha, 0.0f, 1.0f);
        return ImGui::GetColorU32(c);
    };

    dl->AddRectFilled(ImVec2(p0.x - 1.0f, p0.y - 1.0f),
                      ImVec2(p1.x + 1.0f, p1.y + 1.0f),
                      accentWithAlpha(0.07f + pulse * 0.04f),
                      rounding + 1.0f);
    dl->AddRect(ImVec2(p0.x - 1.0f, p0.y - 1.0f),
                ImVec2(p1.x + 1.0f, p1.y + 1.0f),
                accentWithAlpha(0.34f + pulse * 0.16f),
                rounding + 1.0f,
                0,
                2.0f);
    dl->AddRect(ImVec2(p0.x + 2.0f, p0.y + 2.0f),
                ImVec2(p1.x - 2.0f, p1.y - 2.0f),
                accentWithAlpha(0.18f + pulse * 0.10f),
                std::max(0.0f, rounding - 1.0f),
                0,
                1.4f);

    if (!expandCue) return;

    dl->AddRectFilled(ImVec2(p0.x + 3.0f, p0.y + 3.0f),
                      ImVec2(p0.x + 7.0f, p1.y - 3.0f),
                      accentWithAlpha(0.22f + pulse * 0.10f),
                      2.0f);

    const float midX = p1.x - 14.0f;
    const float midY = (p0.y + p1.y) * 0.5f;
    dl->AddLine(ImVec2(midX - 4.0f, midY - 5.0f),
                ImVec2(midX, midY - 1.0f),
                accentWithAlpha(0.60f + pulse * 0.18f),
                1.9f);
    dl->AddLine(ImVec2(midX, midY - 1.0f),
                ImVec2(midX + 4.0f, midY - 5.0f),
                accentWithAlpha(0.60f + pulse * 0.18f),
                1.9f);
    dl->AddLine(ImVec2(midX - 4.0f, midY + 1.0f),
                ImVec2(midX, midY + 5.0f),
                accentWithAlpha(0.60f + pulse * 0.18f),
                1.9f);
    dl->AddLine(ImVec2(midX, midY + 5.0f),
                ImVec2(midX + 4.0f, midY + 1.0f),
                accentWithAlpha(0.60f + pulse * 0.18f),
                1.9f);
}

