            colors[ImGuiCol_CheckMark] = ImVec4(0.34f, 0.61f, 0.84f, 1.0f);
            // 默认深蓝：波形与主题冷色调统一
            g_waveformColor = IM_COL32(175, 215, 255, 255);    // #AFD7FF
            g_waveformBgColor = IM_COL32(11, 15, 21, 255);     // 近黑 #0B0F15
