            g_miniWaveColor = g_waveformColor;
            g_miniWaveBgColor = IM_COL32(0, 0, 0, 0);
            break;

        case AppTheme::Ocean:
            // Ocean Theme — 深海钢蓝版，去荧光，保留水感
            // 背景：深渊蓝 | 面板：暗海蓝 | 强调色：钢蓝 #3A82BD | 边框：雾蓝

            // 1. 背景层
            colors[ImGuiCol_WindowBg]  = ImVec4(0.028f, 0.044f, 0.071f, 1.000f);    // #071122
            colors[ImGuiCol_ChildBg]   = ImVec4(0.057f, 0.094f, 0.149f, 1.000f);    // lifted for distinct file-list area
            colors[ImGuiCol_PopupBg]   = ImVec4(0.063f, 0.102f, 0.157f, 0.970f);    // #101A28

            // 2. 边框：雾蓝
            colors[ImGuiCol_Border]       = ImVec4(0.141f, 0.231f, 0.361f, 0.500f); // fog-blue
