            colors[ImGuiCol_FrameBgActive]  = ImVec4(0.180f, 0.380f, 0.580f, 0.700f); // was 0.28 — nearly invisible

            colors[ImGuiCol_TitleBg]       = ImVec4(0.028f, 0.044f, 0.071f, 1.000f);
            colors[ImGuiCol_TitleBgActive] = ImVec4(0.047f, 0.078f, 0.122f, 1.000f);
            colors[ImGuiCol_MenuBarBg]     = ImVec4(0.047f, 0.078f, 0.122f, 1.000f);

            // 4. 强调色：钢蓝 #3A82BD（非荧光青）
            colors[ImGuiCol_Header]        = ImVec4(0.180f, 0.380f, 0.580f, 0.340f);
            colors[ImGuiCol_HeaderHovered] = ImVec4(0.230f, 0.460f, 0.670f, 0.500f);
            colors[ImGuiCol_HeaderActive]  = ImVec4(0.230f, 0.510f, 0.740f, 0.800f);

            colors[ImGuiCol_Button]        = ImVec4(0.110f, 0.180f, 0.275f, 1.000f);
            colors[ImGuiCol_ButtonHovered] = ImVec4(0.180f, 0.360f, 0.550f, 0.700f);
            colors[ImGuiCol_ButtonActive]  = ImVec4(0.230f, 0.510f, 0.740f, 1.000f);

            colors[ImGuiCol_Tab]        = ImVec4(0.047f, 0.078f, 0.122f, 1.000f);
