            colors[ImGuiCol_TabActive]  = ImVec4(0.190f, 0.400f, 0.600f, 0.750f);

            colors[ImGuiCol_SliderGrab]       = ImVec4(0.230f, 0.510f, 0.740f, 1.000f);
