// 独立组件：立体声/单声道图标按钮 (无文字，纯图标)
// is_stereo=true 画双声道符号，false 画单声道符号
static bool StereoIconButton(const char* id_str, bool* is_stereo, const ImVec2& size_arg = ImVec2(38, 32)) {
    ImGuiWindow* window = ImGui::GetCurrentWindow();
    if (window->SkipItems) return false;

    ImGuiID id = window->GetID(id_str);
    ImVec2 pos = window->DC.CursorPos;
    ImRect bb(pos, ImVec2(pos.x + size_arg.x, pos.y + size_arg.y));

    ImGui::ItemSize(size_arg);
    if (!ImGui::ItemAdd(bb, id)) return false;

    bool hovered, held;
    bool pressed = ImGui::ButtonBehavior(bb, id, &hovered, &held);
    if (pressed) *is_stereo = !(*is_stereo);

    ImVec4* colors = ImGui::GetStyle().Colors;
    const bool isLightTheme = (colors[ImGuiCol_WindowBg].x + colors[ImGuiCol_WindowBg].y + colors[ImGuiCol_WindowBg].z) > 2.2f;
    ImDrawList* dl = window->DrawList;
    float rounding = 6.0f;

    // 背景 (与其他控件统一的质感)
    ImU32 bg_col = isLightTheme
        ? (*is_stereo ? ImGui::GetColorU32(ImVec4(0.957f, 0.900f, 0.920f, 1.0f))
                      : hovered ? ImGui::GetColorU32(ImVec4(0.972f, 0.941f, 0.949f, 1.0f))
                                : ImGui::GetColorU32(ImVec4(0.986f, 0.973f, 0.976f, 1.0f)))
        : (*is_stereo ? ImGui::GetColorU32(ImVec4(0.18f, 0.18f, 0.20f, 1.0f))
                      : hovered ? ImGui::GetColorU32(ImVec4(0.15f, 0.15f, 0.17f, 1.0f))
                                : ImGui::GetColorU32(ImVec4(0.11f, 0.11f, 0.13f, 1.0f)));

    // 背景 + 边框 (精致)
    dl->AddRectFilled(bb.Min, bb.Max, bg_col, rounding);
    dl->AddLine(ImVec2(bb.Min.x + rounding, bb.Min.y + 1.0f), ImVec2(bb.Max.x - rounding, bb.Min.y + 1.0f),
        ImGui::GetColorU32(ImVec4(1.0f, 1.0f, 1.0f, isLightTheme ? 0.08f : 0.04f)), 1.0f);
    dl->AddRect(bb.Min, bb.Max,
        isLightTheme ? ImGui::GetColorU32(ImVec4(0.82f, 0.73f, 0.76f, hovered ? 0.42f : 0.28f))
                     : ImGui::GetColorU32(ImVec4(1.0f, 1.0f, 1.0f, hovered ? 0.08f : 0.04f)), rounding);

    // 图标颜色
    ImU32 iconCol = isLightTheme
        ? (*is_stereo ? ImGui::GetColorU32(ImVec4(0.30f, 0.22f, 0.25f, 1.0f))
                      : hovered ? ImGui::GetColorU32(ImVec4(0.38f, 0.28f, 0.32f, 1.0f))
                                : ImGui::GetColorU32(ImVec4(0.48f, 0.40f, 0.43f, 1.0f)))
        : (*is_stereo ? ImGui::GetColorU32(ImVec4(0.92f, 0.92f, 0.95f, 1.0f))
                      : hovered ? ImGui::GetColorU32(ImVec4(0.78f, 0.78f, 0.82f, 1.0f))
                                : ImGui::GetColorU32(ImVec4(0.55f, 0.55f, 0.60f, 1.0f)));

    float cx = bb.Min.x + size_arg.x * 0.5f;
    float cy = bb.Min.y + size_arg.y * 0.5f;
    float lw = 1.4f;  // 细线条

    if (*is_stereo) {
        // 立体声：两个细弧 (像耳机)
        float r = 5.0f, gap = 3.0f;
        dl->PathClear();
        dl->PathArcTo(ImVec2(cx - gap, cy), r, IM_PI * 0.6f, IM_PI * 1.4f, 12);
        dl->PathStroke(iconCol, 0, lw);
        dl->PathClear();
        dl->PathArcTo(ImVec2(cx + gap, cy), r, -IM_PI * 0.4f, IM_PI * 0.4f, 12);
        dl->PathStroke(iconCol, 0, lw);
    } else {
        // 单声道：单个小圆
        float r = 5.5f;
        dl->PathClear();
        dl->PathArcTo(ImVec2(cx, cy), r, 0.0f, IM_PI * 2.0f, 20);
        dl->PathStroke(iconCol, 0, lw);
        dl->AddLine(ImVec2(cx, cy - 3.0f), ImVec2(cx, cy + 3.0f), iconCol, lw);
    }

    return pressed;
}

