// Sidebar compact glyph button: Refresh / reload.
static bool SidebarRefreshGlyphButton(const char* id_str, const ImVec2& size_arg, bool is_busy) {
    ImGuiWindow* window = ImGui::GetCurrentWindow();
    if (window->SkipItems) return false;

    ImGuiID id = window->GetID(id_str);
    ImVec2 pos = window->DC.CursorPos;
    ImRect bb(pos, ImVec2(pos.x + size_arg.x, pos.y + size_arg.y));

    ImGui::ItemSize(size_arg);
    if (!ImGui::ItemAdd(bb, id)) return false;

    bool hovered, held;
    bool pressed = ImGui::ButtonBehavior(bb, id, &hovered, &held);

    ImGuiStorage* storage = ImGui::GetStateStorage();
    float animTimer = storage->GetFloat(id + 1, 1.0f);
    float rotation = storage->GetFloat(id + 2, 0.0f);
    if (pressed) animTimer = 0.0f;

    const float kSpinDuration = 0.58f;
    const bool animating = animTimer < kSpinDuration;
    if (animating) {
        animTimer += ImGui::GetIO().DeltaTime;
        float t = ImSaturate(animTimer / kSpinDuration);
        float ease = 1.0f - powf(1.0f - t, 3.0f);
        rotation = ease * (IM_PI * 2.0f);
        if (t >= 0.999f) {
            animTimer = 1.0f;
            rotation = 0.0f;
        }
    } else {
        animTimer = 1.0f;
        rotation = 0.0f;
    }
    storage->SetFloat(id + 1, animTimer);
    storage->SetFloat(id + 2, rotation);

    auto mix = [](const ImVec4& a, const ImVec4& b, float t) -> ImVec4 {
        return ImVec4(
            a.x + (b.x - a.x) * t,
            a.y + (b.y - a.y) * t,
            a.z + (b.z - a.z) * t,
            a.w + (b.w - a.w) * t);
    };
    auto withAlpha = [](ImVec4 c, float a) -> ImVec4 { c.w = a; return c; };

    const auto& tcs = ThemeColors::current();
    const bool isLightFilterTheme = (tcs.filterBrowserBG.x + tcs.filterBrowserBG.y + tcs.filterBrowserBG.z) > 2.15f;
    const ImVec4 cue = mix(tcs.searchButtonBG, tcs.filterBrowserSelection, 0.50f);
    const ImVec4 baseBg = isLightFilterTheme
        ? mix(tcs.filterBrowserButtonBG, tcs.filterBrowserBG, 0.10f)
        : mix(tcs.filterBrowserButtonBG, tcs.filterBrowserBG, 0.32f);
    const ImVec4 hoverBg = mix(baseBg, cue, isLightFilterTheme ? 0.18f : 0.24f);
    const ImVec4 busyBg = mix(baseBg, cue, isLightFilterTheme ? 0.12f : 0.18f);
    const ImVec4 border = mix(tcs.filterBrowserOutline, cue, isLightFilterTheme ? 0.24f : 0.18f);
    const ImVec4 glyph = isLightFilterTheme
        ? mix(tcs.filterBrowserText, tcs.mainWindowBG, 0.10f)
        : mix(tcs.filterBrowserText, cue, 0.26f);

    ImDrawList* dl = window->DrawList;
    const float rounding = 6.0f;
    const float busyPulse = is_busy ? (0.5f + 0.5f * sinf((float)ImGui::GetTime() * 5.4f)) : 0.0f;
    const float spinPulse = animating ? (0.65f + 0.35f * sinf((float)ImGui::GetTime() * 10.0f)) : 0.0f;
    const float halo = hovered ? 0.08f : 0.0f;
    const float busyHalo = is_busy ? (isLightFilterTheme ? 0.08f : 0.10f) + busyPulse * 0.05f : 0.0f;
    const float animHalo = animating ? 0.10f + spinPulse * 0.04f : 0.0f;
    const float totalHalo = ImMax(halo, ImMax(busyHalo, animHalo));
    if (totalHalo > 0.0f) {
        ImVec2 c(bb.GetCenter());
        dl->AddCircleFilled(c, size_arg.x * (0.34f + (animating ? 0.08f : 0.0f)), ImGui::GetColorU32(withAlpha(cue, totalHalo)), 24);
    }
    const ImVec4 fillBg = hovered ? hoverBg : (is_busy ? busyBg : baseBg);
    dl->AddRectFilled(bb.Min, bb.Max, ImGui::GetColorU32(withAlpha(fillBg, isLightFilterTheme ? 0.985f : 0.96f)), rounding);
    dl->AddRect(bb.Min, bb.Max, ImGui::GetColorU32(withAlpha(border, hovered ? 0.38f : (is_busy ? 0.32f : 0.24f))), rounding, 0, 1.0f);

    ImVec2 center = bb.GetCenter();
    float radius = size_arg.x * 0.21f;
    float aMin = rotation - IM_PI * 0.55f;
    float aMax = aMin + (300.0f * IM_PI / 180.0f);
    ImU32 glyphCol = ImGui::GetColorU32(withAlpha(glyph, hovered ? 0.98f : (isLightFilterTheme ? 0.94f : 0.88f)));

    dl->PathClear();
    dl->PathArcTo(center, radius, aMin, aMax, 24);
    dl->PathStroke(glyphCol, 0, 1.7f);

    ImVec2 arrowTip(center.x + cosf(aMax) * radius, center.y + sinf(aMax) * radius);
    float tangent = aMax + IM_PI * 0.5f;
    float arrowSize = 4.0f;
    ImVec2 p1(arrowTip.x + cosf(tangent + IM_PI * 0.75f) * arrowSize, arrowTip.y + sinf(tangent + IM_PI * 0.75f) * arrowSize);
    ImVec2 p2(arrowTip.x + cosf(tangent - IM_PI * 0.75f) * arrowSize, arrowTip.y + sinf(tangent - IM_PI * 0.75f) * arrowSize);
    dl->AddLine(arrowTip, p1, glyphCol, 1.7f);
    dl->AddLine(arrowTip, p2, glyphCol, 1.7f);

    if (is_busy) {
        ImVec2 dotCenter(bb.Max.x - 5.5f, bb.Min.y + 5.5f);
        dl->AddCircleFilled(dotCenter, 2.0f, ImGui::GetColorU32(withAlpha(cue, 0.92f)), 12);
        dl->AddCircleFilled(dotCenter, 4.0f, ImGui::GetColorU32(withAlpha(cue, 0.18f + busyPulse * 0.10f)), 16);
    }

    return pressed;
}

// Sidebar compact glyph button: Clear all / Find All.
static bool SidebarClearAllGlyphButton(const char* id_str, const ImVec2& size_arg, bool is_emphasized) {
    ImGuiWindow* window = ImGui::GetCurrentWindow();
    if (window->SkipItems) return false;

    ImGuiID id = window->GetID(id_str);
    ImVec2 pos = window->DC.CursorPos;
    ImRect bb(pos, ImVec2(pos.x + size_arg.x, pos.y + size_arg.y));

    ImGui::ItemSize(size_arg);
    if (!ImGui::ItemAdd(bb, id)) return false;

    bool hovered, held;
    bool pressed = ImGui::ButtonBehavior(bb, id, &hovered, &held);

    ImGuiStorage* storage = ImGui::GetStateStorage();
    float animT = storage->GetFloat(id + 1, is_emphasized ? 1.0f : 0.0f);
    float burst = storage->GetFloat(id + 2, 0.0f);
    if (pressed) burst = 1.0f;
    animT = ImLerp(animT, is_emphasized ? 1.0f : 0.0f, ImSaturate(ImGui::GetIO().DeltaTime * 10.0f));
    burst = ImMax(0.0f, burst - ImGui::GetIO().DeltaTime * 2.0f);
    storage->SetFloat(id + 1, animT);
    storage->SetFloat(id + 2, burst);

    auto mix = [](const ImVec4& a, const ImVec4& b, float t) -> ImVec4 {
        return ImVec4(
            a.x + (b.x - a.x) * t,
            a.y + (b.y - a.y) * t,
            a.z + (b.z - a.z) * t,
            a.w + (b.w - a.w) * t);
    };
    auto withAlpha = [](ImVec4 c, float a) -> ImVec4 { c.w = a; return c; };

    const auto& tcs = ThemeColors::current();
    const bool isLightFilterTheme = (tcs.filterBrowserBG.x + tcs.filterBrowserBG.y + tcs.filterBrowserBG.z) > 2.15f;
    const ImVec4 cue = mix(tcs.searchButtonBG, tcs.filterBrowserSelection, 0.46f);
    const ImVec4 baseBg = isLightFilterTheme
        ? mix(tcs.filterBrowserButtonBG, tcs.filterBrowserBG, 0.08f)
        : mix(tcs.filterBrowserButtonBG, tcs.filterBrowserBG, 0.28f);
    const ImVec4 activeBg = mix(baseBg, cue, isLightFilterTheme ? 0.14f : 0.18f);
    const ImVec4 border = mix(tcs.filterBrowserOutline, cue, isLightFilterTheme ? 0.22f : 0.14f);
    const ImVec4 glyph = isLightFilterTheme
        ? mix(tcs.filterBrowserText, tcs.mainWindowBG, 0.12f)
        : mix(tcs.filterBrowserText, cue, 0.20f);

    ImDrawList* dl = window->DrawList;
    const float rounding = 6.0f;
    const float burstT = 1.0f - burst;
    const float burstEase = 1.0f - powf(1.0f - ImSaturate(burstT), 3.0f);
    const float glow = (hovered ? 0.05f : 0.0f) + animT * 0.06f + burst * 0.12f;
    if (glow > 0.0f) {
        dl->AddCircleFilled(bb.GetCenter(), size_arg.x * (0.30f + burstEase * 0.16f), ImGui::GetColorU32(withAlpha(cue, glow)), 24);
    }
    dl->AddRectFilled(bb.Min, bb.Max, ImGui::GetColorU32(withAlpha((hovered || animT > 0.05f || burst > 0.01f) ? activeBg : baseBg, isLightFilterTheme ? 0.988f : 0.97f)), rounding);
    dl->AddRect(bb.Min, bb.Max, ImGui::GetColorU32(withAlpha(border, hovered ? 0.40f : (animT > 0.05f ? 0.34f : 0.24f))), rounding, 0, 1.0f);

    ImVec2 center = bb.GetCenter();
    float spacing = 4.6f;
    float baseRadius = 1.65f;
    for (int row = -1; row <= 1; ++row) {
        for (int col = -1; col <= 1; ++col) {
            bool isCenter = (row == 0 && col == 0);
            float dist = (float)(abs(row) + abs(col));
            float localT = ImClamp(animT * 1.05f + burst * 1.20f - dist * 0.16f, 0.0f, 1.0f);
            float scale = isCenter ? (1.0f + burst * 0.06f) : ImLerp(0.48f, 1.10f, localT);
            float alpha = isCenter ? 0.98f : ImLerp(isLightFilterTheme ? 0.18f : 0.24f, 0.94f, localT);
            ImVec2 p(center.x + col * spacing, center.y + row * spacing);
            dl->AddCircleFilled(p, baseRadius * scale, ImGui::GetColorU32(withAlpha(glyph, alpha)), 10);
        }
    }

    const float persistentBoxAlpha = hovered ? 0.32f : (animT > 0.05f ? (isLightFilterTheme ? 0.26f : 0.22f) : 0.0f);
    if (persistentBoxAlpha > 0.01f) {
        float half = 6.1f + animT * 0.8f;
        dl->AddRect(
            ImVec2(center.x - half, center.y - half),
            ImVec2(center.x + half, center.y + half),
            ImGui::GetColorU32(withAlpha(cue, persistentBoxAlpha)),
            3.2f, 0, 1.15f);
    }

    const float burstBoxAlpha = burst > 0.01f ? ImLerp(0.90f, 0.0f, burstEase) : 0.0f;
    if (burstBoxAlpha > 0.01f) {
        float half = 6.0f * ImLerp(1.0f, 3.1f, burstEase);
        dl->AddRect(
            ImVec2(center.x - half, center.y - half),
            ImVec2(center.x + half, center.y + half),
            ImGui::GetColorU32(withAlpha(cue, burstBoxAlpha)),
            3.2f, 0, ImLerp(1.45f, 0.45f, burstEase));
    }

    return pressed;
}

// 独立组件：PAN 旋钮 (半圆弧 + 白点 + 蓝字 + 左右排版)
// 布局：左侧 "PAN" 标签 → 中间半圆弧旋钮 → 右侧数值 (L/R/C)
// 拖拽改值、双击归零、右键归零
static bool PanKnob(const char* label, float* v, float v_min, float v_max, const ImVec4& transportSurface, const ImVec2& size_arg = ImVec2(110, 32)) {
    ImGuiWindow* window = ImGui::GetCurrentWindow();
    if (window->SkipItems) return false;

    ImGuiID id = window->GetID(label);
    ImVec2 pos = window->DC.CursorPos;
    ImRect bb(pos, ImVec2(pos.x + size_arg.x, pos.y + size_arg.y));

    ImGui::ItemSize(size_arg);
    if (!ImGui::ItemAdd(bb, id)) return false;

    bool hovered, held;
    ImGui::ButtonBehavior(bb, id, &hovered, &held);
    bool value_changed = false;

    // 1. 拖拽逻辑 (水平+垂直混合)
    if (held && ImGui::IsMouseDragging(0)) {
        float drag_delta = ImGui::GetIO().MouseDelta.x - ImGui::GetIO().MouseDelta.y;
        float range = v_max - v_min;
        *v += drag_delta * (range * 0.005f);
        if (*v < v_min) *v = v_min;
        if (*v > v_max) *v = v_max;
        value_changed = true;
    }
    // 双击归零
    if (hovered && ImGui::IsMouseDoubleClicked(0)) {
        *v = 0.0f;
        value_changed = true;
    }
    // 右键归零 (统一手势)
    if (hovered && ImGui::IsMouseClicked(1)) {
        *v = 0.0f;
        value_changed = true;
    }

    bool is_center = (*v == 0.0f);
    bool is_disabled = (GImGui->CurrentItemFlags & ImGuiItemFlags_Disabled) != 0;

    ImVec4* colors = ImGui::GetStyle().Colors;
    const bool isLightTheme = (colors[ImGuiCol_WindowBg].x + colors[ImGuiCol_WindowBg].y + colors[ImGuiCol_WindowBg].z) > 2.2f;
    // 2. 颜色设置 — disabled 时大幅降低亮度和 alpha
    ImU32 text_col, bg_arc_col, fill_arc_col, tick_col, dot_col;
    if (is_disabled) {
        if (isLightTheme) {
            text_col     = ImGui::GetColorU32(ImVec4(0.62f, 0.57f, 0.59f, 0.55f));
            bg_arc_col   = ImGui::GetColorU32(ImVec4(0.86f, 0.82f, 0.84f, 0.55f));
            fill_arc_col = ImGui::GetColorU32(ImVec4(0.76f, 0.71f, 0.73f, 0.55f));
            tick_col     = ImGui::GetColorU32(ImVec4(0.74f, 0.68f, 0.70f, 0.55f));
            dot_col      = ImGui::GetColorU32(ImVec4(0.68f, 0.63f, 0.65f, 0.55f));
        } else {
            text_col     = ImGui::GetColorU32(ImVec4(0.30f, 0.30f, 0.33f, 0.50f));
            bg_arc_col   = ImGui::GetColorU32(ImVec4(0.12f, 0.12f, 0.13f, 0.50f));
            fill_arc_col = ImGui::GetColorU32(ImVec4(0.35f, 0.35f, 0.37f, 0.50f));
            tick_col     = ImGui::GetColorU32(ImVec4(0.20f, 0.20f, 0.22f, 0.50f));
            dot_col      = ImGui::GetColorU32(ImVec4(0.40f, 0.40f, 0.42f, 0.50f));
        }
    } else {
        if (isLightTheme) {
            text_col = is_center ? ImGui::GetColorU32(ImVec4(0.45f, 0.40f, 0.42f, 1.0f))
                                 : ImGui::GetColorU32(ImVec4(0.46f, 0.30f, 0.36f, 1.0f));
            bg_arc_col   = ImGui::GetColorU32(ImVec4(0.84f, 0.80f, 0.82f, 1.0f));
            fill_arc_col = ImGui::GetColorU32(ImVec4(0.22f, 0.20f, 0.22f, 1.0f));
            tick_col = is_center ? ImGui::GetColorU32(ImVec4(0.64f, 0.59f, 0.62f, 1.0f))
                                 : ImGui::GetColorU32(ImVec4(0.35f, 0.32f, 0.34f, 1.0f));
            dot_col      = ImGui::GetColorU32(ImVec4(0.16f, 0.15f, 0.16f, 1.0f));
        } else {
            text_col = is_center ? ImGui::GetColorU32(ImVec4(0.45f, 0.45f, 0.48f, 1.0f))
                                 : ImGui::GetColorU32(ImVec4(0.38f, 0.65f, 0.98f, 1.0f));
            bg_arc_col   = ImGui::GetColorU32(ImVec4(0.15f, 0.15f, 0.16f, 1.0f));
            fill_arc_col = ImGui::GetColorU32(ImVec4(0.89f, 0.89f, 0.91f, 1.0f));
            tick_col = is_center ? ImGui::GetColorU32(ImVec4(0.32f, 0.32f, 0.36f, 1.0f))
                                 : ImGui::GetColorU32(ImVec4(0.63f, 0.63f, 0.67f, 1.0f));
            dot_col      = ImGui::GetColorU32(ImVec4(1.0f, 1.0f, 1.0f, 1.0f));
        }
    }

    const ImVec4 panSurface = is_disabled ? transportSurface : TransportContrast::Over(
        ImVec4(0, 0, 0, isLightTheme ? 0.04f : 0.12f), transportSurface);
    if (!is_disabled) {
        const auto readable = [&](ImU32 color) {
            return ImGui::GetColorU32(TransportContrast::ForSurface(ImGui::ColorConvertU32ToFloat4(color), panSurface, 3.2));
        };
        bg_arc_col = readable(bg_arc_col);
        dot_col = readable(dot_col);
        fill_arc_col = readable(fill_arc_col);
        tick_col = readable(tick_col);
        text_col = ImGui::GetColorU32(TransportContrast::ForSurface(
            ImGui::ColorConvertU32ToFloat4(text_col), transportSurface, 4.7));
    }
    if (TransportVisualAudit::Collecting()) {
        const ImU32 bg = ImGui::GetColorU32(panSurface);
        TransportVisualAudit::Record("pan.arc", false, bg_arc_col, bg, bb.Min, bb.Max, is_disabled);
        TransportVisualAudit::Record("pan.dot", false, dot_col, bg, bb.Min, bb.Max, is_disabled);
        if (!is_center) TransportVisualAudit::Record("pan.value", true, text_col,
            TransportVisualAudit::surface, bb.Min, bb.Max, is_disabled);
    }
    // 3. 标签已去除（节省空间）
    ImDrawList* dl = window->DrawList;

    // 4. 绘制半圆弧旋钮（左侧居中，右侧留给数值文字）
    ImVec2 arc_center = ImVec2(bb.Min.x + 20.0f, bb.Min.y + size_arg.y * 0.5f + 6.0f);
    float radius = 12.0f;
    float thickness = 2.5f;

    // 4.0 轻微底盘 (单层淡圆)
    if (!is_disabled) {
        dl->AddCircleFilled(arc_center, radius + 2.0f,
            ImGui::GetColorU32(isLightTheme ? ImVec4(0.0f, 0.0f, 0.0f, 0.04f) : ImVec4(0.0f, 0.0f, 0.0f, 0.12f)), 24);
    }

    // 角度：180°(左) → 360°(右)，270° 为正上方中心
    float angle_min = IM_PI;
    float angle_max = IM_PI * 2.0f;
    float angle_mid = IM_PI * 1.5f;

    // 4.1 背景圆弧 (完整半圆)
    dl->PathClear();
    dl->PathArcTo(arc_center, radius, angle_min, angle_max, 32);
    dl->PathStroke(bg_arc_col, 0, thickness);

    // 4.2 中心刻度线 (顶部垂直短线)
    ImVec2 tick_p1 = ImVec2(arc_center.x, arc_center.y - radius - 3.0f);
    ImVec2 tick_p2 = ImVec2(arc_center.x, arc_center.y - radius + 2.0f);
    dl->AddLine(tick_p1, tick_p2, tick_col, 1.5f);

    // 4.3 填充圆弧 (从中心向当前值方向延伸, 加粗)
    float percentage = (*v - v_min) / (v_max - v_min);
    float angle_val = angle_min + percentage * (angle_max - angle_min);

    if (!is_center) {
        dl->PathClear();
        if (percentage > 0.5f) {
            dl->PathArcTo(arc_center, radius, angle_mid, angle_val, 16);
        } else {
            dl->PathArcTo(arc_center, radius, angle_val, angle_mid, 16);
        }
        dl->PathStroke(fill_arc_col, 0, thickness);

    }

    // 4.4 当前位置指示点
    ImVec2 dot_pos = ImVec2(arc_center.x + radius * cosf(angle_val), arc_center.y + radius * sinf(angle_val));
    dl->AddCircleFilled(dot_pos, 3.0f, dot_col, 16);

    // 5. 绘制数值 — 右下角（与 BM 风格一致），居中时不显示
    if (!is_center) {
        char val_buf[16];
        if (*v < 0.0f)
            snprintf(val_buf, sizeof(val_buf), "L%.0f", -(*v));
        else
            snprintf(val_buf, sizeof(val_buf), "R%.0f", *v);
        const float knobFontPx = GetTypeScale(ImGui::GetFontSize()).caption;
        ImVec2 tsFull = ImGui::CalcTextSize(val_buf);
        const float relScale = knobFontPx / ImGui::GetFontSize();
        float tw = tsFull.x * relScale, th = tsFull.y * relScale;
        ImVec2 tPos(bb.Max.x - tw - 1.0f, bb.Max.y - th);
        dl->AddText(ImGui::GetFont(), knobFontPx, tPos, text_col, val_buf);
    }

    return value_changed;
}

// 中心感旋钮：左侧预留标签区防遮挡；中间半圆弧；右侧 20°(收紧) / 260°(拓宽) 扇形图标，示例图风格
static bool CenterSenseKnob(const char* label, float* v, float v_min, float v_max, const ImVec2& size_arg = ImVec2(148, 40)) {
    ImGuiWindow* window = ImGui::GetCurrentWindow();
    if (window->SkipItems) return false;

    ImGuiID id = window->GetID(label);
    ImVec2 pos = window->DC.CursorPos;
    ImRect bb(pos, ImVec2(pos.x + size_arg.x, pos.y + size_arg.y));

    ImGui::ItemSize(size_arg);
    if (!ImGui::ItemAdd(bb, id)) return false;

    bool hovered, held;
    ImGui::ButtonBehavior(bb, id, &hovered, &held);
    bool value_changed = false;

    if (held && ImGui::IsMouseDragging(0)) {
        float drag_delta = ImGui::GetIO().MouseDelta.x - ImGui::GetIO().MouseDelta.y;
        float range = v_max - v_min;
        *v += drag_delta * (range * 0.005f);
        if (*v < v_min) *v = v_min;
        if (*v > v_max) *v = v_max;
        value_changed = true;
    }
    if (hovered && ImGui::IsMouseDoubleClicked(0)) { *v = 0.0f; value_changed = true; }
    if (hovered && ImGui::IsMouseClicked(1)) { *v = 0.0f; value_changed = true; }

    bool is_center = (*v == 0.0f);
    bool is_disabled = (GImGui->CurrentItemFlags & ImGuiItemFlags_Disabled) != 0;

    ImVec4* colors = ImGui::GetStyle().Colors;
    const bool isLightTheme = (colors[ImGuiCol_WindowBg].x + colors[ImGuiCol_WindowBg].y + colors[ImGuiCol_WindowBg].z) > 2.2f;
    ImU32 text_col, bg_arc_col, fill_arc_col, tick_col, dot_col;
    if (is_disabled) {
        text_col     = isLightTheme ? ImGui::GetColorU32(ImVec4(0.62f, 0.57f, 0.59f, 0.55f)) : ImGui::GetColorU32(ImVec4(0.30f, 0.30f, 0.33f, 0.50f));
        bg_arc_col   = isLightTheme ? ImGui::GetColorU32(ImVec4(0.86f, 0.82f, 0.84f, 0.55f)) : ImGui::GetColorU32(ImVec4(0.12f, 0.12f, 0.13f, 0.50f));
        fill_arc_col = isLightTheme ? ImGui::GetColorU32(ImVec4(0.76f, 0.71f, 0.73f, 0.55f)) : ImGui::GetColorU32(ImVec4(0.35f, 0.35f, 0.37f, 0.50f));
        tick_col     = isLightTheme ? ImGui::GetColorU32(ImVec4(0.74f, 0.68f, 0.70f, 0.55f)) : ImGui::GetColorU32(ImVec4(0.20f, 0.20f, 0.22f, 0.50f));
        dot_col      = isLightTheme ? ImGui::GetColorU32(ImVec4(0.68f, 0.63f, 0.65f, 0.55f)) : ImGui::GetColorU32(ImVec4(0.40f, 0.40f, 0.42f, 0.50f));
    } else {
        text_col     = is_center ? ImGui::GetColorU32(ImVec4(0.45f, 0.45f, 0.48f, 1.0f)) : ImGui::GetColorU32(ImVec4(0.38f, 0.65f, 0.98f, 1.0f));
        bg_arc_col   = isLightTheme ? ImGui::GetColorU32(ImVec4(0.84f, 0.80f, 0.82f, 1.0f)) : ImGui::GetColorU32(ImVec4(0.15f, 0.15f, 0.16f, 1.0f));
        fill_arc_col = isLightTheme ? ImGui::GetColorU32(ImVec4(0.22f, 0.20f, 0.22f, 1.0f)) : ImGui::GetColorU32(ImVec4(0.89f, 0.89f, 0.91f, 1.0f));
        tick_col     = isLightTheme ? ImGui::GetColorU32(ImVec4(0.64f, 0.59f, 0.62f, 1.0f)) : ImGui::GetColorU32(ImVec4(0.32f, 0.32f, 0.36f, 1.0f));
        dot_col      = isLightTheme ? ImGui::GetColorU32(ImVec4(0.16f, 0.15f, 0.16f, 1.0f)) : ImGui::GetColorU32(ImVec4(1.0f, 1.0f, 1.0f, 1.0f));
    }

    // 弧线与图标居中
    ImDrawList* dl = window->DrawList;
    const float arc_zone = size_arg.x;
    ImVec2 arc_center = ImVec2(bb.Min.x + arc_zone * 0.5f, bb.Min.y + size_arg.y * 0.5f + 6.0f);
    float radius = 14.0f;
    float thickness = 2.5f;
    float angle_min = IM_PI;
    float angle_max = IM_PI * 2.0f;
    float angle_mid = IM_PI * 1.5f;

    // 轻微底盘
    if (!is_disabled) {
        dl->AddCircleFilled(arc_center, radius + 2.0f,
            ImGui::GetColorU32(isLightTheme ? ImVec4(0.0f, 0.0f, 0.0f, 0.04f) : ImVec4(0.0f, 0.0f, 0.0f, 0.12f)), 24);
    }

    dl->PathClear();
    dl->PathArcTo(arc_center, radius, angle_min, angle_max, 32);
    dl->PathStroke(bg_arc_col, 0, thickness);

    ImVec2 tick_p1 = ImVec2(arc_center.x, arc_center.y - radius - 3.0f);
    ImVec2 tick_p2 = ImVec2(arc_center.x, arc_center.y - radius + 2.0f);
    dl->AddLine(tick_p1, tick_p2, tick_col, 1.5f);

    float percentage = (*v - v_min) / (v_max - v_min);
    float angle_val = angle_min + percentage * (angle_max - angle_min);
    if (!is_center) {
        dl->PathClear();
        if (percentage > 0.5f)
            dl->PathArcTo(arc_center, radius, angle_mid, angle_val, 16);
        else
            dl->PathArcTo(arc_center, radius, angle_val, angle_mid, 16);
        dl->PathStroke(fill_arc_col, 0, thickness);
    }
    ImVec2 dot_pos = ImVec2(arc_center.x + radius * cosf(angle_val), arc_center.y + radius * sinf(angle_val));
    dl->AddCircleFilled(dot_pos, 3.5f, dot_col, 16);

    // 两个扇形图标：20° 收紧 / 260° 拓宽，示例图风格，更大更直观
    const float icon_r = 7.0f;
    const float icon_gap = 16.0f;
    ImVec2 icon_center_left  = ImVec2(arc_center.x - radius - icon_gap, arc_center.y);
    ImVec2 icon_center_right = ImVec2(arc_center.x + radius + icon_gap, arc_center.y);
    ImU32 icon_col = is_disabled ? ImGui::GetColorU32(ImVec4(0.4f, 0.4f, 0.42f, 0.5f)) : ImGui::GetColorU32(ImVec4(0.48f, 0.50f, 0.54f, 0.95f));

    // 20° 窄扇形 (收紧)
    const float narrow_deg = 20.0f * (3.14159265f / 180.0f);
    float a0 = IM_PI - narrow_deg * 0.5f, a1 = IM_PI + narrow_deg * 0.5f;
    dl->PathClear();
    dl->PathArcTo(icon_center_left, icon_r, a0, a1, 8);
    dl->PathLineTo(icon_center_left);
    dl->PathFillConvex(icon_col);

    // 260° 宽扇形 (拓宽)，留 100° 缺口朝左
    const float wide_start = 50.0f * (3.14159265f / 180.0f);
    const float wide_end   = 310.0f * (3.14159265f / 180.0f);
    dl->PathClear();
    dl->PathArcTo(icon_center_right, icon_r, wide_start, wide_end, 36);
    dl->PathLineTo(icon_center_right);
    dl->PathFillConvex(icon_col);

    return value_changed;
}

// Soundstage 扇形可视化弹窗（中心感控制的高级视图）

static constexpr float MagicEQDefaultHalfWidthPercent = 20.0f;

#if AURA_BUILD_DIAGNOSTICS && !AURA_INTERNAL_BETA
// UI-thread observation only: the QA bridge reads the reason after the real
// DrawMagicEQBar drag path has accepted or rejected the pointer movement.
int g_magicEqQaLastRejectReason = 0;
int g_magicEqQaActiveDragPart = 0;
#endif

static bool DrawMagicEQBar(const char* strId, MagicEQSettings& settings, int sampleRate,
                           bool& saveSettingsNow, const ImVec4& transportSurface, bool navyStateContrast) {
    ImGuiWindow* window = ImGui::GetCurrentWindow();
    if (!window || window->SkipItems) return false;
    settings.widgetWidth = std::clamp(settings.widgetWidth, 120.0f, 1600.0f);
    const MagicEQSettings originalSettings = settings;
    const float width = settings.widgetWidth;
    const ImVec2 pos = ImGui::GetCursorScreenPos();
    const ImVec2 size(width, 32.0f);
    const ImGuiID id = window->GetID(strId);
    const ImRect bounds(pos, ImVec2(pos.x + width, pos.y + size.y));
    ImGui::ItemSize(size);
    if (!ImGui::ItemAdd(bounds, id)) return false;

    enum class DragPart { None, Center, LeftEndpoint, RightEndpoint, ResizeLeft, ResizeRight };
    struct DragState {
        DragPart part = DragPart::None;
        float startX = 0.0f, startY = 0.0f;
        float startWidth = 180.0f;
        float startCenterPercent = 50.0f, startHalfWidthPercent = 10.0f;
        float startLowPercent = 40.0f, startHighPercent = 60.0f;
    };
    static DragState drag;
    static bool pendingSettingsSave = false;

    bool hovered = false, held = false;
    ImGui::ButtonBehavior(bounds, id, &hovered, &held);
    const ImGuiIO& io = ImGui::GetIO();
    const ImVec2 mouse = io.MousePos;
    const float statusWidth = std::min(60.0f, std::max(54.0f, width * 0.34f));
    const ImVec2 markMin(pos.x + 5.0f, pos.y + 4.0f);
    const ImVec2 markMax(markMin.x + 46.0f, markMin.y + 24.0f);
    const float steepnessLeft = markMax.x + 3.0f;
    const float steepnessRight = pos.x + width - statusWidth;
    const bool detailedRuler = width >= 440.0f;
    const float railInset = std::max(
        std::clamp((width - 180.0f) * (88.0f / 260.0f), 0.0f, 88.0f),
        std::clamp((width - 180.0f) * (80.0f / 140.0f), 0.0f, 80.0f));
    const float railLeft = pos.x + std::max({53.0f + railInset,
                                            width >= 180.0f ? 80.0f : 53.0f,
                                            width >= 600.0f ? 190.0f : 0.0f});
    const float railRight = std::max(railLeft + 12.0f, pos.x + width - statusWidth - 5.0f);
    const float railWidth = std::max(1.0f, railRight - railLeft);
    // At 120 px the mark, mode cell and rail leave a 10 px top-row slot.
    // Keep a menu hitbox there; the rail itself occupies the lower row.
    const float steepnessMinimumHitWidth = 10.0f;
    const float steepnessRulerRight = std::min(steepnessRight, railLeft - 4.0f);
    const float steepnessVisibleRight = steepnessRulerRight > steepnessLeft
        ? steepnessRulerRight
        : std::min(steepnessRight, steepnessLeft + steepnessMinimumHitWidth);
    const float railY = pos.y + 21.5f;
    const float gripTop = pos.y + 13.0f;
    const float gripBottom = pos.y + 29.0f;
    float lowHz = 0.0f, highHz = 0.0f;
    CenterSenseDsp::magicEQEdges(settings.centerFreq, settings.halfWidthPercent, lowHz, highHz);
    float centerPercent = CenterSenseDsp::magicEQFrequencyToPercent(settings.centerFreq);
    float lowPercent = CenterSenseDsp::magicEQFrequencyToPercent(lowHz);
    float highPercent = CenterSenseDsp::magicEQFrequencyToPercent(highHz);
    float centerX = railLeft + railWidth * centerPercent * 0.01f;
    float leftX = railLeft + railWidth * lowPercent * 0.01f;
    float rightX = railLeft + railWidth * highPercent * 0.01f;
    const bool leftResizeHit = hovered && mouse.x <= pos.x + 5.0f;
    const bool rightResizeHit = hovered && mouse.x >= pos.x + width - 5.0f;
    const bool toggleHit = hovered && mouse.x >= markMin.x && mouse.x < markMax.x &&
                           mouse.y >= markMin.y && mouse.y < markMax.y;
    const bool modeHit = hovered && mouse.x >= pos.x + width - statusWidth;
    const bool steepnessHit = hovered && steepnessVisibleRight > steepnessLeft &&
                              mouse.x >= steepnessLeft && mouse.x < steepnessVisibleRight &&
                              mouse.y < gripTop;
    const float leftDistance = std::fabs(mouse.x - leftX);
    const float rightDistance = std::fabs(mouse.x - rightX);
    const bool leftEndpointHit = hovered && leftDistance <= 7.0f && mouse.y >= gripTop && mouse.y <= gripBottom;
    const bool rightEndpointHit = hovered && rightDistance <= 7.0f && mouse.y >= gripTop && mouse.y <= gripBottom;
    const bool widthModifier = io.KeyCtrl || io.KeySuper;
    bool changed = false;
    bool dragLimited = false;
    CenterSenseDsp::MagicEQTailReason rejectionReason = CenterSenseDsp::MagicEQTailReason::None;

    if (ImGui::IsMouseClicked(ImGuiMouseButton_Left) && hovered) {
        drag.startX = mouse.x;
        drag.startY = mouse.y;
        drag.startWidth = width;
        drag.startCenterPercent = centerPercent;
        drag.startHalfWidthPercent = std::clamp(settings.halfWidthPercent, 1.0f, 50.0f);
        drag.startLowPercent = lowPercent;
        drag.startHighPercent = highPercent;
        if (leftResizeHit) {
            drag.part = DragPart::ResizeLeft;
        } else if (rightResizeHit) {
            drag.part = DragPart::ResizeRight;
        } else if (toggleHit) {
            settings.enabled = !settings.enabled;
            changed = true;
            drag.part = DragPart::None;
        } else if (steepnessHit) {
            ImGui::OpenPopup("MagicEQSteepnessPopup");
            drag.part = DragPart::None;
        } else if (modeHit) {
            settings.mode = settings.mode == MagicEQMode::Notch ? MagicEQMode::Pass : MagicEQMode::Notch;
            settings.enabled = true;
            changed = true;
            drag.part = DragPart::None;
        } else if (leftEndpointHit || rightEndpointHit) {
            settings.enabled = true;
            drag.part = leftDistance <= rightDistance ? DragPart::LeftEndpoint : DragPart::RightEndpoint;
            changed = true;
        } else {
            drag.part = DragPart::Center;
        }
    }

    if (hovered && ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left)) {
        settings.enabled = false;
        settings.centerFreq = 1000.0f;
        settings.halfWidthPercent = MagicEQDefaultHalfWidthPercent;
        drag.part = DragPart::None;
        changed = true;
    }
    if (hovered && ImGui::IsMouseClicked(ImGuiMouseButton_Right)) {
        if (modeHit) {
            ImGui::OpenPopup("MagicEQSteepnessPopup");
            drag.part = DragPart::None;
        } else {
            settings.enabled = false;
            settings.centerFreq = 1000.0f;
            settings.halfWidthPercent = MagicEQDefaultHalfWidthPercent;
            drag.part = DragPart::None;
            changed = true;
        }
    }
    struct SlopeDisplay {
        char compact[64]{}, shortValue[48]{}, fallback[8]{}, menu[160]{}, detail[320]{};
    };
    // Four fixed slots; rapid dragging can never grow the cache.
    struct TailAvailabilityCache {
        float center = -1.0f, width = -1.0f;
        int sampleRate = -1;
        MagicEQMode mode = MagicEQMode::Pass;
        CenterSenseDsp::MagicEQTailEstimate entries[4]{};
    };
    static TailAvailabilityCache tailCache;
    const auto availabilityFor = [&](CenterSenseDsp::MagicEQSteepness grade) {
        if (tailCache.center != settings.centerFreq || tailCache.width != settings.halfWidthPercent ||
            tailCache.sampleRate != sampleRate || tailCache.mode != settings.mode) {
            tailCache.center = settings.centerFreq;
            tailCache.width = settings.halfWidthPercent;
            tailCache.sampleRate = sampleRate;
            tailCache.mode = settings.mode;
            for (int index = 0; index < 4; ++index) {
                CenterSenseDsp::MagicEQProcessParams params{};
                params.enabled = true;
                params.mode = settings.mode;
                params.steepness = static_cast<CenterSenseDsp::MagicEQSteepness>(index);
                params.centerFreq = settings.centerFreq;
                params.halfWidthPercent = settings.halfWidthPercent;
                tailCache.entries[index] = CenterSenseDsp::estimateMagicEQTail(params, sampleRate);
            }
        }
        return tailCache.entries[static_cast<int>(grade)];
    };
    const auto availabilityReason = [&](CenterSenseDsp::MagicEQTailReason reason) {
        return reason == CenterSenseDsp::MagicEQTailReason::TailBudget
            ? L(MagicEQ_TailTooLong) : L(MagicEQ_FrequencyUnavailable);
    };
    const auto slopeDisplay = [&](CenterSenseDsp::MagicEQSteepness grade, bool withDetail = false) {
        SlopeDisplay display{};
        const int nominal = grade == CenterSenseDsp::MagicEQSteepness::Soft ? 12
            : grade == CenterSenseDsp::MagicEQSteepness::Steep ? 24
            : grade == CenterSenseDsp::MagicEQSteepness::VerySteep ? 48 : 144;
        if (grade == CenterSenseDsp::MagicEQSteepness::Brickwall) {
            std::snprintf(display.compact, sizeof(display.compact), "%s", L(MagicEQ_BrickwallApprox));
            std::snprintf(display.shortValue, sizeof(display.shortValue), "%d", nominal);
            std::snprintf(display.menu, sizeof(display.menu), "%s (~%d dB/oct)",
                          L(MagicEQ_BrickwallApprox), nominal);
        } else {
            std::snprintf(display.compact, sizeof(display.compact), "%d dB/oct", nominal);
            std::snprintf(display.shortValue, sizeof(display.shortValue), "%d", nominal);
            std::snprintf(display.menu, sizeof(display.menu), "%d dB/oct", nominal);
        }
        std::snprintf(display.fallback, sizeof(display.fallback), "~");
        if (!withDetail) return display;
        CenterSenseDsp::MagicEQProcessParams params{};
        params.enabled = settings.enabled;
        params.mode = settings.mode;
        params.steepness = grade;
        params.centerFreq = settings.centerFreq;
        params.halfWidthPercent = settings.halfWidthPercent;
        const auto slopes = CenterSenseDsp::measureMagicEQLocalSlope(params, sampleRate);
        const auto reasonText = [](CenterSenseDsp::MagicEQSlopeUnavailable reason) {
            using Reason = CenterSenseDsp::MagicEQSlopeUnavailable;
            if (reason == Reason::Bypass) return L(MagicEQ_SlopeBypass);
            if (reason == Reason::FrequencyLimit) return L(MagicEQ_SlopeFrequencyLimit);
            if (reason == Reason::InvalidSampleRate) return L(MagicEQ_SlopeSampleRate);
            return L(MagicEQ_SlopeNarrowBand);
        };
        const auto sideText = [&](const CenterSenseDsp::MagicEQLocalSlopeSide& side,
                                  const char* sideName, char* shortText, size_t shortCapacity,
                                  char* detailText, size_t detailCapacity) {
            if (side.valid) {
                std::snprintf(shortText, shortCapacity, "%s %+.1f dB/oct", sideName, side.dbPerOctave);
                std::snprintf(detailText, detailCapacity, "%s %+.1f dB/oct (%.1f–%.1f Hz)",
                              sideName, side.dbPerOctave, side.fromHz, side.toHz);
            } else {
                std::snprintf(shortText, shortCapacity, "%s —", sideName);
                std::snprintf(detailText, detailCapacity, "%s — %s", sideName, reasonText(side.reason));
            }
        };
        char lowShort[72]{}, highShort[72]{}, lowDetail[150]{}, highDetail[150]{};
        sideText(slopes.low, L(MagicEQ_SlopeLowSide), lowShort, sizeof(lowShort),
                 lowDetail, sizeof(lowDetail));
        sideText(slopes.high, L(MagicEQ_SlopeHighSide), highShort, sizeof(highShort),
                 highDetail, sizeof(highDetail));
        std::snprintf(display.detail, sizeof(display.detail), "%s\n%s", lowDetail, highDetail);
        return display;
    };
    const auto drawSteepnessCurve = [](ImDrawList* target, ImVec2 origin, MagicEQMode mode,
                                        CenterSenseDsp::MagicEQSteepness grade, ImU32 color) {
        const float depth = grade == CenterSenseDsp::MagicEQSteepness::Soft ? 3.0f
            : (grade == CenterSenseDsp::MagicEQSteepness::Steep ? 5.0f : 7.0f);
        const float direction = mode == MagicEQMode::Notch ? 1.0f : -1.0f;
        if (grade == CenterSenseDsp::MagicEQSteepness::VerySteep ||
            grade == CenterSenseDsp::MagicEQSteepness::Brickwall) {
            const ImVec2 sharpCurve[5] = {
                ImVec2(origin.x, origin.y), ImVec2(origin.x + 6.0f, origin.y),
                ImVec2(origin.x + 9.0f, origin.y + direction * depth),
                ImVec2(origin.x + 12.0f, origin.y), ImVec2(origin.x + 18.0f, origin.y)
            };
            target->AddPolyline(sharpCurve, 5, color, 0, 1.5f);
            return;
        }
        ImVec2 curve[7];
        for (int point = 0; point < 7; ++point) {
            const float t = static_cast<float>(point) / 6.0f;
            const float arc = 1.0f - std::pow(std::fabs(2.0f * t - 1.0f),
                grade == CenterSenseDsp::MagicEQSteepness::Soft ? 2.0f : 4.0f);
            curve[point] = ImVec2(origin.x + t * 18.0f, origin.y + direction * depth * arc);
        }
        target->AddPolyline(curve, 7, color, 0, 1.5f);
    };
    if (BeginTransientScrollbarPopup("MagicEQSteepnessPopup")) {
        ImGui::TextUnformatted(L(MagicEQ_NominalEdgeSlope));
        if (settings.mode == MagicEQMode::Notch && ImGui::IsItemHovered())
            ImGui::SetTooltip("%s", L(MagicEQ_NotchNominalExplanation));
        const bool soft = settings.steepness == CenterSenseDsp::MagicEQSteepness::Soft;
        const bool steep = settings.steepness == CenterSenseDsp::MagicEQSteepness::Steep;
        const bool verySteep = settings.steepness == CenterSenseDsp::MagicEQSteepness::VerySteep;
        const bool brickwall = settings.steepness == CenterSenseDsp::MagicEQSteepness::Brickwall;
        const auto menuRow = [&](CenterSenseDsp::MagicEQSteepness grade, bool selected) {
            ImGui::Indent(22.0f);
            const SlopeDisplay display = slopeDisplay(grade);
            const auto availability = availabilityFor(grade);
            // With no file loaded there is no sample rate to evaluate. Let the
            // user choose a grade; the real file's 200 ms gate applies on load.
            const bool selectable = sampleRate <= 0 || availability.available;
            const bool clicked = ImGui::MenuItem(display.menu, nullptr, selected, selectable);
            const ImVec2 itemMin = ImGui::GetItemRectMin();
            const ImVec2 itemMax = ImGui::GetItemRectMax();
#if AURA_BUILD_DIAGNOSTICS && !AURA_INTERNAL_BETA
            if (ThemeInspector::IsCollecting()) {
                const char* gradeZone = grade == CenterSenseDsp::MagicEQSteepness::Soft
                    ? "transport.magicEQ.gradeSoft"
                    : grade == CenterSenseDsp::MagicEQSteepness::Steep
                    ? "transport.magicEQ.gradeSteep"
                    : grade == CenterSenseDsp::MagicEQSteepness::VerySteep
                    ? "transport.magicEQ.gradeVerySteep"
                    : "transport.magicEQ.gradeBrickwall";
                ThemeInspector::RegisterZone(itemMin, itemMax, gradeZone, nullptr,
                                             "src/main.cpp:MagicEQSteepnessPopup");
            }
#endif
            if (ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled)) {
                if (sampleRate <= 0) ImGui::SetTooltip("%s", L(MagicEQ_UnloadedGradeHint));
                else if (!availability.available) ImGui::SetTooltip("%s", availabilityReason(availability.reason));
                else {
                    const SlopeDisplay detail = slopeDisplay(grade, true);
                    float edgeLow = 0.0f, edgeHigh = 0.0f;
                    CenterSenseDsp::magicEQEdges(settings.centerFreq, settings.halfWidthPercent,
                                                  edgeLow, edgeHigh);
                    char bandDetail[192]{};
                    std::snprintf(bandDetail, sizeof(bandDetail), L(MagicEQ_BandDetail),
                                  settings.centerFreq, edgeLow, edgeHigh,
                                  settings.centerFreq / std::max(1.0f, edgeHigh - edgeLow));
                    if (settings.mode == MagicEQMode::Notch)
                        ImGui::SetTooltip("%s: %s\n%s\n%s\n%s", L(MagicEQ_NominalEdgeSlope),
                                          display.menu, bandDetail, detail.detail,
                                          L(MagicEQ_NotchNominalExplanation));
                    else
                        ImGui::SetTooltip("%s: %s\n%s\n%s", L(MagicEQ_NominalEdgeSlope),
                                          display.menu, bandDetail, detail.detail);
                }
            }
            const auto& menuTheme = ThemeColors::current();
            drawSteepnessCurve(ImGui::GetWindowDrawList(),
                               ImVec2(itemMin.x - 20.0f, (itemMin.y + itemMax.y) * 0.5f),
                               settings.mode, grade, ImGui::GetColorU32(menuTheme.controlAccent));
            ImGui::Unindent(22.0f);
            return clicked;
        };
        if (menuRow(CenterSenseDsp::MagicEQSteepness::Soft, soft)) {
            settings.steepness = CenterSenseDsp::MagicEQSteepness::Soft;
            settings.enabled = true;
            changed = true;
        }
        if (menuRow(CenterSenseDsp::MagicEQSteepness::Steep, steep)) {
            settings.steepness = CenterSenseDsp::MagicEQSteepness::Steep;
            settings.enabled = true;
            changed = true;
        }
        if (menuRow(CenterSenseDsp::MagicEQSteepness::VerySteep, verySteep)) {
            settings.steepness = CenterSenseDsp::MagicEQSteepness::VerySteep;
            settings.enabled = true;
            changed = true;
        }
        if (menuRow(CenterSenseDsp::MagicEQSteepness::Brickwall, brickwall)) {
            settings.steepness = CenterSenseDsp::MagicEQSteepness::Brickwall;
            settings.enabled = true;
            changed = true;
        }
        ImGui::EndPopup();
    }

    if (drag.part != DragPart::None && held && ImGui::IsMouseDragging(ImGuiMouseButton_Left)) {
        const float deltaX = mouse.x - drag.startX;
        const float deltaY = mouse.y - drag.startY;
        if (drag.part == DragPart::ResizeLeft || drag.part == DragPart::ResizeRight) {
            const float direction = drag.part == DragPart::ResizeLeft ? -1.0f : 1.0f;
            settings.widgetWidth = std::clamp(drag.startWidth + deltaX * direction, 120.0f, 1600.0f);
        } else {
            settings.enabled = true;
            if (drag.part == DragPart::LeftEndpoint) {
                const float nextLow = drag.startLowPercent + deltaX / railWidth * 100.0f;
                CenterSenseDsp::magicEQSetLowEdgePercent(nextLow, settings.centerFreq, settings.halfWidthPercent);
            } else if (drag.part == DragPart::RightEndpoint) {
                const float nextHigh = drag.startHighPercent + deltaX / railWidth * 100.0f;
                CenterSenseDsp::magicEQSetHighEdgePercent(nextHigh, settings.centerFreq, settings.halfWidthPercent);
            } else {
                float nextHalf = drag.startHalfWidthPercent;
                if (widthModifier) nextHalf = std::clamp(nextHalf - deltaY * 0.25f, 1.0f, 50.0f);
                const float nextCenter = std::clamp(drag.startCenterPercent + deltaX / railWidth * 100.0f,
                                                   nextHalf, 100.0f - nextHalf);
                settings.centerFreq = CenterSenseDsp::magicEQPercentToFrequency(nextCenter);
                settings.halfWidthPercent = nextHalf;
            }
        }
        changed = true;
    }
    if (hovered && std::fabs(io.MouseWheel) > 0.0f) {
        settings.enabled = true;
        settings.halfWidthPercent = std::clamp(settings.halfWidthPercent + io.MouseWheel * 1.5f, 1.0f, 50.0f);
        changed = true;
    }

    // The selected grade must never silently turn into dry audio at an unsupported
    // sample rate or after a frequency/width drag. Widget resizing is independent.
    // The 40% first-use target is a visual target, not permission to exceed
    // the current sample rate and 200 ms tail limit. On first enable only,
    // choose the widest valid band no wider than that target.
    if (settings.enabled && !originalSettings.enabled && sampleRate > 0 &&
        settings.halfWidthPercent == MagicEQDefaultHalfWidthPercent &&
        !availabilityFor(settings.steepness).available) {
        for (float candidate = MagicEQDefaultHalfWidthPercent - 1.0f;
             candidate >= 1.0f; candidate -= 1.0f) {
            const auto available = CenterSenseDsp::estimateMagicEQTail(
                CenterSenseDsp::MagicEQProcessParams{true, settings.mode,
                    settings.steepness, settings.centerFreq, candidate}, sampleRate);
            if (available.available) {
                settings.halfWidthPercent = candidate;
                break;
            }
        }
    }
    const auto currentAvailability = availabilityFor(settings.steepness);
    if (settings.enabled && sampleRate > 0 && !currentAvailability.available) {
        rejectionReason = currentAvailability.reason;
        dragLimited = drag.part == DragPart::Center || drag.part == DragPart::LeftEndpoint ||
            drag.part == DragPart::RightEndpoint;
        const float resizedWidth = settings.widgetWidth;
        settings = originalSettings;
        settings.widgetWidth = resizedWidth;
        if (originalSettings.enabled &&
            !CenterSenseDsp::estimateMagicEQTail(
                CenterSenseDsp::MagicEQProcessParams{true, originalSettings.mode,
                    originalSettings.steepness, originalSettings.centerFreq,
                    originalSettings.halfWidthPercent}, sampleRate).available) {
            settings.enabled = false; // visible bypass after a file/sample-rate change
            changed = true;
        } else {
            changed = resizedWidth != originalSettings.widgetWidth;
        }
    }

    if (changed) pendingSettingsSave = true;
    if (ImGui::IsMouseReleased(ImGuiMouseButton_Left)) {
        drag.part = DragPart::None;
        saveSettingsNow = pendingSettingsSave;
        pendingSettingsSave = false;
    } else if (!ImGui::IsMouseDown(ImGuiMouseButton_Left) && changed) {
        saveSettingsNow = true;
        pendingSettingsSave = false;
    }
    if (!ImGui::IsWindowFocused(ImGuiFocusedFlags_RootAndChildWindows)) drag.part = DragPart::None;
    CenterSenseDsp::magicEQEdges(settings.centerFreq, settings.halfWidthPercent, lowHz, highHz);
    centerPercent = CenterSenseDsp::magicEQFrequencyToPercent(settings.centerFreq);
    lowPercent = CenterSenseDsp::magicEQFrequencyToPercent(lowHz);
    highPercent = CenterSenseDsp::magicEQFrequencyToPercent(highHz);
    centerX = railLeft + railWidth * centerPercent * 0.01f;
    leftX = railLeft + railWidth * lowPercent * 0.01f;
    rightX = railLeft + railWidth * highPercent * 0.01f;

    const ThemeColorScheme& theme = ThemeColors::current();
    const ImVec4 primaryText = TransportContrast::ForSurface(theme.interfaceText, transportSurface, 4.7);
    const ImU32 baseText = ImGui::GetColorU32(primaryText);
    const ImU32 muted = ImGui::GetColorU32(TransportContrast::ForSurface(
        ImVec4(primaryText.x, primaryText.y, primaryText.z, .48f), transportSurface, 4.7));
    const auto navyEq = MistBlueChrome::EqState(theme, transportSurface, settings.enabled, toggleHit, toggleHit && held);
    const ImVec4 navyBandColor = settings.enabled && settings.mode == MagicEQMode::Notch
        ? theme.waveformPositionLine : navyEq.signal;
    const ImVec4 statusColor = navyStateContrast ? navyBandColor : TransportContrast::ForSurface(!settings.enabled ? theme.interfaceText
        : (settings.mode == MagicEQMode::Notch ? theme.waveformSelectionEdge : theme.controlAccent), transportSurface, 3.2);
    const ImU32 status = ImGui::GetColorU32(statusColor);
    ImDrawList* draw = window->DrawList;
    // The EQ shares the transport bar surface; only the switch, rail and mode
    // have their own shapes. This keeps the full player bar visually continuous.
    const bool markHover = toggleHit;
    const bool markPressed = markHover && held;
    const ImVec4 markBackground = navyStateContrast ? navyEq.button : !settings.enabled
        ? ImLerp(transportSurface, theme.chromeBorder, markHover ? 0.38f : 0.23f)
        : ImLerp(transportSurface, theme.controlAccent,
                 markPressed ? 0.06f : (markHover ? 0.17f : 0.11f));
    const ImU32 markColor = navyStateContrast ? ImGui::GetColorU32(navyEq.ink) : ImGui::GetColorU32(TransportContrast::ForSurface(settings.enabled
        ? ImLerp(theme.controlAccent, primaryText, markHover && !markPressed ? .23f : 0.f)
        : ImGui::ColorConvertU32ToFloat4(muted),
        TransportContrast::Over(markBackground, transportSurface), 4.7));
    draw->AddRectFilled(markMin, markMax, ImGui::GetColorU32(markBackground), 3.0f);
    const ImVec2 magicEqStar(markMin.x + 9.5f, markMin.y + 12.0f);
    const float starOuter = 5.5f, starInner = 2.2f;
    draw->PathClear();
    for (int point = 0; point < 8; ++point) {
        const float angle = -3.14159265f * 0.5f + static_cast<float>(point) * 3.14159265f / 4.0f;
        const float radius = (point % 2 == 0) ? starOuter : starInner;
        draw->PathLineTo(ImVec2(magicEqStar.x + std::cos(angle) * radius,
                                magicEqStar.y + std::sin(angle) * radius));
    }
    draw->PathFillConcave(markColor);
    ImFont* markFont = GetUIFontEmphasis();
    draw->AddText(markFont ? markFont : ImGui::GetFont(), 14.0f,
                  ImVec2(markMin.x + 18.0f, markMin.y + 3.5f), markColor, "EQ");
    const ImU32 markLineColor = settings.enabled
        ? ImGui::GetColorU32(ImLerp(theme.controlAccent, transportSurface,
                                   markPressed ? 0.12f : (markHover ? 0.04f : 0.0f)))
        : ImGui::GetColorU32(ImVec4(theme.interfaceText.x, theme.interfaceText.y,
                                    theme.interfaceText.z, 0.22f));
    draw->AddLine(ImVec2(markMin.x + 3.0f, markMax.y - 1.0f),
                  ImVec2(markMax.x - 3.0f, markMax.y - 1.0f), markLineColor,
                  markPressed ? 2.0f : 1.5f);
    TransportVisualAudit::RecordGlyphs("eq.label", markColor, ImGui::GetColorU32(markBackground),
        ImVec2(markMin.x + 18.0f, markMin.y + 3.5f), "EQ", markFont, 14.0f);
    const SlopeDisplay steepnessLabel = slopeDisplay(settings.steepness);
    const float slopeAvailableWidth = std::max(0.0f, steepnessVisibleRight - steepnessLeft);
    const ImVec2 fullSlopeSize = ImGui::CalcTextSize(steepnessLabel.compact);
    const ImVec2 shortSlopeSize = ImGui::CalcTextSize(steepnessLabel.shortValue);
    if (slopeAvailableWidth >= 4.0f) {
        const float slopeClipHeight = std::max(13.0f, 1.0f + std::max(fullSlopeSize.y, shortSlopeSize.y));
        draw->PushClipRect(ImVec2(steepnessLeft, pos.y),
                           ImVec2(steepnessVisibleRight, pos.y + slopeClipHeight), true);
        if (slopeAvailableWidth >= 22.0f + fullSlopeSize.x) {
            drawSteepnessCurve(draw, ImVec2(steepnessLeft + 1.0f, pos.y + 8.0f), settings.mode,
                               settings.steepness, settings.enabled ? status : muted);
            draw->AddText(ImVec2(steepnessLeft + 22.0f, pos.y + 1.0f), muted,
                          steepnessLabel.compact);
            TransportVisualAudit::RecordGlyphs("eq.slope", muted, ImGui::GetColorU32(transportSurface),
                ImVec2(steepnessLeft + 22.0f, pos.y + 1.0f), steepnessLabel.compact);
        } else if (slopeAvailableWidth >= shortSlopeSize.x + 2.0f) {
            draw->AddText(ImVec2(steepnessLeft + 1.0f, pos.y + 1.0f), muted,
                          steepnessLabel.shortValue);
            TransportVisualAudit::RecordGlyphs("eq.slope", muted, ImGui::GetColorU32(transportSurface),
                ImVec2(steepnessLeft + 1.0f, pos.y + 1.0f), steepnessLabel.shortValue);
        } else if (slopeAvailableWidth >= 18.0f) {
            drawSteepnessCurve(draw, ImVec2(steepnessLeft, pos.y + 8.0f), settings.mode,
                               settings.steepness, settings.enabled ? status : muted);
            TransportVisualAudit::Record("eq.slope", false, settings.enabled ? status : muted,
                ImGui::GetColorU32(transportSurface), ImVec2(steepnessLeft, pos.y),
                ImVec2(steepnessVisibleRight, pos.y + 13.0f));
        } else {
            const float arrowX = steepnessLeft + slopeAvailableWidth * 0.5f;
            draw->AddTriangleFilled(ImVec2(arrowX - 3.0f, pos.y + 4.0f),
                                    ImVec2(arrowX + 3.0f, pos.y + 4.0f),
                                    ImVec2(arrowX, pos.y + 8.0f), muted);
            TransportVisualAudit::Record("eq.slope", false, muted, ImGui::GetColorU32(transportSurface),
                ImVec2(arrowX - 3.0f, pos.y + 4.0f), ImVec2(arrowX + 3.0f, pos.y + 8.0f));
        }
        draw->PopClipRect();
    }

    const ImU32 tickColor = ImGui::GetColorU32(TransportContrast::ForSurface(
        ImVec4(primaryText.x, primaryText.y, primaryText.z, .20f), transportSurface, 3.1));
    struct RulerTick { float frequencyHz; const char* label; };
    constexpr RulerTick majorTicks[] = {
        {20.0f, "20"}, {50.0f, "50"}, {100.0f, "100"}, {200.0f, "200"},
        {500.0f, "500"}, {1000.0f, "1k"}, {2000.0f, "2k"}, {5000.0f, "5k"},
        {10000.0f, "10k"}, {20000.0f, "20k"}
    };
    const char* rangeText = GetMagicEQFrequencyLabel(lowHz, highHz);
    const ImVec2 rangeSize = ImGui::CalcTextSize(rangeText);
    char centerLabel[16] = {};
    if (settings.centerFreq >= 1000.0f)
        std::snprintf(centerLabel, sizeof(centerLabel), "%.2gk", settings.centerFreq / 1000.0f);
    else
        std::snprintf(centerLabel, sizeof(centerLabel), "%.0f", settings.centerFreq);
    const ImVec2 centerLabelSize = ImGui::CalcTextSize(centerLabel);
    const float frequencyInfoLeft = railLeft;
    const float frequencyInfoWidth = railRight - railLeft;
    const bool rangeFitsSelection = rangeSize.x + 16.0f <= rightX - leftX;
    const bool centerFitsSelection = centerLabelSize.x + 12.0f <= rightX - leftX;
    const bool showFrequencyFallback = !rangeFitsSelection && !centerFitsSelection;
    const char* compactFrequencyFallback = "i";
    const ImVec2 compactFrequencyFallbackSize = ImGui::CalcTextSize(compactFrequencyFallback);
    const char* frequencyInfoText = rangeSize.x + 8.0f <= frequencyInfoWidth ? rangeText
        : (centerLabelSize.x + 8.0f <= frequencyInfoWidth ? centerLabel
            : (compactFrequencyFallbackSize.x + 4.0f <= frequencyInfoWidth
                ? compactFrequencyFallback : ""));
    const ImVec2 frequencyInfoSize = ImGui::CalcTextSize(frequencyInfoText);
    const float frequencyInfoX = std::clamp(centerX - frequencyInfoSize.x * 0.5f,
                                            frequencyInfoLeft + 2.0f,
                                            railRight - frequencyInfoSize.x - 2.0f);
    const float frequencyLabelMinX = frequencyInfoX - 2.0f;
    const float frequencyLabelMaxX = frequencyInfoX + frequencyInfoSize.x + 2.0f;
    if (detailedRuler && railWidth >= 220.0f) {
        for (float decade = 10.0f; decade <= 10000.0f; decade *= 10.0f) {
            for (int multiple = 2; multiple <= 9; ++multiple) {
                if (multiple == 2 || multiple == 5) continue;
                const float frequency = decade * static_cast<float>(multiple);
                if (frequency < 20.0f || frequency > 20000.0f) continue;
                const float x = railLeft + railWidth *
                    CenterSenseDsp::magicEQFrequencyToPercent(frequency) * 0.01f;
                draw->AddLine(ImVec2(x, railY - 2.5f), ImVec2(x, railY + 2.5f), tickColor);
            }
        }
    }
    float lastLabelRight = railLeft - 4.0f;
    for (const RulerTick& tick : majorTicks) {
        const float x = railLeft + railWidth *
            CenterSenseDsp::magicEQFrequencyToPercent(tick.frequencyHz) * 0.01f;
        draw->AddLine(ImVec2(x, railY - 5.0f), ImVec2(x, railY + 5.0f), tickColor);
        if (detailedRuler && railWidth >= 220.0f) {
            const ImVec2 labelSize = ImGui::CalcTextSize(tick.label);
            const float labelLeft = std::clamp(x - labelSize.x * 0.5f,
                                               railLeft, railRight - labelSize.x);
            const bool frequencyLabelOverlap = frequencyInfoText[0] != '\0' &&
                labelLeft < frequencyLabelMaxX + 2.0f &&
                labelLeft + labelSize.x > frequencyLabelMinX - 2.0f;
            if (!frequencyLabelOverlap && labelLeft >= lastLabelRight + 4.0f) {
                draw->AddText(ImVec2(labelLeft, pos.y + 2.0f), muted, tick.label);
                TransportVisualAudit::RecordGlyphs("eq.tick_label", muted, ImGui::GetColorU32(transportSurface),
                    ImVec2(labelLeft, pos.y + 2.0f), tick.label);
                lastLabelRight = labelLeft + labelSize.x;
            }
        }
    }
    draw->AddLine(ImVec2(railLeft, railY), ImVec2(railRight, railY),
                  navyStateContrast && !settings.enabled ? status : muted,
                  navyStateContrast && !settings.enabled ? 1.0f : 2.0f);
    const float bandAlpha = navyStateContrast && !settings.enabled ? 0.f
        : (settings.enabled ? (navyStateContrast ? .60f : .42f) : .20f);
    draw->AddRectFilled(ImVec2(leftX, railY - 4.5f), ImVec2(rightX, railY + 4.5f),
                        ImGui::GetColorU32(ImVec4(statusColor.x, statusColor.y, statusColor.z,
                                                   bandAlpha)), 4.5f);
    draw->AddLine(ImVec2(leftX, railY), ImVec2(rightX, railY), status,
                  navyStateContrast ? (settings.enabled ? 3.0f : 1.0f) : 2.0f);
    const ImVec4 bandSurface = TransportContrast::Over(
        ImVec4(statusColor.x, statusColor.y, statusColor.z, bandAlpha), transportSurface);
    const ImU32 centerDotColor = ImGui::GetColorU32(TransportContrast::ForSurface(primaryText, bandSurface, 3.2));
    if (navyStateContrast && !settings.enabled)
        draw->AddCircle(ImVec2(centerX, railY), 3.2f, centerDotColor, 12, 1.0f);
    else
        draw->AddCircleFilled(ImVec2(centerX, railY), 3.2f, centerDotColor, 12);
    const auto drawVerticalGrip = [&](float x, bool highlighted, const char* auditId) {
        const ImU32 gripFill = highlighted ? ImGui::GetColorU32(TransportContrast::ForSurface(
            theme.controlAccent, transportSurface, 3.2)) : status;
        draw->AddRectFilled(ImVec2(x - 3.5f, gripTop), ImVec2(x + 3.5f, gripBottom),
                            ImGui::GetColorU32(transportSurface), 2.0f);
        draw->AddRect(ImVec2(x - 3.5f, gripTop), ImVec2(x + 3.5f, gripBottom), gripFill, 2.0f);
        draw->AddLine(ImVec2(x, gripTop + 3.0f), ImVec2(x, gripBottom - 3.0f), gripFill, 1.5f);
        TransportVisualAudit::Record(auditId, false, gripFill, ImGui::GetColorU32(transportSurface),
            ImVec2(x - 3.5f, gripTop), ImVec2(x + 3.5f, gripBottom));
    };
    drawVerticalGrip(leftX, leftEndpointHit || drag.part == DragPart::LeftEndpoint, "eq.grip");
    drawVerticalGrip(rightX, rightEndpointHit || drag.part == DragPart::RightEndpoint, "eq.grip.right");
    TransportVisualAudit::Record("eq.center", false, centerDotColor, ImGui::GetColorU32(bandSurface), ImVec2(centerX - 3.2f, railY - 3.2f), ImVec2(centerX + 3.2f, railY + 3.2f));
    // Frequency detail lives above the rail so the chosen band and grips stay clear.
    if (frequencyInfoText[0] != '\0') {
        draw->AddRectFilled(ImVec2(frequencyLabelMinX, pos.y + 1.0f),
                            ImVec2(frequencyLabelMaxX, pos.y + 14.0f),
                            ImGui::GetColorU32(transportSurface), 2.0f);
        draw->AddText(ImVec2(frequencyInfoX, pos.y + 1.0f),
                      showFrequencyFallback ? baseText : muted, frequencyInfoText);
        TransportVisualAudit::RecordGlyphs("eq.frequency", showFrequencyFallback ? baseText : muted,
            ImGui::GetColorU32(transportSurface), ImVec2(frequencyInfoX, pos.y + 1), frequencyInfoText);
    } else {
        const float indicatorX = frequencyInfoLeft + frequencyInfoWidth * 0.5f;
        draw->AddTriangleFilled(ImVec2(indicatorX - 3.0f, pos.y + 4.0f),
                                ImVec2(indicatorX + 3.0f, pos.y + 4.0f),
                                ImVec2(indicatorX, pos.y + 10.0f), status);
    }
    const bool draggingFrequency = ImGui::IsMouseDown(ImGuiMouseButton_Left) &&
        ImGui::IsWindowFocused(ImGuiFocusedFlags_RootAndChildWindows) &&
        (drag.part == DragPart::LeftEndpoint || drag.part == DragPart::RightEndpoint ||
         drag.part == DragPart::Center);
    if (draggingFrequency) {
        const float bubbleHz = drag.part == DragPart::LeftEndpoint ? lowHz :
            (drag.part == DragPart::RightEndpoint ? highHz : settings.centerFreq);
        const float bubbleCenter = drag.part == DragPart::LeftEndpoint ? leftX :
            (drag.part == DragPart::RightEndpoint ? rightX : centerX);
        char bubbleText[48] = {};
        if (bubbleHz >= 1000.0f) {
            if (dragLimited)
                std::snprintf(bubbleText, sizeof(bubbleText), "%s %.1f kHz",
                              L(MagicEQ_LimitedPrefix), bubbleHz / 1000.0f);
            else std::snprintf(bubbleText, sizeof(bubbleText), "%.1f kHz", bubbleHz / 1000.0f);
        } else {
            if (dragLimited)
                std::snprintf(bubbleText, sizeof(bubbleText), "%s %.0f Hz",
                              L(MagicEQ_LimitedPrefix), bubbleHz);
            else std::snprintf(bubbleText, sizeof(bubbleText), "%.0f Hz", bubbleHz);
        }
        const ImVec2 bubbleSize = ImGui::CalcTextSize(bubbleText);
        const float bubbleWidth = bubbleSize.x + 10.0f;
        const float bubbleX = std::clamp(bubbleCenter - bubbleWidth * 0.5f,
                                         pos.x + 4.0f, pos.x + width - bubbleWidth - 4.0f);
        ImDrawList* bubbleDraw = ImGui::GetForegroundDrawList();
        bubbleDraw->AddRectFilled(ImVec2(bubbleX, pos.y - 19.0f),
                                  ImVec2(bubbleX + bubbleWidth, pos.y - 3.0f),
                                  ImGui::GetColorU32(transportSurface), 2.0f);
        bubbleDraw->AddRect(ImVec2(bubbleX, pos.y - 19.0f),
                            ImVec2(bubbleX + bubbleWidth, pos.y - 3.0f),
                            ImGui::GetColorU32(theme.controlAccent), 2.0f);
        bubbleDraw->AddTriangleFilled(ImVec2(bubbleCenter - 3.0f, pos.y - 3.0f),
                                      ImVec2(bubbleCenter + 3.0f, pos.y - 3.0f),
                                      ImVec2(bubbleCenter, pos.y),
                                      ImGui::GetColorU32(theme.controlAccent));
        bubbleDraw->AddText(ImVec2(bubbleX + 5.0f, pos.y - 18.0f), baseText, bubbleText);
    }

    const float modeLeft = pos.x + width - statusWidth;
    const auto navyMode = MistBlueChrome::EqModeState(theme, transportSurface, settings.enabled,
        settings.mode == MagicEQMode::Notch, modeHit, modeHit && held);
    const ImVec4 modeBackground = navyStateContrast ? navyMode.button : TransportContrast::Over(
        ImVec4(statusColor.x, statusColor.y, statusColor.z, settings.enabled ? .16f : .10f), transportSurface);
    draw->AddRectFilled(ImVec2(modeLeft + 1.0f, pos.y + 4.0f),
                        ImVec2(pos.x + width - 4.0f, pos.y + 28.0f),
                        navyStateContrast ? ImGui::GetColorU32(modeBackground) : ImGui::GetColorU32(ImVec4(statusColor.x, statusColor.y, statusColor.z,
                                                   settings.enabled ? 0.16f : 0.10f)), 4.0f);
    if (navyStateContrast && settings.enabled && settings.mode == MagicEQMode::Pass)
        draw->AddRect(ImVec2(modeLeft + 1.0f, pos.y + 4.0f),
                      ImVec2(pos.x + width - 4.0f, pos.y + 28.0f),
                      ImGui::GetColorU32(theme.chromeBorder), 4.0f);
    const ImU32 modeInk = navyStateContrast ? ImGui::GetColorU32(navyMode.ink) : ImGui::GetColorU32(TransportContrast::ForSurface(
        settings.enabled ? statusColor : ImGui::ColorConvertU32ToFloat4(muted), modeBackground, 4.7));
    const char* modeLabel = GetMagicEQModeLabel(settings.enabled, static_cast<int>(settings.mode));
    const float modeTextWidth = ImGui::CalcTextSize(modeLabel).x;
    if (modeTextWidth + 8.0f > statusWidth) {
        modeLabel = !settings.enabled ? L(MagicEQ_ModeBypassCompact)
            : (settings.mode == MagicEQMode::Notch
                ? L(MagicEQ_ModeNotchCompact) : L(MagicEQ_ModePassCompact));
    }
    // The current language's compact word normally fits even at 120 px.
    // At enlarged font scales use a language-neutral shape, never an English initial.
    const bool modeIconOnly = ImGui::CalcTextSize(modeLabel).x + 8.0f > statusWidth;
    const ImVec2 labelSize = modeIconOnly ? ImVec2(0.0f, 0.0f) : ImGui::CalcTextSize(modeLabel);
    draw->PushClipRect(ImVec2(modeLeft + 3.0f, pos.y + 4.0f),
                       ImVec2(pos.x + width - 3.0f, pos.y + 28.0f), true);
    if (modeIconOnly) {
        const float iconX = modeLeft + (statusWidth - 18.0f) * 0.5f;
        const ImU32 modeShape = navyStateContrast ? modeInk : (settings.enabled ? status : muted);
        TransportVisualAudit::Record("eq.mode", false, modeShape,
            ImGui::GetColorU32(modeBackground), ImVec2(iconX, pos.y + 8), ImVec2(iconX + 18, pos.y + 24));
        if (settings.enabled)
            drawSteepnessCurve(draw, ImVec2(iconX, pos.y + 16.0f), settings.mode,
                               settings.steepness, modeShape);
        else
            draw->AddLine(ImVec2(iconX, pos.y + 16.0f),
                          ImVec2(iconX + 18.0f, pos.y + 16.0f), modeShape, 1.5f);
    } else {
        draw->AddText(ImVec2(modeLeft + std::max(4.0f, (statusWidth - labelSize.x) * 0.5f), pos.y + 8.0f),
                      modeInk, modeLabel);
        TransportVisualAudit::RecordGlyphs("eq.mode", modeInk, ImGui::GetColorU32(modeBackground),
            ImVec2(modeLeft + std::max(4.0f, (statusWidth - labelSize.x) * 0.5f), pos.y + 8.0f), modeLabel);
    }
    draw->PopClipRect();
    draw->AddLine(ImVec2(pos.x + 1.5f, pos.y + 9.0f), ImVec2(pos.x + 1.5f, pos.y + 23.0f), status, 1.5f);
    draw->AddLine(ImVec2(pos.x + width - 1.5f, pos.y + 9.0f),
                  ImVec2(pos.x + width - 1.5f, pos.y + 23.0f), status, 1.5f);

    if (hovered && settings.invalidInput) {
        ImGui::SetTooltip("%s", L(MagicEQ_InvalidParameters));
    } else if (hovered && rejectionReason != CenterSenseDsp::MagicEQTailReason::None) {
        ImGui::SetTooltip("%s", availabilityReason(rejectionReason));
    } else if (hovered && !settings.enabled &&
               !availabilityFor(settings.steepness).available) {
        ImGui::SetTooltip("%s", availabilityReason(availabilityFor(settings.steepness).reason));
    } else if (steepnessHit) {
        const SlopeDisplay detail = slopeDisplay(settings.steepness, true);
        ImGui::SetTooltip("%s", detail.detail);
    } else if (modeHit) {
        ImGui::SetTooltip("%s", GetMagicEQModeLabel(settings.enabled, static_cast<int>(settings.mode)));
    } else if (hovered) {
        ImGui::SetTooltip("%s", GetMagicEQFrequencyLabel(lowHz, highHz));
    }
#if AURA_BUILD_DIAGNOSTICS && !AURA_INTERNAL_BETA
    g_magicEqQaLastRejectReason = static_cast<int>(rejectionReason);
    g_magicEqQaActiveDragPart = ImGui::IsMouseDown(ImGuiMouseButton_Left)
        ? static_cast<int>(drag.part) : 0;
    if (ThemeInspector::IsCollecting()) {
        const auto zone = [&](const char* key, float x1, float y1, float x2, float y2) {
            ThemeInspector::RegisterZone(ImVec2(x1, y1), ImVec2(x2, y2),
                                         key, nullptr, "src/main.cpp:DrawMagicEQBar");
        };
        zone("transport.magicEQ.leftGrip", leftX - 7.0f, gripTop,
             leftX + 7.0f, gripBottom);
        zone("transport.magicEQ.rightGrip", rightX - 7.0f, gripTop,
             rightX + 7.0f, gripBottom);
        zone("transport.magicEQ.centerGrip", centerX - 7.0f, gripTop,
             centerX + 7.0f, gripBottom);
        zone("transport.magicEQ.mode", pos.x + width - statusWidth, pos.y,
             pos.x + width, pos.y + 32.0f);
        zone("transport.magicEQ.grade", steepnessLeft, pos.y,
             steepnessVisibleRight, gripTop);
        zone("transport.magicEQ.power", markMin.x, markMin.y,
             markMax.x, markMax.y);
    }
#endif
    return changed;
}

static bool DrawSoundstagePopupContent(float* centerSenseValue) {
    // 映射: centerSense [-1,1] → angle [30°,270°]（-1=窄/Mono, 0=中间150°, 1=宽/Surround）
    float angle_deg = 150.0f + (*centerSenseValue) * 120.0f;
    if (angle_deg < 30.0f) angle_deg = 30.0f;
    if (angle_deg > 270.0f) angle_deg = 270.0f;

    ImGuiWindow* window = ImGui::GetCurrentWindow();
    ImDrawList* dl = window->DrawList;
    const ImVec2 size(160.0f, 130.0f);
    ImVec2 pos = window->DC.CursorPos;
    ImRect bb(pos, ImVec2(pos.x + size.x, pos.y + size.y));
    ImGuiID id = window->GetID("##SoundstageCtrl");

    ImGui::ItemSize(bb);
    if (!ImGui::ItemAdd(bb, id)) return false;

    bool hovered, held;
    ImGui::ButtonBehavior(bb, id, &hovered, &held);
    bool changed = false;

    if (held) {
        float dx = ImGui::GetIO().MouseDelta.x;
        *centerSenseValue += dx * 0.008f;
        if (*centerSenseValue < -1.0f) *centerSenseValue = -1.0f;
        if (*centerSenseValue > 1.0f) *centerSenseValue = 1.0f;
        angle_deg = 150.0f + (*centerSenseValue) * 120.0f;
        changed = true;
    }
    if (hovered && ImGui::IsMouseDoubleClicked(0)) { *centerSenseValue = 0.0f; angle_deg = 150.0f; changed = true; }

    // 颜色
    ImU32 colLine    = IM_COL32(194, 231, 255, 255);
    ImU32 colAxis    = IM_COL32(255, 255, 255, 25);

    ImVec2 center(bb.Min.x + size.x * 0.5f, bb.Min.y + 78.0f);
    float rIn = 12.0f, rOut = 62.0f;
    float angleRad = angle_deg * (3.14159265f / 180.0f);
    float startA = -3.14159265f / 2.0f - angleRad / 2.0f;
    float endA   = -3.14159265f / 2.0f + angleRad / 2.0f;

    // 扇形填充（安全 API，不用 PrimReserve）
    ImU32 colFill = IM_COL32(0, 74, 119, 120);
    dl->PathArcTo(center, rOut, startA, endA, 24);
    dl->PathArcTo(center, rIn,  endA, startA, 24);
    dl->PathFillConvex(colFill);

    // 参考线
    dl->AddLine(ImVec2(center.x - rOut, center.y), ImVec2(center.x + rOut, center.y), colAxis);
    float gA = 30.0f * (3.14159265f / 180.0f);
    for (int side = -1; side <= 1; side += 2) {
        float a = -3.14159265f / 2.0f + side * gA;
        ImVec2 p1(center.x + cosf(a) * rIn, center.y + sinf(a) * rIn);
        ImVec2 p2(center.x + cosf(a) * rOut, center.y + sinf(a) * rOut);
        for (int i = 0; i < 8; i += 2) {
            ImVec2 d1(p1.x + (p2.x-p1.x)*(i/8.0f), p1.y + (p2.y-p1.y)*(i/8.0f));
            ImVec2 d2(p1.x + (p2.x-p1.x)*((i+1)/8.0f), p1.y + (p2.y-p1.y)*((i+1)/8.0f));
            dl->AddLine(d1, d2, colAxis);
        }
    }

    // 圆弧轮廓
    dl->PathArcTo(center, rIn,  startA, endA, 24); dl->PathStroke(colLine, 0, 1.2f);
    dl->PathArcTo(center, rOut, startA, endA, 24); dl->PathStroke(colLine, 0, 1.2f);
    // 连接线
    dl->AddLine(ImVec2(center.x+cosf(startA)*rIn, center.y+sinf(startA)*rIn),
                ImVec2(center.x+cosf(startA)*rOut, center.y+sinf(startA)*rOut), colLine, 1.2f);
    dl->AddLine(ImVec2(center.x+cosf(endA)*rIn, center.y+sinf(endA)*rIn),
                ImVec2(center.x+cosf(endA)*rOut, center.y+sinf(endA)*rOut), colLine, 1.2f);

    // 中心点
    dl->AddCircleFilled(center, 2.0f, colLine);
    dl->AddCircle(center, 6.0f, IM_COL32(194, 231, 255, 60), 0, 1.0f);

    // 标签
    const char* modeText = (angle_deg <= 80.0f) ? "TIGHT" : (angle_deg >= 220.0f) ? "WIDE" : "NEUTRAL";
    char valBuf[32]; snprintf(valBuf, sizeof(valBuf), "%.0f%%", (*centerSenseValue) * 100.0f);
    ImVec2 ts1 = ImGui::CalcTextSize(modeText);
    ImVec2 ts2 = ImGui::CalcTextSize(valBuf);
    dl->AddText(ImVec2(bb.Min.x + (size.x - ts1.x) * 0.5f, bb.Max.y - 28.0f), IM_COL32(255,255,255,120), modeText);
    dl->AddText(ImVec2(bb.Min.x + (size.x - ts2.x) * 0.5f, bb.Max.y - 14.0f), IM_COL32(255,255,255,180), valBuf);

    return changed;
}

// Dockable Panel System

static ImVec4 ResolveThreeDotSplitterColor(
    const ThemeColorScheme& theme,
    bool hovered,
    bool active)
{
    auto mix = [](const ImVec4& a, const ImVec4& b, float t) {
        return ImVec4(
            a.x + (b.x - a.x) * t,
            a.y + (b.y - a.y) * t,
            a.z + (b.z - a.z) * t,
            a.w + (b.w - a.w) * t);
    };
    const bool lightTheme = ThemeColors::isLightChromeTheme(theme);
    ImVec4 color = mix(
        mix(theme.waveformSplitterLine, theme.chromeBorder, 0.28f),
        theme.interfaceText,
        lightTheme ? 0.68f : 0.38f);
    if (active) color = mix(color, theme.controlAccent, 0.18f);
    color.w = active
        ? (lightTheme ? 0.58f : 0.68f)
        : (hovered ? (lightTheme ? 0.78f : 0.88f)
                   : (lightTheme ? 0.68f : 0.85f));
    return color;
}

static ImVec4 ResolveWaveformSplitterDragBg(const ThemeColorScheme& theme) {
    auto mix = [](const ImVec4& a, const ImVec4& b, float t) {
        return ImVec4(
            a.x + (b.x - a.x) * t,
            a.y + (b.y - a.y) * t,
            a.z + (b.z - a.z) * t,
            a.w + (b.w - a.w) * t);
    };
    ImVec4 color = mix(theme.waveformSplitterBG, theme.controlAccent, 0.10f);
    color.w = 1.0f;
    return color;
}

// Draw a vertical splitter and handle dragging to resize
// Returns true if the width was changed
// invertDelta: true for right-side panels (drag left = increase width)
bool VerticalSplitter(const char* id, float* panelWidth, float minWidth = 100.0f, float maxWidth = 600.0f, float height = 0.0f, bool invertDelta = false) {
    ImGuiIO& io = ImGui::GetIO();
    ImVec2 pos = ImGui::GetCursorScreenPos();
    float splitterWidth = 12.0f;  // Keep left/right seams visually identical; interaction affordance should not create asymmetry in chrome width
    if (height <= 0) height = ImGui::GetContentRegionAvail().y;

// Use InvisibleButton for interaction.
    ImGui::InvisibleButton(id, ImVec2(splitterWidth, height));
    if (ThemeInspector::IsCollecting()) {
        const char* annotationKey = nullptr;
        if (id && std::strcmp(id, "##LeftSplitter") == 0) annotationKey = "splitter.left";
        else if (id && std::strcmp(id, "##RightSplitter") == 0) annotationKey = "splitter.right";
        if (annotationKey) {
            ThemeInspector::RegisterLastItem(annotationKey, "Panel splitter", "src/main.cpp:VerticalSplitter");
        }
    }
    bool hovered = ImGui::IsItemHovered();
    bool active = ImGui::IsItemActive();
    const bool draggingResize = active && ImGui::IsMouseDragging(0);

    if (hovered || active) {
        ImGui::SetMouseCursor(ImGuiMouseCursor_ResizeEW);
    }

    ImDrawList* dl = ImGui::GetWindowDrawList();
    const ThemeColorScheme& splitterTheme = ThemeColors::current();
    const float cx = pos.x + splitterWidth * 0.5f;
    const ImVec4 splitterColor = ResolveThreeDotSplitterColor(
        splitterTheme, hovered, draggingResize);

    // Three dots along vertical axis (centered): filter|results and results|info splitters.
    // Keep the hit target alive while hiding the visual affordance after idle.
    {
        const float midY = pos.y + height * 0.5f;
        const float gap = ImClamp(height * 0.018f, 5.0f, 9.0f);
        const float edgePad = gap + 3.0f;
        if (height > edgePad * 2.0f + 1.0f) {
            const float r = draggingResize ? 1.95f : (hovered ? 2.15f : 2.0f);
            const ImU32 dotCol = ImGui::GetColorU32(splitterColor);
            aura::ui::workspace::DrawThreeDotSplitterGrip(
                dl, ImVec2(cx, midY), ImVec2(0.0f, 1.0f), gap, r, dotCol);
        }
    }

    if (draggingResize) {
        float delta = io.MouseDelta.x;
        if (invertDelta) delta = -delta;  // Invert for right-side panels
        *panelWidth = std::clamp(*panelWidth + delta, minWidth, maxWidth);
        return true;
    }

    return false;
}

// Draw a horizontal splitter and handle dragging to resize
bool HorizontalSplitter(const char* id, float* panelHeight, float minHeight, float maxHeight, float width, bool growWhenDraggingDown) {
    ImGuiIO& io = ImGui::GetIO();
    ImVec2 pos = ImGui::GetCursorScreenPos();
    float splitterHeight = 6.0f;  // Visible enough to read as a drag target without becoming a heavy black bar.
    if (width <= 0) width = ImGui::GetContentRegionAvail().x;

    ImGui::InvisibleButton(id, ImVec2(width, splitterHeight));
    if (ThemeInspector::IsCollecting() && id && std::strcmp(id, "##WaveformSplitter") == 0) {
        ThemeInspector::RegisterLastItem(
            "splitter.waveform", "Waveform splitter", "src/main.cpp:HorizontalSplitter");
    }
    bool hovered = ImGui::IsItemHovered();
    bool active = ImGui::IsItemActive();
    const bool draggingResize = active && ImGui::IsMouseDragging(0);
    const bool minimalistLightSplitter = ThemeColors::isLightChromeTheme(ThemeColors::current());
    const bool sidebarSubpaneSplitter = id && std::strstr(id, "RelatedPathsTreeSplitter") != nullptr;

    if (hovered || active) {
        ImGui::SetMouseCursor(ImGuiMouseCursor_ResizeNS);
    }

    // Fill the splitter band so light themes do not expose a dark window seam.
    ImDrawList* dl = ImGui::GetWindowDrawList();
    auto splitterWithAlpha = [](ImVec4 c, float a) {
        c.w = a;
        return c;
    };
    auto splitterMix = [](const ImVec4& a, const ImVec4& b, float t) {
        return ImVec4(
            a.x + (b.x - a.x) * t,
            a.y + (b.y - a.y) * t,
            a.z + (b.z - a.z) * t,
            a.w + (b.w - a.w) * t);
    };
    const ThemeColorScheme& splitterTheme = ThemeColors::current();
    const ImVec4 transportSeamBg = splitterWithAlpha(
        splitterMix(splitterTheme.transportBarBG, splitterTheme.waveformBG, 0.38f),
        1.0f);
    const ImVec4 waveformSplitterDragBg = ResolveWaveformSplitterDragBg(splitterTheme);
    const ImVec4 idleSeamBg = transportSeamBg;
    const ImVec4 splitterBg = splitterWithAlpha(
        sidebarSubpaneSplitter
            ? splitterTheme.sidebarSubpaneBG
            : (minimalistLightSplitter
                ? splitterTheme.waveformBG
                : (active
                    ? waveformSplitterDragBg
                    : hovered
                        ? splitterMix(transportSeamBg, splitterTheme.chromeBorder, 0.06f)
                        : idleSeamBg)),
        (minimalistLightSplitter && !sidebarSubpaneSplitter) ? 0.0f : 1.0f);
    const bool drawSidebarSubpaneBand = sidebarSubpaneSplitter && (hovered || active);
    if ((!sidebarSubpaneSplitter && (!minimalistLightSplitter || hovered || active)) || drawSidebarSubpaneBand) {
        dl->AddRectFilled(pos, ImVec2(pos.x + width, pos.y + splitterHeight), ImGui::GetColorU32(splitterBg), 0.0f);
    }
    float cy = pos.y + splitterHeight * 0.5f;

    // Keep the splitter readable as a drag target even at rest.
    {
        const float midX = pos.x + width * 0.5f;
        const float gap = ImClamp(width * 0.018f, 5.0f, 9.0f);
        const float edgePad = gap + 3.0f;
        if (width > edgePad * 2.0f + 1.0f) {
            const float r = draggingResize ? 1.95f : (hovered ? 2.15f : 2.0f);
            const ImVec4 dotRgb = ResolveThreeDotSplitterColor(
                splitterTheme, hovered, draggingResize);
            const ImU32 dotCol = ImGui::GetColorU32(dotRgb);
            aura::ui::workspace::DrawThreeDotSplitterGrip(
                dl, ImVec2(midX, cy), ImVec2(1.0f, 0.0f), gap, r, dotCol);
        }
    }

    if (draggingResize) {
        float delta = io.MouseDelta.y;
        *panelHeight = std::clamp(
            *panelHeight + (growWhenDraggingDown ? delta : -delta),
            minHeight,
            maxHeight);  // Default: drag up = increase bottom panel height.
        return true;
    }

    return false;
}

aura::ui::dock::DockLayout g_dockLayout;
aura::ui::dock::DockDragSession g_dockDrag(g_dockLayout);
static uint64_t g_dockGeometryRevision = 1;
static AppState::PanelState g_searchResultsDockPanel;
static aura::ui::dock::DockTitleGesture g_dockTitleGesture;
static AppState::PanelState* g_dockGesturePanel = nullptr;
static AppState::PanelState g_dockGesturePanelBefore;
static aura::ui::dock::DockRect g_dockGestureRectBefore;
static void* g_dockGestureCaptureWindow = nullptr;
static bool g_dockGestureNativeReleased = false;
static bool g_dockGestureInterrupted = false;
static std::string g_dockRestoreFloatingModule;
static std::vector<std::string> g_dockCommittedThisFrame;
static aura::ui::dock::DockDropPlan g_dockDropPlan;
static std::string g_dockTitleHoverModule;
static int g_dockTitleHoverZone = 0; // 1 = Dockable title band.
