    ImGui::Dummy(ImVec2(0.0f, style.ItemSpacing.y + style.FramePadding.y * 0.35f));
    ImGui::SetCursorPosX(contentStartX);
    ImGui::PushStyleColor(ImGuiCol_Text, bodyColor);
