    const ImVec4 kThemeDockCenterBg = kUseSoftChromeTheme
        ? uiMix(kThemeDockBase, kCurrentTheme.frameBgBase, 0.22f)
        : kThemeDockBase;
    const bool kUseLightDockChrome =
        (kThemeDockBg.x + kThemeDockBg.y + kThemeDockBg.z) > 2.15f;
    const ImVec4 kLegacyDockTitleSurface = uiWithAlpha(
        uiMix(kThemeDockBg, kThemeDockCenterBg, 0.08f), 0.88f);
