    const ImVec4 kLightSoftHudBg = uiWithAlpha(uiMix(kCurrentTheme.dialogBG, kCurrentTheme.waveformBG, 0.42f), 0.92f);
    const ImVec4 kLightSoftHudLine = uiWithAlpha(uiMix(kCurrentTheme.controlAccent, kCurrentTheme.resultsSelection, 0.28f), 0.72f);
    const ImVec4 kLightSoftHudZone = uiWithAlpha(uiMix(kCurrentTheme.resultsSelection, kCurrentTheme.controlAccent, 0.30f), 0.52f);
    const ImVec4 kLightSoftHudText = uiWithAlpha(uiMix(kThemeTextStrong, kCurrentTheme.controlAccent, 0.10f), 1.0f);
    const ImVec4 kLightSoftRegionTop = uiWithAlpha(uiMix(kCurrentTheme.resultsSelection, kCurrentTheme.controlAccent, 0.32f), 0.14f);
    const ImVec4 kLightSoftRegionMid = uiWithAlpha(uiMix(kCurrentTheme.resultsSelection, kCurrentTheme.waveformSecondaryColor, 0.26f), 0.09f);
    const ImVec4 kLightSoftRegionGlow = uiWithAlpha(uiMix(kCurrentTheme.resultsSelection, kCurrentTheme.controlAccent, 0.26f), 0.34f);
    const ImVec4 kLightSoftRegionEdge = uiWithAlpha(uiMix(kCurrentTheme.controlAccent, kCurrentTheme.waveformSecondaryColor, 0.34f), 0.42f);
