    // Transfer / Export Dialog (F-008)

    // The transfer feature now uses the shared function-window shell. Keep
    // the legacy popup only for callers that have not opted into that shell.
    if (state.showTransferDialog && !state.panelTransfer.visible) {
        ImGui::OpenPopup((std::string(L(Export_FileTitle)) + "###TransferDlg").c_str());
        state.showTransferDialog = false;
    }
    if (!state.panelTransfer.visible &&
        BeginTransientScrollbarPopupModal((std::string(L(Export_FileTitle)) + "###TransferDlg").c_str(), nullptr, ImGuiWindowFlags_AlwaysAutoResize)) {
        { ReadingTextScope _readingPopup;  // dialog body is a reading surface
        EscClosePopup();
        ImGui::Text(L(Dlg_SelectedNFiles), state.transferTotalCount);
        ImGui::Separator();

        // Destination folder
        ImGui::Text("%s", L(Export_TargetFolder));
        ImGui::SetNextItemWidth(400);
        ImGui::InputText("##TransferDest", state.transferDestFolder, sizeof(state.transferDestFolder));
        ImGui::SameLine();
        if (ImGui::Button(L(Main_TransferBrowseBtn2))) {
            std::string folder = OpenFolderDialog(g_hwnd);
            if (!folder.empty()) {
                strncpy_s(state.transferDestFolder, sizeof(state.transferDestFolder), folder.c_str(), _TRUNCATE);
                state.settings.defaultExportPath = folder;
                MarkSettingsDirty(state);
            }
        }

        // File format
        ImGui::Spacing();
        if (ImGui::Checkbox(L(Export_KeepFormat), &state.transferUseSourceFormat)) {
            CaptureDialogTransferSettings(state);
            MarkSettingsDirty(state);
        }
        if (!state.transferUseSourceFormat) {
            static auto fileTypes = TransferEngine::getFileTypeChoices();
            ImGui::SetNextItemWidth(150);
            if (BeginTransientScrollbarCombo(L(Export_OutputFormat), state.transferFileType < (int)fileTypes.size() ? fileTypes[state.transferFileType].first.c_str() : "WAV")) {
                for (int i = 0; i < (int)fileTypes.size(); i++) {
                    if (ImGui::Selectable(fileTypes[i].first.c_str(), state.transferFileType == i)) {
                        state.transferFileType = i;
                        CaptureDialogTransferSettings(state);
                        MarkSettingsDirty(state);
                    }
                }
                ImGui::EndCombo();
            }
        }

        // Folder organization strategy
        static auto strategies = TransferEngine::getFolderStrategyList();
        ImGui::SetNextItemWidth(250);
        if (BeginTransientScrollbarCombo(L(Export_DirStrategy), state.transferFolderStrategy < (int)strategies.size() ? strategies[state.transferFolderStrategy].second.c_str() : "SingleFolder")) {
            for (int i = 0; i < (int)strategies.size(); i++) {
                if (ImGui::Selectable(strategies[i].second.c_str(), state.transferFolderStrategy == i)) {
                    state.transferFolderStrategy = i;
                    CaptureDialogTransferSettings(state);
                    MarkSettingsDirty(state);
                }
            }
            ImGui::EndCombo();
        }

        // Existing file behavior
        static auto behaviors = TransferEngine::getExistingBehaviorChoices();
        ImGui::SetNextItemWidth(200);
        if (BeginTransientScrollbarCombo(L(Export_ExistingFile), state.transferExistingBehavior < (int)behaviors.size() ? behaviors[state.transferExistingBehavior].first.c_str() : "Skip")) {
            for (int i = 0; i < (int)behaviors.size(); i++) {
                if (ImGui::Selectable(behaviors[i].first.c_str(), state.transferExistingBehavior == i)) {
                    state.transferExistingBehavior = i;
                    CaptureDialogTransferSettings(state);
                    MarkSettingsDirty(state);
                }
            }
            ImGui::EndCombo();
        }

        if (ImGui::Checkbox(L(Export_EmbedMeta), &state.transferEmbedMetadata)) {
            CaptureDialogTransferSettings(state);
            MarkSettingsDirty(state);
        }

        // Status / progress
        if (state.transferInProgress) {
            float progress = state.transferTotalCount > 0 ? (float)state.transferCompletedCount / state.transferTotalCount : 0.f;
            ImGui::ProgressBar(progress, ImVec2(-1, 0));
            ImGui::Text(L(Main_TaskProgressFmt), state.transferCompletedCount, state.transferTotalCount, state.transferErrorCount);
        }
        const std::string transferShown = state.TransferStatusText();  // H1: UI-thread render of keyed status
        if (!transferShown.empty()) {
            bool isError = state.transferStatusKind == AppState::TransferStatusKind::Error ||
                           state.transferStatusKind == AppState::TransferStatusKind::Fail;
            if (isError) ImGui::TextColored(ImVec4(1,0.4f,0.4f,1), "%s", transferShown.c_str());
            else ImGui::TextColored(ImVec4(0.4f,1,0.4f,1), "%s", transferShown.c_str());
        }

        ImGui::Separator();
        bool destValid = state.transferDestFolder[0] != '\0';
        if (!destValid) ImGui::BeginDisabled();
        if (ImGui::Button(L(Export_Start), ImVec2(120, 0)) && !state.transferInProgress) {
            // Validate destination directory
            std::string destDir = state.transferDestFolder;
            if (Platform::FileSystem::IsNetworkPath(destDir)) {
                state.setTransferStatus(L(Write_BlockedNetworkLibrary), AppState::TransferStatusKind::Error);
            } else {
            state.settings.defaultExportPath = destDir;
            CaptureDialogTransferSettings(state);
            MarkSettingsDirty(state);
            namespace fs = std::filesystem;
            std::string destinationProbeError;
            const auto destinationStatus =
                Platform::FileSystem::ProbePath(destDir, &destinationProbeError);
            bool destinationCreateFailed = false;
            if (destinationStatus == Platform::FileSystem::PathStatus::Missing) {
                destinationCreateFailed = !Platform::FileSystem::CreateDirectories(destDir);
            }
            if (destinationStatus == Platform::FileSystem::PathStatus::Error && !destinationCreateFailed) {
                { char tsb1[512]; std::snprintf(tsb1, sizeof(tsb1), L(TR_MkdirFailFmt), destinationProbeError.c_str());
                state.setTransferStatus(tsb1, AppState::TransferStatusKind::Error); }
            } else if (destinationCreateFailed) {
                { char tsb2[512]; std::snprintf(tsb2, sizeof(tsb2), L(TR_MkdirFailFmt), "create directories failed");
                state.setTransferStatus(tsb2, AppState::TransferStatusKind::Error); }
            } else if (!Platform::FileSystem::IsDirectory(destDir)) {
                state.setTransferStatus(L(TR_NotFolder), AppState::TransferStatusKind::Error);
            } else {
                // Execute export in background thread
                state.transferInProgress = true;
                state.transferCompletedCount = 0;
                state.transferErrorCount = 0;
                state.setTransferStatus(L(Export_Exporting), AppState::TransferStatusKind::Neutral);

                auto strategies2 = TransferEngine::getFolderStrategyList();
                auto behaviors2 = TransferEngine::getExistingBehaviorChoices();
                FolderNamingStrategy folderStrat = state.transferFolderStrategy < (int)strategies2.size()
                    ? strategies2[state.transferFolderStrategy].first : FolderNamingStrategy::SingleFolder;
                ExistingFileBehavior existBehav = state.transferExistingBehavior < (int)behaviors2.size()
                    ? behaviors2[state.transferExistingBehavior].second : ExistingFileBehavior::SkipExisting;
                bool keepSource = state.transferUseSourceFormat;

                std::thread([&state, destDir, folderStrat, existBehav, keepSource]() {
                    namespace fs = std::filesystem;
                    int completed = 0, errors = 0;
                    for (const auto& rec : state.transferSelectedFiles) {
                        if (!state.transferInProgress) break; // cancelled

                        // Generate destination path
                        std::unordered_map<std::string, std::string> meta;
                        meta["Category"] = rec.category;
                        meta["Library"] = rec.album;
                        meta["Designer"] = rec.artist;
                        std::string errMsg;
                        std::string subFolder = TransferEngine::generateDestFolderPath(folderStrat, destDir, meta, errMsg);
                        if (subFolder.empty()) subFolder = destDir;

                        // Ensure subfolder exists
                        Platform::FileSystem::CreateDirectories(subFolder);

                        TransferPrefs transferPrefs = TransferEngine::getDefaultPrefs();
                        std::string safeFileName =
                            TransferEngine::buildSafeDestinationFileName(rec.fileName, transferPrefs);
                        std::string destFile = subFolder;
                        if (destFile.back() != '/' && destFile.back() != '\\') destFile += "\\";
                        destFile += safeFileName;

                        TransferDestinationResolution resolved =
                            TransferEngine::resolveExistingDestinationPath(destFile, existBehav);
                        if (!resolved.errorMessage.empty()) {
                            errors++;
                            state.setTransferStatus("Error: " + rec.fileName + " - " + resolved.errorMessage, AppState::TransferStatusKind::Neutral);
                            state.transferErrorCount = errors;
                            continue;
                        }
                        if (!resolved.shouldCopy) {
                            completed++;
                            state.transferCompletedCount = completed;
                            continue;
                        }
                        destFile = resolved.path;

                        // Simple file copy (format conversion is P2 — current scope: copy as-is)
                        try {
                            std::string copyError;
                            if (!Platform::FileSystem::CopyFile(
                                    rec.filePath, destFile, resolved.wouldOverwrite, &copyError)) {
                                errors++;
                                state.setTransferStatusFmt(LStr::TR_CopyErrFmt, AppState::TransferStatusKind::Error,
                                                         rec.fileName, copyError);
                            } else {
                                completed++;
                            }
                        } catch (const std::exception& ex) {
                            errors++;
                            state.setTransferStatusFmt(LStr::TR_CopyExFmt, AppState::TransferStatusKind::Fail,
                                                     rec.fileName, std::string(ex.what()));
                        }
                        state.transferCompletedCount = completed;
                        state.transferErrorCount = errors;
                    }
                    state.transferInProgress = false;
                    if (errors == 0) {
                        state.setTransferStatusCount(LStr::TR_DoneAllFmt, AppState::TransferStatusKind::Neutral, completed, -1);
                    } else {
                        state.setTransferStatusCount(LStr::TR_DoneMixedFmt, AppState::TransferStatusKind::Fail, completed, errors);  // P1-1: mixed = failures present -> red
                    }
                }).detach();
            }
            }
        }
        if (!destValid) ImGui::EndDisabled();

        ImGui::SameLine();
        if (state.transferInProgress) {
            if (ImGui::Button(L(Cancel), ImVec2(100, 0))) {
                state.transferInProgress = false;
                state.setTransferStatus(L(Export_Cancelled), AppState::TransferStatusKind::Neutral);
            }
        } else {
            if (ImGui::Button(L(Close), ImVec2(100, 0))) {
                ImGui::CloseCurrentPopup();
            }
        }
        }
        ImGui::EndPopup();
    }

    // Batch Rename Dialog

    if (state.showBatchRenameDialog) {
        ImGui::OpenPopup(L(Dlg_BatchOp));
        state.showBatchRenameDialog = false;
    }
    if (BeginTransientScrollbarPopupModal(L(Dlg_BatchOp), nullptr, ImGuiWindowFlags_None)) {
        { ReadingTextScope _readingPopup;  // dialog body is a reading surface
        EscClosePopup();
        ImGui::SetWindowSize(ImVec2(900, 650), ImGuiCond_FirstUseEver);

        // Selected files count
        auto selectedRecords = state.getSelectedRecords();
        ImGui::TextColored(ImVec4(0.4f, 0.8f, 1.0f, 1.0f),
            L(Dlg_SelectedNFiles), (int)selectedRecords.size());

        // Tab bar for Rename vs Metadata
        if (ImGui::BeginTabBar("##BatchOperationTabs")) {
            if (ImGui::BeginTabItem(L(Main_BatchRenameTab))) {
                state.batchDialogTab = 0;
                ImGui::EndTabItem();
            }
            if (ImGui::BeginTabItem(L(Main_BatchMetaTab))) {
                state.batchDialogTab = 1;
                ImGui::EndTabItem();
            }
            ImGui::EndTabBar();
        }

        ImGui::Separator();

        if (state.batchDialogTab == 0) {
// RENAME TAB
        // Two columns: left for rules, right for preview
        float rulesPanelWidth = 380.0f;

        // Left panel - Rule configuration
        BeginTransientScrollbarChild("RulesPanel", ImVec2(rulesPanelWidth, 450), true);
        {
            ImGui::Text("%s", L(Batch_RenameRules));
            ImGui::Separator();

            // Mode selection
            ImGui::Text("%s", L(Batch_OpMode));
            ImGui::SetNextItemWidth(300);
            {
                // Build \0-separated combo string from localized mode names
                auto modeLabel = [](int i) { return GetRenameModeName((AppState::RenameMode)i); };
                std::string comboStr;
                for (int i = 0; i < (int)AppState::RenameMode::COUNT; ++i) {
                    comboStr += modeLabel(i);
                    comboStr += '\0';
                }
                comboStr += '\0';
                ImGui::Combo("##RenameMode", &state.renameModeIndex, comboStr.c_str());
            }

            // Mode description
            AppState::RenameMode currentMode = (AppState::RenameMode)state.renameModeIndex;
            ImGui::TextColored(ImVec4(0.6f, 0.6f, 0.6f, 1.0f), L(Main_CheckedItemFmt),
                GetRenameModeDescription(currentMode));

            ImGui::Spacing();

            // Input fields based on mode
            bool needsSearch = (currentMode == AppState::RenameMode::TextReplace ||
                               currentMode == AppState::RenameMode::RegexReplace ||
                               currentMode == AppState::RenameMode::DeleteText ||
                               currentMode == AppState::RenameMode::AddPrefix ||
                               currentMode == AppState::RenameMode::AddSuffix ||
                               currentMode == AppState::RenameMode::DeleteStartChars ||
                               currentMode == AppState::RenameMode::DeleteEndChars ||
                               currentMode == AppState::RenameMode::DeleteFromMatchedTextToEnd ||
                               currentMode == AppState::RenameMode::RemoveExtraBrackets ||
                               currentMode == AppState::RenameMode::InsertSequenceNumber ||
                               currentMode == AppState::RenameMode::ReplaceSpaces);

            bool needsReplace = (currentMode == AppState::RenameMode::TextReplace ||
                                currentMode == AppState::RenameMode::RegexReplace ||
                                currentMode == AppState::RenameMode::InsertSequenceNumber);
            const bool needsOccurrenceSelector =
                (currentMode == AppState::RenameMode::DeleteFromMatchedTextToEnd);

            if (needsSearch) {
                const char* searchLabel = L(RenField_Search);
                if (currentMode == AppState::RenameMode::AddPrefix ||
                    currentMode == AppState::RenameMode::AddSuffix) {
                    searchLabel = currentMode == AppState::RenameMode::AddPrefix ? L(RenField_Prefix) : L(RenField_Suffix);
                } else if (currentMode == AppState::RenameMode::DeleteStartChars ||
                          currentMode == AppState::RenameMode::DeleteEndChars) {
                    searchLabel = L(RenField_CharCount);
                } else if (currentMode == AppState::RenameMode::RemoveExtraBrackets) {
                    searchLabel = L(RenField_BracketType);
                } else if (currentMode == AppState::RenameMode::InsertSequenceNumber) {
                    searchLabel = L(RenField_SeqFormat);
                } else if (currentMode == AppState::RenameMode::ReplaceSpaces) {
                    searchLabel = L(RenField_ReplaceChar);
                } else if (currentMode == AppState::RenameMode::DeleteFromMatchedTextToEnd) {
                    searchLabel = L(Ren_HitWord);
                }

                ImGui::Text("%s", searchLabel);
                ImGui::SetNextItemWidth(300);
                ImGui::InputText("##RenameSearch", state.renameSearchBuffer, sizeof(state.renameSearchBuffer));
            }

            if (needsReplace) {
                const char* replaceLabel = L(RenField_ReplaceWith);
                if (currentMode == AppState::RenameMode::InsertSequenceNumber) {
                    replaceLabel = L(RenField_Position);
                }
                ImGui::Text("%s", replaceLabel);
                ImGui::SetNextItemWidth(300);
                ImGui::InputText("##RenameReplace", state.renameReplaceBuffer, sizeof(state.renameReplaceBuffer));
            }
            if (needsOccurrenceSelector) {
                ImGui::TextUnformatted(L(Main_MatchLocationLabel));
                std::string occurrenceItems = L(Occur_FirstHit);
                occurrenceItems.push_back('\0');
                occurrenceItems += L(Occur_LastHit);
                occurrenceItems.push_back('\0');
                occurrenceItems.push_back('\0');
                ImGui::SetNextItemWidth(300);
                ImGui::Combo("##RenameDeleteToEndOccurrence", &state.renameDeleteToEndOccurrence, occurrenceItems.c_str());
            }

            ImGui::Spacing();

            // Add to queue button
            if (ImGui::Button(L(Batch_AddToQueue), ImVec2(150, 0))) {
                AppState::RenameRule rule;
                rule.mode = currentMode;
                rule.searchText = state.renameSearchBuffer;
                rule.replaceText = needsOccurrenceSelector
                    ? (state.renameDeleteToEndOccurrence == 0 ? "first" : "last")
                    : state.renameReplaceBuffer;

                // Generate description
                const char* modeName = GetRenameModeName(currentMode);
                if (currentMode == AppState::RenameMode::TextReplace ||
                    currentMode == AppState::RenameMode::RegexReplace) {
                    rule.description = std::string(modeName) + ": '" + rule.searchText + "' -> '" + rule.replaceText + "'";
                } else if (currentMode == AppState::RenameMode::AddPrefix ||
                          currentMode == AppState::RenameMode::AddSuffix) {
                    rule.description = std::string(modeName) + ": '" + rule.searchText + "'";
                } else if (currentMode == AppState::RenameMode::DeleteStartChars ||
                          currentMode == AppState::RenameMode::DeleteEndChars) {
                    rule.description = std::string(modeName) + ": " + rule.searchText;
                } else if (currentMode == AppState::RenameMode::DeleteFromMatchedTextToEnd) {
                    rule.description = std::string(modeName) + ": '" + rule.searchText + "' (" +
                        (rule.replaceText == "last" ? L(Occur_LastHit) : L(Occur_FirstHit)) + ")";
                } else {
                    rule.description = modeName;
                }

                state.renameRuleQueue.push_back(rule);

                // Clear input fields
                memset(state.renameSearchBuffer, 0, sizeof(state.renameSearchBuffer));
                memset(state.renameReplaceBuffer, 0, sizeof(state.renameReplaceBuffer));
            }

            ImGui::Separator();

            // Queue display
            ImGui::Text(L(Main_ActionQueueFmt), (int)state.renameRuleQueue.size());

            BeginTransientScrollbarChild("RuleQueue", ImVec2(0, 150), true);
            for (int i = 0; i < (int)state.renameRuleQueue.size(); ++i) {
                ImGui::PushID(i);
                bool selected = (i == state.renameRuleSelectedIndex);
                if (ImGui::Selectable(state.renameRuleQueue[i].description.c_str(), selected)) {
                    state.renameRuleSelectedIndex = i;
                }
                ImGui::PopID();
            }
            ImGui::EndChild();

            // Queue control buttons
            if (ImGui::Button(L(Main_MoveUpBtn))) {
                if (state.renameRuleSelectedIndex > 0 &&
                    state.renameRuleSelectedIndex < (int)state.renameRuleQueue.size()) {
                    std::swap(state.renameRuleQueue[state.renameRuleSelectedIndex],
                             state.renameRuleQueue[state.renameRuleSelectedIndex - 1]);
                    state.renameRuleSelectedIndex--;
                }
            }
            ImGui::SameLine();
            if (ImGui::Button(L(Main_MoveDownBtn))) {
                if (state.renameRuleSelectedIndex >= 0 &&
                    state.renameRuleSelectedIndex < (int)state.renameRuleQueue.size() - 1) {
                    std::swap(state.renameRuleQueue[state.renameRuleSelectedIndex],
                             state.renameRuleQueue[state.renameRuleSelectedIndex + 1]);
                    state.renameRuleSelectedIndex++;
                }
            }
            ImGui::SameLine();
            if (ImGui::Button(L(Main_RemoveBtn2))) {
                if (state.renameRuleSelectedIndex >= 0 &&
                    state.renameRuleSelectedIndex < (int)state.renameRuleQueue.size()) {
                    state.renameRuleQueue.erase(state.renameRuleQueue.begin() + state.renameRuleSelectedIndex);
                    if (state.renameRuleSelectedIndex >= (int)state.renameRuleQueue.size()) {
                        state.renameRuleSelectedIndex = (int)state.renameRuleQueue.size() - 1;
                    }
                }
            }
            ImGui::SameLine();
            if (ImGui::Button(L(Main_ClearQueueBtn))) {
                state.renameRuleQueue.clear();
                state.renameRuleSelectedIndex = -1;
            }
        }
        ImGui::EndChild();

        ImGui::SameLine();

        // Right panel - Preview
        BeginTransientScrollbarChild("PreviewPanel", ImVec2(0, 450), true);
        {
            // Generate preview button
            if (ImGui::Button(L(Batch_GenPreview))) {
                GenerateBatchRenamePreview(state);
            }
            ImGui::SameLine();

            // Stats
            if (!state.renamePreviewList.empty()) {
                int okCount = 0, conflictCount = 0, unchangedCount = 0;
                for (const auto& p : state.renamePreviewList) {
                    if (p.status == u8"OK") okCount++;
                    else if (p.status == L(RenStatus_NoChange)) unchangedCount++;
                    else conflictCount++;
                }
                ImGui::Text(L(RenPreview_Summary), okCount, unchangedCount, conflictCount);
            }

            ImGui::Separator();

            // Preview table
            if (BeginTransientScrollbarTable("RenamePreviewTable", 3,
                ImGuiTableFlags_RowBg | ImGuiTableFlags_Borders | ImGuiTableFlags_ScrollY | ImGuiTableFlags_Resizable,
                ImVec2(0, 380))) {

                ImGui::TableSetupScrollFreeze(0, 1);
                ImGui::TableSetupColumn(L(RenTable_Status), ImGuiTableColumnFlags_WidthFixed, 80);
                ImGui::TableSetupColumn(L(RenTable_OldName), ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableSetupColumn(L(RenTable_NewName), ImGuiTableColumnFlags_WidthStretch);
                ImGui::TableHeadersRow();

                for (const auto& preview : state.renamePreviewList) {
                    ImGui::TableNextRow();

                    // Status column with color
                    ImGui::TableNextColumn();
                    if (preview.status == u8"OK") {
                        ImGui::TextColored(ImVec4(0.4f, 1.0f, 0.4f, 1.0f), "%s", preview.status.c_str());
                    } else if (preview.status == L(RenStatus_NoChange) || preview.status == L(RenStatus_NoRules)) {
                        ImGui::TextColored(ImVec4(0.6f, 0.6f, 0.6f, 1.0f), "%s", preview.status.c_str());
                    } else {
                        ImGui::TextColored(ImVec4(1.0f, 0.4f, 0.4f, 1.0f), "%s", preview.status.c_str());
                    }

                    // Old name
                    ImGui::TableNextColumn();
                    ImGui::Text("%s", preview.oldName.c_str());

                    // New name
                    ImGui::TableNextColumn();
                    if (preview.willChange) {
                        ImGui::TextColored(ImVec4(0.4f, 0.8f, 1.0f, 1.0f), "%s", preview.newName.c_str());
                    } else {
                        ImGui::TextDisabled("%s", preview.newName.c_str());
                    }
                }

                ImGui::EndTable();
            }
        }
        ImGui::EndChild();

        ImGui::Separator();

        // Bottom buttons
        bool hasPreview = !state.renamePreviewList.empty();
        bool hasOK = false;
        for (const auto& p : state.renamePreviewList) {
            if (p.status == u8"OK" && p.willChange) { hasOK = true; break; }
        }

        ImGui::BeginDisabled(!hasPreview || !hasOK);
        if (ImGui::Button(L(Batch_ExecRename), ImVec2(150, 0))) {
            ExecuteBatchRename(state);
            state.renameRuleQueue.clear();
            state.renamePreviewList.clear();
            ImGui::CloseCurrentPopup();
        }
        ImGui::EndDisabled();

        ImGui::SameLine();
        if (ImGui::Button(L(Close), ImVec2(100, 0))) {
            state.renameRuleQueue.clear();
            state.renamePreviewList.clear();
            ImGui::CloseCurrentPopup();
        }

        } else {
// METADATA TAB
        static std::string s_batchMetaSaveMsg;
        static int s_batchMetaSaveSuccess = 0, s_batchMetaSaveSkipped = 0, s_batchMetaSaveFailed = 0;
        ImGui::Text("%s", L(Batch_EditMeta));
        ImGui::Separator();

        ImGui::Spacing();

        // Mode: Replace or Append
        ImGui::Text("%s", L(Batch_WriteMode));
        ImGui::RadioButton(L(Batch_Replace), &state.batchMetaAppendMode, 0);
        ImGui::SameLine();
        ImGui::RadioButton(L(Batch_Append), &state.batchMetaAppendMode, 1);

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        // Description field
        ImGui::Text("%s", L(Batch_Description));
        ImGui::SetNextItemWidth(600);
        ImGui::InputTextMultiline("##BatchMetaDesc", state.batchMetaDescription,
            sizeof(state.batchMetaDescription), ImVec2(600, 80));

        ImGui::Spacing();

        // Keywords field
        ImGui::Text("%s", L(Batch_Keywords));
        ImGui::SetNextItemWidth(600);
        ImGui::InputTextMultiline("##BatchMetaKeywords", state.batchMetaKeywords,
            sizeof(state.batchMetaKeywords), ImVec2(600, 60));

        ImGui::Spacing();

        // Category field
        ImGui::Text("%s", L(Batch_Category));
        ImGui::SetNextItemWidth(400);
        ImGui::InputText("##BatchMetaCategory", state.batchMetaCategory,
            sizeof(state.batchMetaCategory));

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        // Preview of affected files
        ImGui::Text("%s", L(Batch_AffectedFiles));
        BeginTransientScrollbarChild("##MetadataAffectedFiles", ImVec2(0, 200), true);
        for (const auto& record : selectedRecords) {
            fs::path p = Utf8ToPathMain(record.filePath);
            ImGui::BulletText("%s", PathToUtf8Main(p.filename()).c_str());
        }
        ImGui::EndChild();

        ImGui::Spacing();

        // Action buttons
        bool hasContent = (strlen(state.batchMetaDescription) > 0 ||
                          strlen(state.batchMetaKeywords) > 0 ||
                          strlen(state.batchMetaCategory) > 0);

        ImGui::BeginDisabled(!hasContent || selectedRecords.empty());
        if (ImGui::Button(L(Batch_ApplyMeta), ImVec2(150, 0))) {
            s_batchMetaSaveSuccess = 0;
            s_batchMetaSaveSkipped = 0;
            s_batchMetaSaveFailed = 0;
            auto undoOp = std::make_unique<MetadataPatchOp>();
            undoOp->operationName = "Batch edit metadata";
            std::vector<std::pair<int64_t, MetadataEditPatch>> patchItems;
            bool abort = false;
                for (const auto& record : selectedRecords) {
                    if (!Platform::FileSystem::Exists(record.filePath)) {
                        s_batchMetaSaveSkipped++;
                        continue;
                    }
                    std::string newDesc = state.batchMetaDescription;
                    std::string newKeywords = state.batchMetaKeywords;
                    std::string newCategory = state.batchMetaCategory;
                    if (state.batchMetaAppendMode) {
                        if (!newDesc.empty() && !record.description.empty()) newDesc = record.description + " " + newDesc;
                        else if (newDesc.empty()) newDesc = record.description;
                        if (!newKeywords.empty() && !record.keywords.empty()) newKeywords = record.keywords + ", " + newKeywords;
                        else if (newKeywords.empty()) newKeywords = record.keywords;
                        if (!newCategory.empty() && !record.category.empty()) newCategory = record.category + "/" + newCategory;
                        else if (newCategory.empty()) newCategory = record.category;
                    }
                    MetadataEditPatch patch;
                    // In replace mode, only patch fields that have content — empty = skip, not clear.
                    // In append mode, newXxx already carries the original value for empty inputs.
                    if (!newDesc.empty())     patch.setDescription(newDesc);
                    if (!newKeywords.empty()) patch.setKeywords(newKeywords);
                    if (!newCategory.empty()) patch.setCategory(newCategory);
                    MetadataPatchEntry entry;
                    entry.fileId = record.id;
                    entry.oldValues = {{"description", record.description}, {"keywords", record.keywords}, {"category", record.category}};
                    entry.newValues = {{"description", newDesc}, {"keywords", newKeywords}, {"category", newCategory}};
                    undoOp->entries.push_back(std::move(entry));
                    if (!patch.isEmpty()) {
                        patchItems.push_back({record.id, patch});
                    }
                }
                if (!patchItems.empty()) {
                    BatchMetadataApplyResult res = state.database.applyMetadataPatchMany(patchItems);
                    if (res.failed == 0) {
                        s_batchMetaSaveSuccess = res.success;
                    } else {
                        s_batchMetaSaveSuccess = 0;
                        s_batchMetaSaveFailed += (int)patchItems.size();
                        undoOp->entries.clear();
                        abort = true;
                    }
                }
                if (abort) {
                    s_batchMetaSaveSuccess = 0;
                    s_batchMetaSaveFailed = (int)selectedRecords.size();
                    undoOp->entries.clear();
                }
            if (s_batchMetaSaveSuccess > 0) {
                state.undoStack.push(std::move(undoOp));
                state.database.invalidateFacetQueryCache();
                RefreshSearchResults(state, false);
            }
            s_batchMetaSaveMsg = std::to_string(s_batchMetaSaveSuccess) + u8" 成功";
            if (s_batchMetaSaveSkipped > 0)
                s_batchMetaSaveMsg += u8", " + std::to_string(s_batchMetaSaveSkipped) + u8" 跳过（文件不在磁盘上）";
            if (s_batchMetaSaveFailed > 0)
                s_batchMetaSaveMsg += u8", " + std::to_string(s_batchMetaSaveFailed) + u8" 失败";
            if (s_batchMetaSaveFailed == 0) {
                memset(state.batchMetaDescription, 0, sizeof(state.batchMetaDescription));
                memset(state.batchMetaKeywords, 0, sizeof(state.batchMetaKeywords));
                memset(state.batchMetaCategory, 0, sizeof(state.batchMetaCategory));
            }
        }
        ImGui::EndDisabled();
        if (!s_batchMetaSaveMsg.empty()) {
            ImGui::TextColored(
                s_batchMetaSaveFailed > 0 ? ImVec4(1.0f, 0.4f, 0.4f, 1.0f) :
                (s_batchMetaSaveSkipped > 0 ? ImVec4(1.0f, 0.8f, 0.2f, 1.0f) : ImVec4(0.4f, 0.9f, 0.4f, 1.0f)),
                "%s", s_batchMetaSaveMsg.c_str());
        }
        if (ImGui::Button(L(Close), ImVec2(100, 0))) {
            s_batchMetaSaveMsg.clear();
            ImGui::CloseCurrentPopup();
        }
        }  // End of tab content

        }
        ImGui::EndPopup();
    }

    // Handle popup dialogs
    // About window
    if (state.showAboutWindow) {
        ImGui::OpenPopup("##AboutAuro");
        state.showAboutWindow = false;
    }
    if (BeginTransientScrollbarPopupModal("##AboutAuro", nullptr, ImGuiWindowFlags_AlwaysAutoResize | ImGuiWindowFlags_NoTitleBar)) {
        { ReadingTextScope _readingPopup;  // dialog body is a reading surface
        EscClosePopup();
        ImGui::Text(L(Main_AppNameBrand));        ImGui::SameLine();
        ImGui::TextDisabled(L(Main_VersionFmt), SOUNDMANAGER_VERSION_STRING);
        ImGui::Separator();
        ImGui::TextWrapped(L(Main_UpdateCenterMovedNote));
        if (ImGui::Button(L(Main_OpenUpdateCenterBtn), ImVec2(160.0f, 0.0f))) {
            state.showUpdateCenter = true;
            ImGui::CloseCurrentPopup();
        }
        ImGui::Separator();
        if (ImGui::Button(L(OK), ImVec2(120, 0))) {
            ImGui::CloseCurrentPopup();
        }
        }
        ImGui::EndPopup();
    }

    #if defined(ARIS_UPDATE_NOTICE_QA)
    static const std::string qaUpdateNoticeState = [] {
        const char* value = std::getenv("ARIS_UPDATE_NOTICE_QA_STATE");
        return value ? std::string(value) : std::string{};
    }();
    if (!qaUpdateNoticeState.empty()) {
        const char* theme = std::getenv("ARIS_UPDATE_NOTICE_QA_THEME");
        if (theme && std::strcmp(theme, "lapis") == 0) ApplyTheme(AppTheme::LapisBlue);
        if (theme && std::strcmp(theme, "light") == 0) ApplyTheme(AppTheme::JadeMist);
    }
    if (!qaUpdateNoticeState.empty()) state.showUpdateCenter = true;
    #endif

    {
        const auto updateState = aris::update::GetHarkenSearchUpdateUiState();
        const bool readyChanged = updateState.phase == aris::update::HarkenSearchUpdateUiPhase::Ready &&
            (g_lastHarkenSearchUpdateUiState.phase != updateState.phase ||
             g_lastHarkenSearchUpdateUiState.candidateVersion != updateState.candidateVersion);
        if (readyChanged && !state.updateNoticeSeenThisSession) {
            state.showUpdateCenter = true;
            state.updateNoticeSeenThisSession = true;
            g_releaseNotesUiState.showHistory = false;
        }
        g_lastHarkenSearchUpdateUiState = updateState;
        if (g_releaseNotesUiState.wantOpen) {
            state.showUpdateCenter = true;
            g_releaseNotesUiState.showHistory = true;
            g_releaseNotesUiState.wantOpen = false;
        }
    }

    if (state.showUpdateCenter) {
        LoadReleaseNotesFromExeDir();
        auto updateState = aris::update::GetHarkenSearchUpdateUiState();
        aris::update::SyncHarkenSearchCandidateReleaseNotes(g_releaseNotesUiState,
            updateState.candidateVersion, updateState.candidateReleaseNotes,
            updateState.candidateReleaseNotesFailed);
        #if defined(ARIS_UPDATE_NOTICE_QA)
        if (!qaUpdateNoticeState.empty()) {
            updateState.currentVersion = "1.0.24";
            updateState.candidateVersion = "1.0.25-long-version-cjk-版本-emoji";
            updateState.lastError.clear();
            g_releaseNotesUiState.showHistory = qaUpdateNoticeState == "history";
            if (qaUpdateNoticeState == "checking") updateState.phase = aris::update::HarkenSearchUpdateUiPhase::Checking;
            else if (qaUpdateNoticeState == "latest") updateState.phase = aris::update::HarkenSearchUpdateUiPhase::Idle;
            else if (qaUpdateNoticeState == "available") updateState.phase = aris::update::HarkenSearchUpdateUiPhase::Ready;
            else if (qaUpdateNoticeState == "downloading") {
                updateState.phase = aris::update::HarkenSearchUpdateUiPhase::Downloading;
                updateState.downloadedBytes = 56U * 1024U * 1024U;
                updateState.totalBytes = 132U * 1024U * 1024U;
            } else if (qaUpdateNoticeState == "restarting") updateState.phase = aris::update::HarkenSearchUpdateUiPhase::Restarting;
            else if (qaUpdateNoticeState == "error") {
                updateState.phase = aris::update::HarkenSearchUpdateUiPhase::Error;
                updateState.lastError = "runtime pair mismatch: Bootstrap signature rejected; 请重新下载安装包后重试。";
            }
            if (qaUpdateNoticeState == "history" && g_releaseNotesUiState.releases.empty()) {
                g_releaseNotesUiState.hasData = true;
                g_releaseNotesUiState.message.clear();
                g_releaseNotesUiState.releases = {
                    {"v1.0.25", "2026-08-11", u8"自动更新闭环与主题一致性",
                     {"Harken Search Team"}, {{"fix", u8"更新中心", u8"七种状态和完整历史内容均可到达。", "Harken Search Team"}}, {}},
                    {"v1.0.24", "2026-08-04", u8"真实发布链路验证",
                     {"Harken Search Team"}, {{"fix", u8"安装", u8"失败时保留确切诊断现场。", "Harken Search Team"}}, {}},
                };
                g_releaseNotesUiState.expandedReleaseVersion = "v1.0.25";
            }
        }
        #endif
        static std::uint64_t updateNoticeOperationGeneration = 0;
        const aris::update::HarkenSearchUpdateNoticeActions actions{
            [] {
                const bool accepted = aris::update::RequestHarkenSearchUpdateCheck();
                if (accepted) ++updateNoticeOperationGeneration;
                return accepted;
            },
            [] {
                const bool accepted = aris::update::ConfirmHarkenSearchUpdateRestart();
                if (accepted) ++updateNoticeOperationGeneration;
                return accepted;
            },
        };
        const aris::update::HarkenSearchUpdateNoticePresentation presentation{
            kUpdateCenterWindowId,
            u8"检查更新",
            u8"重试",
            u8"立即重启更新",
            u8"稍后",
            updateState.downloadedBytes,
            updateState.totalBytes,
            updateState.lastError,
            updateNoticeOperationGeneration,
        };
        aris::update::RenderHarkenSearchUpdateNoticeUi(
            state.showUpdateCenter,
            g_releaseNotesUiState,
            updateState,
            actions,
            presentation);
    } else {
        g_releaseNotesUiState.showHistory = false;
        g_releaseNotesUiState.expandedReleaseVersion.clear();
    }

