                ImGui::BeginDisabled(!canRebuildCurrent);
                if (ImGui::MenuItem(L(Misc_RebuildCurrentWave))) {
                    RebuildCurrentFileMainWaveform(state);
                }
                ImGui::EndDisabled();
                if (g_selectedWaveformRebuildWorkflow.currentFileTaskActive()) {
                    ImGui::TextUnformatted(L(Main_RebuildingWaveform));
                    if (ImGui::SmallButton(L(Main_CancelCurrentRebuildBtn))) {
                        state.waveformWorker.cancelAllPending();
                        g_selectedWaveformRebuildWorkflow.cancel();
                        ShowCurrentFileWaveformRebuildToast(state);
                    }
                }

                ImGui::BeginDisabled(!canRebuild || state.waveformRebuildActive);
                if (ImGui::MenuItem(L(Main_MenuFillMissingWave))) {
                    state.audioEngine.stop();
                    StartIncrementalWaveformRebuild(state);
                }
                if (ImGui::MenuItem(L(Main_MenuRebuildAllWave))) {
                    state.audioEngine.stop();
                    StartFullWaveformRebuild(state);
                }
                ImGui::EndDisabled();
                if (state.waveformRebuildActive) {
                    const int64_t displayProgress = state.waveformRebuildTotal > 0
                        ? std::min(state.waveformRebuildProgress, state.waveformRebuildTotal)
                        : state.waveformRebuildProgress;
                    float prog = state.waveformRebuildTotal > 0
                        ? (float)displayProgress / (float)state.waveformRebuildTotal : 0.0f;
                    char buf[192];
                    if (state.waveformRebuildSkipped > 0 || state.waveformRebuildFailed > 0)
                        snprintf(buf, sizeof(buf), u8"%lld / %lld (skip: %d, fail: %d)",
                                 (long long)displayProgress, (long long)state.waveformRebuildTotal,
                                 state.waveformRebuildSkipped, state.waveformRebuildFailed);
                    else
                        snprintf(buf, sizeof(buf), u8"%lld / %lld",
                                 (long long)displayProgress, (long long)state.waveformRebuildTotal);
                    DrawUnifiedProgressBar(prog, ImVec2(-1, 0), buf);
                    if (ImGui::SmallButton(L(Main_CancelRebuildBtn))) state.waveformRebuildCancel = true;
                }
