            ImGui::Separator();

            // Randomize — full database random sample (respects current filters)
            if (ImGui::MenuItem(L(Edit_RandomSort))) {
                SearchFilter randFilter = BuildCurrentDbFilter(state);
                state.searchResults = state.database.searchFilesRandom(randFilter, AppState::PAGE_SIZE);
                state.bumpSearchResultsGen();
                FilterResultsByFileType(state);
                state.totalFileCount = state.database.searchFilesCount(randFilter);
                state.loadedCount = (int)state.searchResults.size();
                state.hasMoreResults = false;
                state.clearPendingWaveforms();
                    state.syncToTab();
            }

            if (ImGui::MenuItem(L(Edit_NextRandom), GetShortcutString(ShortcutAction::RandomFile).c_str(), false, !state.searchResults.empty())) {
                if (!state.searchResults.empty()) {
                    std::random_device rd;
                    std::mt19937 g(rd());
                    std::uniform_int_distribution<int> dist(0, (int)state.searchResults.size() - 1);
                    int randomIdx = dist(g);
                    state.selectedIndicesSet.clear();
                    state.selectedIndicesSet.insert(randomIdx);
                    state.beginAudioTargetFromSearchResult(randomIdx);
                    const auto& record = state.searchResults[randomIdx];
                    state.audioEngine.loadFileAsync(record.filePath, state.settings.autoplayOnSelect);
                    ScheduleDeferredWaveformDetail(state, record.filePath, AppState::WAVEFORM_DEFAULT_DETAIL_PEAKS);
                    ResetWaveformZoom(state);
                    if (state.settings.autoplayOnSelect)
                        MarkFilePlayed(state, record.filePath, record.id);
                    state.syncToTab();
                }
            }

            ImGui::Separator();

