    static bool s_bottomStatusWasScanning = false;
    const bool bottomStatusScanningNow = state.isScanning.load();
    if (HarkenSearch::ShouldPublishScanCompletionToast(
            s_bottomStatusWasScanning,
            bottomStatusScanningNow,
            state.scanTotal.load(),
            state.scanCompletionPending.load(std::memory_order_acquire),
            state.scanStopDisposition.load(std::memory_order_acquire))) {
        state.scanSummaryToastUntil = ImGui::GetTime() + 10.0;
    }
    s_bottomStatusWasScanning = bottomStatusScanningNow;

    auto BuildInlineBottomStatusText = [&]() -> std::string {
        std::string status;
        if (bottomStatusScanningNow) {
            int scanProgress = state.scanProgress.load();
            int scanTotal = state.scanTotal.load();
            int scanAdded = state.scanAddedCount.load();
            int scanUpdated = state.scanUpdatedCount.load();
            std::string sbScanFile = state.getScanFile();
            bool sbPostPhase = (scanTotal > 0 && scanProgress >= scanTotal - 1)
                && (!sbScanFile.empty() && sbScanFile[0] != '[' && sbScanFile.find("...") != std::string::npos);
            if (sbPostPhase) {
                status = std::string(L(Scan_PostProcessing));
                if (!sbScanFile.empty()) {
                    status += " | ";
                    status += sbScanFile;
                }
            } else {
                const char* phaseLabel = L(Scan_Scanning);
                switch (state.scanPhase.load(std::memory_order_relaxed)) {
                    case AppState::ScanPhase::InitialImport:   phaseLabel = L(ScanPhase_InitImport); break;
                    case AppState::ScanPhase::IncrementalScan: phaseLabel = L(ScanPhase_Incremental); break;
                    case AppState::ScanPhase::RemoveMissing:   phaseLabel = L(ScanPhase_RemoveMissing); break;
                    case AppState::ScanPhase::RenameOrMove:    phaseLabel = L(ScanPhase_RenameMove); break;
                    case AppState::ScanPhase::FailureRetry:    phaseLabel = L(ScanPhase_FailRetry); break;
                    default: break;
                }
                char progressBuf[96];
                snprintf(progressBuf, sizeof(progressBuf), "%s %d/%d", phaseLabel, scanProgress, scanTotal);
                status = progressBuf;
                if (scanAdded > 0 || scanUpdated > 0) {
                    char deltaBuf[96];
                    snprintf(deltaBuf, sizeof(deltaBuf), " | +%d ~%d", scanAdded, scanUpdated);
                    status += deltaBuf;
                }
                std::string currentFile = state.getScanFile();
                if (currentFile.length() > 54) {
                    currentFile = "..." + currentFile.substr(currentFile.length() - 51);
                }
                if (!currentFile.empty()) {
                    status += " | ";
                    status += currentFile;
                }
            }
        } else if (state.scanCompletionPending.load(std::memory_order_acquire) &&
                   state.scanTotal.load() > 0) {
            status = std::string(u8"本次入库收尾中") + " | " + BuildScanCompletionPendingLabel(state);
        } else if (state.scanSummaryToastUntil > ImGui::GetTime() && state.scanTotal.load() > 0) {
            char ingestCountBuf[24];
            snprintf(ingestCountBuf, sizeof(ingestCountBuf), "%d", state.scanIngestedCount.load());
            const std::string statusIngestDuration =
                FormatDurationMsCompact(state.scanCompletionDurationMs.load(std::memory_order_acquire));
            status = std::string(u8"扫描完成 | 入库 ") + ingestCountBuf + u8" | 耗时 " + statusIngestDuration;
            if (!state.settings.cacheWaveformsOnScan) {
                status += u8" | mini 波形后台补齐";
            }
            if (state.showPostScanSimilarityIndexNotice) {
                status += std::string(" | ") + L(Scan_SimIndexRunningBg);
            }
        } else if (state.showPostScanSimilarityIndexNotice) {
            status = L(Scan_SimIndexRunningBg);
        } else if (state.ftsRebuildProgress.load() >= 0.0f) {
            float p = state.ftsRebuildProgress.load();
            const char* phase = (p < 0.05f) ? L(ScanPhase_Preparing) : (p > 0.90f) ? L(ScanPhase_ReplacingIdx) : L(ScanPhase_RebuildSearch);
            char pctBuf[64];
            snprintf(pctBuf, sizeof(pctBuf), "%s %.0f%%", phase, p * 100.0f);
            status = pctBuf;
        } else if (state.bgCacheRunning.load()) {
            char bgBuf[128];
            snprintf(bgBuf, sizeof(bgBuf), L(Scan_BackgroundIdx), state.bgCacheProgress.load(), state.bgCacheTotal.load());
            status = bgBuf;
        } else if (state.loadErrorToastUntil > ImGui::GetTime() && !state.loadErrorToast.empty()) {
            status = std::string(u8"⚠ ") + state.loadErrorToast;
        } else {
            int64_t totalFilesCount = state.database.getFileCount();
            const ImVec4 statusCountText = ImVec4(1.0f, 1.0f, 1.0f, 0.98f);
            if (state.totalFileCount == -1) {
                char spinnerChar = "|/-\\"[(int)(ImGui::GetTime() * 10.0f) & 3];
                char countBuf[96];
                snprintf(countBuf, sizeof(countBuf), L(Scan_CountingResults), spinnerChar);
                status = countBuf;
            } else {
                char dbBuf[96];
                snprintf(dbBuf, sizeof(dbBuf), "%s %lld %s", L(Status_Database), (long long)totalFilesCount, L(Status_Files));
                status = dbBuf;
                if (state.viewMode == ViewMode::Browser) {
                    char browserBuf[96];
                    snprintf(browserBuf, sizeof(browserBuf), L(Status_CurrentDir), (int)state.fileBrowser.activeEntries().size());
                    status += " | ";
                    status += browserBuf;
                } else {
                    char displayBuf[64];
                    snprintf(displayBuf, sizeof(displayBuf), "%s %lld", L(Status_Display), (long long)state.totalFileCount);
                    status += " | ";
                    status += displayBuf;
                }
            }
        }
        return status;
    };
    auto BuildTransportItemCountText = [&]() -> std::string {
        if (bottomStatusScanningNow ||
            (state.scanCompletionPending.load(std::memory_order_acquire) && state.scanTotal.load() > 0) ||
            (state.scanSummaryToastUntil > ImGui::GetTime() && state.scanTotal.load() > 0) ||
            state.showPostScanSimilarityIndexNotice ||
            state.batchFeatureExtracting.load() ||
            state.ftsRebuildProgress.load() >= 0.0f ||
            state.bgCacheRunning.load() ||
            (state.loadErrorToastUntil > ImGui::GetTime() && !state.loadErrorToast.empty()) ||
            state.totalFileCount == -1) {
            return std::string();
        }

        int64_t countToShow = 0;
        if (state.viewMode == ViewMode::Browser) {
            countToShow = (int64_t)state.fileBrowser.activeEntries().size();
        } else {
            countToShow = (long long)state.totalFileCount;
        }

        char countBuf[64];
        snprintf(countBuf, sizeof(countBuf), "%lld %s", (long long)countToShow, L(Status_Files));
        return countBuf;
    };

    // BOTTOM - Waveform and Transport (with resizable splitter)
    // The center may end above a bottom Dock band; the waveform always starts
